activate_schema.body:
{
    metadata <- read_store_metadata(connection)
    active_build_digest <- scalar_character(metadata$active_build_digest)
    build_digest <- scalar_character(schema$manifest$fingerprints$build_digest)
    if (identical(active_build_digest, build_digest)) {
        return(invisible(schema))
    }
    now <- as.POSIXct(now, tz = "UTC")
    register_schema_version(connection, schema, now)
    manifest <- schema$manifest
    fingerprints <- manifest$fingerprints
    sql <- paste0("UPDATE ", quote_identifier(connection, "_graft_store"), " SET active_structural_digest = ?, active_build_digest = ?, ", "source_digest = ?, build_digest = ?, manifest_json = ?, updated_at = ?")
    DBI::dbExecute(connection, sql, params = list(scalar_character(fingerprints$structural_digest), build_digest, scalar_character(fingerprints$source_digest), build_digest, canonical_manifest_json(manifest), now))
    invisible(schema)
}

as_graft_provenance.body:
{
    if (!is_graft_provenance(x)) {
        abort_validation_error(paste0("`", arg, "` must be a GraftProvenance object."), field = arg, rule = "graft_provenance", observed_value = x)
    }
    validation_error <- tryCatch({
        S7::validate(x)
        NULL
    }, error = function(error) error)
    if (!is.null(validation_error)) {
        abort_validation_error(paste0("`", arg, "` is an invalid GraftProvenance object; create a new one."), field = arg, rule = "graft_provenance_valid", observed_value = x, parent = validation_error)
    }
    x
}

as_graft_read_store_internal.body:
{
    if (S7::S7_inherits(x, GraftStore)) {
        return(as_graft_store_internal(x, arg))
    }
    if (!is_graft_view(x)) {
        abort_backend_error(paste0("`", arg, "` must be a GraftStore or GraftView object."), operation = "validate_read_store", argument = arg)
    }
    view <- as_graft_view(x, arg)
    state <- graft_view_state(view)
    source <- as_graft_store_internal(state$store, arg)
    snapshot <- as_graft_snapshot(state$snapshot, "view snapshot")
    schema <- validate_graft_snapshot_mapping(source, snapshot)
    if (!identical(canonical_manifest_json(schema$manifest), canonical_manifest_json(state$schema$manifest))) {
        abort_snapshot_error("graft_snapshot_schema_error", "The view schema no longer matches its registered snapshot schema.", schema_build_digest = snapshot@schema_build_digest)
    }
    new_graft_snapshot_backend(source, schema, snapshot_data(snapshot))
}

as_graft_schema_internal.body:
{
    if (!S7::S7_inherits(x, GraftSchema)) {
        abort_schema_error(paste0("`", arg, "` must be a GraftSchema object."), argument = arg)
    }
    error <- tryCatch({
        S7::validate(x)
        NULL
    }, error = identity)
    if (!is.null(error)) {
        abort_schema_integrity(paste0("`", arg, "` is an invalid GraftSchema object."), argument = arg, parent = error)
    }
    state <- graft_schema_state(x)
    path <- if (is.na(state$path)) 
        NULL
    else state$path
    compiled_schema <- new_compiled_schema(graft_schema_manifest(x), path)
    validate_manifest_integrity(compiled_schema)
    compiled_schema
}

as_graft_schema_object.body:
{
    if (S7::S7_inherits(x, GraftSchema)) {
        as_graft_schema_internal(x, arg)
        return(x)
    }
    abort_schema_error(paste0("`", arg, "` must be a GraftSchema object."), argument = arg)
}

as_graft_snapshot.body:
{
    if (!S7::S7_inherits(x, GraftSnapshot)) {
        abort_snapshot_error("graft_snapshot_invalid", paste0("`", arg, "` must be a GraftSnapshot object."), argument = arg)
    }
    data <- snapshot_data(x)
    shape_valid <- is.list(data) && !is.object(data) && identical(names(data), snapshot_field_names())
    expected <- if (shape_valid) {
        tryCatch(snapshot_digest(data), error = function(error) NA_character_)
    }
    else {
        NA_character_
    }
    observed <- if (shape_valid) 
        data$snapshot_id
    else NA_character_
    if (shape_valid && !identical(observed, expected)) {
        abort_snapshot_error("graft_snapshot_tampered", "The snapshot digest is invalid; create a new snapshot.", expected_snapshot_id = expected, observed_snapshot_id = observed)
    }
    error <- tryCatch({
        S7::validate(x)
        NULL
    }, error = identity)
    if (!is.null(error)) {
        abort_snapshot_error("graft_snapshot_invalid", paste0("`", arg, "` is invalid; create a new snapshot."), argument = arg, parent = error)
    }
    x
}

as_graft_store_internal.body:
{
    if (!S7::S7_inherits(x, GraftStore)) {
        abort_backend_error(paste0("`", arg, "` must be a GraftStore object."), operation = "validate_store", argument = arg)
    }
    error <- tryCatch({
        S7::validate(x)
        NULL
    }, error = identity)
    if (!is.null(error)) {
        abort_backend_error(paste0("`", arg, "` is an invalid GraftStore object."), operation = "validate_store", argument = arg, parent = error)
    }
    backend <- graft_store_state(x)$backend
    validate_store_backend(backend, require_open = require_open, arg = arg)
    backend
}

as_graft_view.body:
{
    if (!is_graft_view(x)) {
        abort_snapshot_error("graft_snapshot_invalid", paste0("`", arg, "` must be a GraftView object."), argument = arg)
    }
    state <- graft_view_state(x)
    if (is.list(state) && !is.object(state) && identical(names(state), c("store", "snapshot", "schema")) && S7::S7_inherits(state$snapshot, GraftSnapshot)) {
        snapshot <- as_graft_snapshot(state$snapshot, paste0(arg, " snapshot"))
        if (S7::S7_inherits(state$store, GraftStore)) {
            store_id <- tryCatch(state$store@id, error = function(.x) NA_character_)
            if (is_nonempty_string(store_id) && !identical(snapshot@store_id, store_id)) {
                abort_snapshot_error("graft_snapshot_store_mismatch", "The snapshot belongs to a different Graft store.", expected_store_id = snapshot@store_id, observed_store_id = store_id)
            }
        }
    }
    error <- tryCatch({
        S7::validate(x)
        NULL
    }, error = identity)
    if (!is.null(error)) {
        abort_snapshot_error("graft_snapshot_invalid", paste0("`", arg, "` is an invalid GraftView object."), argument = arg, parent = error)
    }
    x
}

assemble_candidate_authority.body:
{
    rows <- staged$rows
    validate_candidate_execution_rows(rows, plan)
    changed <- rows$action %in% c("insert", "update")
    revisions <- assemble_candidate_revisions(rows[changed, , drop = FALSE], batch, plan, recorded_at, commit_order)
    revision_ids <- rows$expected_revision_id
    revision_ids[changed] <- revisions$revision_id
    if (anyNA(revision_ids) || !all(nzchar(revision_ids))) {
        abort_commit_plan("graft_commit_plan_invalid", "Every staged observation must resolve to a revision ID.")
    }
    origin_index <- match(candidate_authority_key(rows), candidate_authority_key(staged$origins))
    if (anyNA(origin_index)) {
        abort_commit_plan("graft_commit_plan_invalid", "Every staged observation must have one accepted origin decision.")
    }
    dispositions <- unname(c(insert = "inserted", update = "updated", match = "matched")[rows$action])
    observations <- data.frame(record_id = rows$record_id, class = rows$class, batch_id = rep(batch$batch_id, nrow(rows)), disposition = dispositions, revision_id = revision_ids, origin_key = staged$origins$origin_key[origin_index], matched_by = rows$identity_reason, identity_evidence_json = rows$identity_evidence, observed_at = rep(recorded_at, nrow(rows)), stringsAsFactors = FALSE)
    list(revisions = revisions, heads = assemble_candidate_heads(revisions, recorded_at), observations = observations, identifiers = assemble_candidate_identifiers(staged$identifiers, recorded_at), origins = assemble_candidate_origins(staged$origins, batch, recorded_at))
}

assemble_candidate_heads.body:
{
