}

assemble_candidate_identifiers.body:
{
    if (nrow(identifiers) == 0L) {
        return(data.frame(record_id = character(), class = character(), namespace = character(), value = character(), normalized_value = character(), status = character(), assigned_by = character(), confidence = numeric(), created_at = as.POSIXct(numeric(), origin = "1970-01-01", tz = "UTC"), stringsAsFactors = FALSE))
    }
    result <- data.frame(record_id = identifiers$record_id, class = identifiers$class, namespace = identifiers$namespace, value = identifiers$value, normalized_value = identifiers$normalized_value, status = identifiers$status, assigned_by = identifiers$assigned_by, confidence = rep(1, nrow(identifiers)), created_at = rep(recorded_at, nrow(identifiers)), stringsAsFactors = FALSE)
