    }
    result <- data.frame(record_id = origins$record_id, class = origins$class, producer = origins$producer, origin_key = origins$origin_key, first_batch_id = rep(batch$batch_id, nrow(origins)), created_at = rep(recorded_at, nrow(origins)), stringsAsFactors = FALSE)
    key <- paste(result$class, result$producer, result$origin_key, sep = "\037")
    result[!duplicated(key), , drop = FALSE]
}

assemble_candidate_revisions.body:
{
    if (nrow(rows) == 0L) {
        return(empty_candidate_revisions())
    }
    revision_number <- ifelse(is.na(rows$expected_revision_number), 1, as.numeric(rows$expected_revision_number) + 1)
    prior_revision_id <- rows$expected_revision_id
    revision_id <- vapply(seq_len(nrow(rows)), function(index) {
        deterministic_graft_id("GraftRecordRevision", list(batch_id = batch$batch_id, schema_build_digest = plan@schema_build_digest, record_id = rows$record_id[[index]], class = rows$class[[index]], revision_number = as.character(revision_number[[index]]), content_digest = rows$content_digest[[index]], prior_revision_id = prior_revision_id[[index]]))
    }, character(1))
    data.frame(revision_id = revision_id, record_id = rows$record_id, class = rows$class, batch_id = rep(batch$batch_id, nrow(rows)), schema_build_digest = rep(plan@schema_build_digest, nrow(rows)), revision_number = revision_number, operation = rows$action, payload_json = rows$payload_json, content_digest = rows$content_digest, changed_fields_json = rows$changed_fields_json, prior_revision_id = prior_revision_id, recorded_at = rep(recorded_at, nrow(rows)), commit_order = rep(commit_order, nrow(rows)), 
        stringsAsFactors = FALSE)
}

augment_manifest_with_definitions.body:
{
    manifest <- compiled$manifest
    if (!is.null(manifest$classes[[graft_definition_class_name]])) {
        return(compiled)
    }
    taken_views <- vapply(manifest$classes, function(class) scalar_character(class$view), character(1))
    if (graft_definition_view_name %in% taken_views) {
        abort_schema_error(paste0("The view name `", graft_definition_view_name, "` is reserved for the graft definition system class."), field = "view", rule = "reserved_definition_view")
    }
    manifest$classes[[graft_definition_class_name]] <- graft_definition_class_contract()
    manifest$fingerprints$structural_digest <- manifest_structural_digest(manifest)
    manifest$fingerprints$build_digest <- manifest_build_digest(manifest)
    compiled$manifest <- manifest
    compiled
}

