canonical_exact_numeric_lexeme.body:
{
    negative <- startsWith(value, "-")
    unsigned <- sub("^[+-]", "", value)
    whole <- if (grepl(".", unsigned, fixed = TRUE)) {
        sub("\\..*$", "", unsigned)
    }
    else {
        unsigned
    }
    fraction <- if (decimal && grepl(".", unsigned, fixed = TRUE)) {
        sub("^[^.]*\\.", "", unsigned)
    }
    else {
        ""
    }
    whole <- sub("^0+", "", whole)
    if (!nzchar(whole)) {
        whole <- "0"
    }
    fraction <- sub("0+$", "", fraction)
    canonical <- paste0(whole, if (nzchar(fraction)) 
        paste0(".", fraction)
    else "")
    if (negative && !identical(canonical, "0")) {
        paste0("-", canonical)
    }
    else {
        canonical
    }
}

