canonical_schema_value.body:
{
    if (!is.list(value) || is.null(value)) {
        return(value)
    }
    value_names <- names(value)
    if (!is.null(value_names) && all(nzchar(value_names))) {
        value <- value[order(value_names, method = "radix")]
    }
    lapply(value, canonical_schema_value)
}

canonical_slot_scalar.body:
{
    type <- canonical_slot_type(slot)
    if (is.null(value) || length(value) == 0L) {
        return(NULL)
    }
    if (length(value) != 1L) {
        abort_backend_error("A scalar logical-record value must contain exactly one item.", operation = "canonicalize_record", field = scalar_character(slot$name), value_length = length(value))
    }
    if (scalar_logical(slot$object_reference)) {
        if (is.na(value)) {
            return(NA_character_)
        }
        return(as.character(value))
    }
    if (is.na(value)) {
        return(switch(type, BOOLEAN = NA, BIGINT = NA_real_, DOUBLE = NA_real_, DECIMAL = NA_real_, DATE = as.Date(NA_character_), TIME = NA_character_, TIMESTAMP = as.POSIXct(NA_real_, origin = "1970-01-01", tz = "UTC"), NA_character_))
    }
    switch(type, BOOLEAN = as.logical(value), BIGINT = as.numeric(value), DOUBLE = as.numeric(value), DECIMAL = as.numeric(value), DATE = as.Date(value), TIME = canonical_time_value(value), TIMESTAMP = as.POSIXct(value, tz = "UTC"), as.character(value))
}

canonical_slot_type.body:
{
    type <- toupper(scalar_character(slot$relational_type, "VARCHAR"))
    if (scalar_logical(slot$object_reference) && !identical(type, "VARCHAR")) {
        slot_name <- scalar_character(slot$name, "<unknown>")
        abort_schema_error(paste0("Object-reference slot `", slot_name, "` must use relational type `VARCHAR`, not `", type, "`."), operation = operation, field = slot_name, relational_type = type, rule = "object_reference_varchar")
    }
    type
}

canonical_slot_value.body:
{
    canonical_slot_type(slot)
    if (!scalar_logical(slot$multivalued)) {
        return(canonical_slot_scalar(value, slot))
    }
    if (is.null(value) || length(value) == 0L) {
        return(list())
    }
    values <- lapply(seq_along(value), function(index) canonical_slot_scalar(value[[index]], slot))
    if (!scalar_logical(slot$ordered)) {
        keys <- vapply(values, canonical_json, character(1))
        values <- values[order(keys, method = "radix")]
    }
    unname(values)
}

canonical_time_value.body:
{
    seconds <- if (inherits(value, "difftime")) {
        as.numeric(value, units = "secs")
    }
    else if (is.numeric(value)) {
        as.numeric(value)
    }
    else {
        parts <- as.numeric(strsplit(as.character(value), ":", fixed = TRUE)[[1L]])
        if (length(parts) < 2L || length(parts) > 3L || anyNA(parts)) {
            abort_backend_error("A TIME value could not be canonicalized.", operation = "canonicalize_record", observed_value = value)
        }
        parts[[1L]] * 3600 + parts[[2L]] * 60 + if (length(parts) == 3L) {
            parts[[3L]]
        }
        else {
            0
        }
    }
    total_microseconds <- round(seconds * 1e+06)
    if (!is.finite(total_microseconds) || total_microseconds < 0 || total_microseconds >= 86400 * 1e+06) {
        abort_backend_error("A TIME value must be between 00:00:00 and 23:59:59.999999.", operation = "canonicalize_record", observed_value = value)
    }
    hour <- floor(total_microseconds/(3600 * 1e+06))
    remainder <- total_microseconds - hour * 3600 * 1e+06
    minute <- floor(remainder/(60 * 1e+06))
    remainder <- remainder - minute * 60 * 1e+06
    second <- floor(remainder/1e+06)
    microsecond <- as.integer(remainder - second * 1e+06)
    result <- sprintf("%02d:%02d:%02d", hour, minute, second)
    if (microsecond > 0L) {
        fraction <- sub("0+$", "", sprintf("%06d", microsecond))
        result <- paste0(result, ".", fraction)
    }
    result
}

