{
    switch(validation_slot_type(slot), VARCHAR = if (scalar_character(slot$range) %in% c("uri", "uriorcurie")) {
        coerce_linkml_reference(x, scalar_character(slot$range))
    } else if (is.factor(x)) {
        as.character(x)
