coerce_date.body:
{
    if (inherits(x, "Date")) {
        days <- as.numeric(x)
        rendered <- tryCatch(suppressWarnings(format(x, "%Y-%m-%d")), error = function(error) NULL)
        invalid <- is.null(rendered) || length(rendered) != length(days) || any(!is.na(days) & (!is.finite(days) | days != trunc(days) | is.na(rendered) | !grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$", rendered)))
        if (invalid) {
            return(NULL)
        }
        return(x)
    }
    if (!is.character(x)) {
        return(NULL)
    }
    valid_format <- is.na(x) | grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$", x)
    if (!all(valid_format)) {
        return(NULL)
    }
    value <- tryCatch(suppressWarnings(as.Date(x, format = "%Y-%m-%d")), error = function(error) NULL)
    if (is.null(value)) {
        return(NULL)
    }
    rendered <- format(value, "%Y-%m-%d")
    if (any(!is.na(x) & (is.na(value) | rendered != x))) {
        return(NULL)
    }
    value
}

coerce_exact_numeric.body:
{
    if (is.factor(x)) {
        x <- as.character(x)
    }
    if (!is.numeric(x) && !is.character(x)) {
        return(NULL)
    }
    if (is.numeric(x)) {
        missing <- is.na(x)
        invalid <- !missing & (!is.finite(x) | x != trunc(x) | abs(x) > 2^53 - 1)
        if (any(invalid)) {
            return(NULL)
        }
        values <- rep(NA_character_, length(x))
        values[!missing] <- sprintf("%.0f", x[!missing])
        values[!missing & x == 0] <- "0"
        if (!all(vapply(values[!missing], exact_numeric_lexeme_fits_storage, logical(1), integer = integer))) {
            return(NULL)
        }
        return(values)
    }
    values <- trimws(x)
    missing <- is.na(values)
    pattern <- if (integer) {
        "^[+-]?[0-9]+$"
    }
    else {
        "^[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)$"
    }
    if (any(!missing & !grepl(pattern, values, perl = TRUE))) {
        return(NULL)
    }
    result <- rep(NA_character_, length(values))
    result[!missing] <- vapply(values[!missing], canonical_exact_numeric_lexeme, character(1), decimal = !integer)
    if (!all(vapply(result[!missing], exact_numeric_lexeme_fits_storage, logical(1), integer = integer))) {
        return(NULL)
    }
    result
}

coerce_historical_value.body:
{
    type <- toupper(scalar_character(slot$duckdb_type, scalar_character(slot$relational_type, "VARCHAR")))
    object_reference <- scalar_logical(slot$object_reference)
    if (is.null(value)) {
        return(NULL)
    }
    if (object_reference) {
        canonical <- canonical_slot_value(value, slot)
        if (scalar_logical(slot$multivalued)) {
            return(as.character(unlist(canonical, use.names = FALSE)))
        }
        return(canonical)
    }
    convert <- function(item) {
        if (is.null(item)) {
            return(NULL)
        }
        if (identical(type, "BOOLEAN")) {
            return(as.logical(item))
        }
        if (identical(type, "BIGINT")) {
            if (is.character(item)) {
                number <- suppressWarnings(as.numeric(item))
                exact <- is.finite(number) && abs(number) <= 2^53 && identical(format(number, scientific = FALSE, trim = TRUE), item)
                if (!exact) {
                  return(item)
                }
                return(number)
            }
            return(as.numeric(item))
        }
        if (identical(type, "DECIMAL")) {
            if (is.character(item)) {
                return(item)
            }
            return(as.numeric(item))
        }
        if (identical(type, "DOUBLE")) {
            return(as.numeric(item))
        }
        if (identical(type, "DATE")) {
            return(as.Date(item))
        }
        if (identical(type, "TIME")) {
            parts <- as.numeric(strsplit(as.character(item), ":", fixed = TRUE)[[1L]])
            seconds <- parts[[1L]] * 3600 + parts[[2L]] * 60
            if (length(parts) == 3L) {
                seconds <- seconds + parts[[3L]]
            }
            return(as.difftime(seconds, units = "secs"))
        }
        if (identical(type, "TIMESTAMP")) {
            return(as.POSIXct(item, format = "%Y-%m-%dT%H:%M:%OSZ", tz = "UTC"))
        }
        as.character(item)
    }
    if (scalar_logical(slot$multivalued)) {
        if (length(value) == 0L) {
            if (identical(type, "BOOLEAN")) {
                return(logical())
            }
            if (type %in% c("BIGINT", "DECIMAL")) {
                return(character())
            }
            if (identical(type, "DOUBLE")) {
                return(numeric())
            }
            if (identical(type, "DATE")) {
                return(as.Date(character()))
            }
            if (identical(type, "TIME")) {
                return(as.difftime(numeric(), units = "secs"))
            }
            if (identical(type, "TIMESTAMP")) {
                return(as.POSIXct(character(), tz = "UTC"))
            }
            return(character())
        }
        return(unname(do.call(c, lapply(value, convert))))
    }
    convert(value)
}

