coerce_timestamp.body:
{
    if (length(datetime_format) == 0L || is.na(datetime_format) || !nzchar(datetime_format)) {
        datetime_format <- NULL
    }
    if (inherits(x, "POSIXt")) {
        value <- tryCatch(suppressWarnings(as.POSIXct(x, tz = "UTC")), error = function(error) NULL)
        if (is.null(value)) {
            return(NULL)
        }
        seconds <- as.numeric(value)
        whole_seconds <- trunc(seconds)
        microsecond_value <- whole_seconds + round((seconds - whole_seconds) * 1e+06)/1e+06
        rendered <- tryCatch(suppressWarnings(format(value, "%Y-%m-%dT%H:%M:%S", tz = "UTC")), error = function(error) NULL)
        invalid <- is.null(rendered) || length(rendered) != length(seconds) || any(!is.na(seconds) & (!is.finite(seconds) | seconds != microsecond_value | is.na(rendered) | !grepl(paste0("^[0-9]{4}-[0-9]{2}-[0-9]{2}T", "[0-9]{2}:[0-9]{2}:[0-9]{2}$"), rendered)))
        if (invalid) {
            return(NULL)
        }
        return(value)
    }
    if (inherits(x, "Date")) {
        if (!is.null(datetime_format)) {
            return(NULL)
        }
        value <- coerce_date(x)
        if (is.null(value)) {
            return(NULL)
        }
        return(coerce_timestamp(as.POSIXct(value, tz = "UTC")))
    }
    if (!is.character(x)) {
        return(NULL)
    }
    if (!is.null(datetime_format)) {
        pattern <- switch(datetime_format, offset = offset_datetime_pattern(), local_utc = local_datetime_pattern(), NULL)
        if (is.null(pattern) || any(!is.na(x) & !grepl(pattern, x, perl = TRUE))) {
            return(NULL)
        }
    }
    seconds <- vapply(x, coerce_timestamp_character_value, numeric(1), datetime_format = datetime_format, USE.NAMES = FALSE)
    if (any(!is.na(x) & is.na(seconds))) {
        return(NULL)
    }
    as.POSIXct(seconds, origin = "1970-01-01", tz = "UTC")
}

coerce_timestamp_character_value.body:
{
    if (is.na(value)) {
        return(NA_real_)
    }
    offset <- identical(datetime_format, "offset") || (is.null(datetime_format) && grepl(offset_datetime_pattern(), value, perl = TRUE))
    local_utc <- identical(datetime_format, "local_utc") || (is.null(datetime_format) && grepl(local_datetime_pattern(), value, perl = TRUE))
    space_utc <- is.null(datetime_format) && grepl(space_datetime_pattern(), value, perl = TRUE)
    date_utc <- is.null(datetime_format) && grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$", value, perl = TRUE)
    if (!offset && !local_utc && !space_utc && !date_utc) {
        return(NA_real_)
    }
    tryCatch(suppressWarnings({
        parsed <- if (offset) {
            match <- regexec("([+-])([0-9]{2}):([0-9]{2})$", value, perl = TRUE)
            parts <- regmatches(value, match)[[1L]]
            if (length(parts) == 0L) {
                local_value <- sub("Z$", "", value)
                offset_seconds <- 0
            }
            else {
                local_value <- substr(value, 1L, nchar(value) - nchar(parts[[1L]]))
                direction <- if (identical(parts[[2L]], "+")) 
                  1
                else -1
                offset_seconds <- direction * (as.numeric(parts[[3L]]) * 3600 + as.numeric(parts[[4L]]) * 60)
            }
            local_time <- strptime(local_value, "%Y-%m-%dT%H:%M:%OS", tz = "UTC")
            as.numeric(as.POSIXct(local_time, tz = "UTC")) - offset_seconds
        }
        else if (local_utc) {
            strptime(value, "%Y-%m-%dT%H:%M:%OS", tz = "UTC")
        }
        else if (space_utc) {
            strptime(value, "%Y-%m-%d %H:%M:%OS", tz = "UTC")
        }
        else {
            strptime(value, "%Y-%m-%d", tz = "UTC")
        }
        as.numeric(as.POSIXct(parsed, origin = "1970-01-01", tz = "UTC"))
    }), error = function(error) NA_real_)
}

