        validate_commit_plan_replay(plan, replay)
        replay$replay <- TRUE
        signal_batch_replay(replay)
        return(replay)
    }
    commit_prepared_plan(store = store, batch = batch, staged = execution$staged, plan = plan, started = started)
}

