    tables <- lapply(classes, function(class_name) {
        contract <- manifest$classes[[class_name]]
        original_table <- commons_original_table(original, class_name)
        commons_class_dictionary_table(class_name, contract, original_table, definitions[definitions$target == class_name, , drop = FALSE], manifest)
    })
    relation_tables <- lapply(relations, function(relation) {
        commons_relation_dictionary_table(manifest, relation, definitions[definitions$target == scalar_character(relation$view), , drop = FALSE])
    })
    document <- list(`$version` = "0.1.0", name = commons_dictionary_prose(original, "name"), description = commons_dictionary_prose(original, "description"), details = commons_dictionary_prose(original, "details"), tables = c(tables, relation_tables), relationships = commons_dictionary_relationships(original, classes), glossary = if (is.null(original)) NULL else original$glossary)
    commons_compact(document)
}

commons_dictionary_column.body:
{
    column <- list(name = name, type = commons_definition_type(slot), label = if (is.null(original)) NULL else original$label, description = if (is.null(original)) NULL else original$description, details = if (is.null(original)) NULL else original$details, units = if (is.null(original)) NULL else original$units, constraints = if (is.null(original)) NULL else original$constraints)
    enum <- scalar_character(slot$enum)
    if (!is.na(enum)) {
        values <- manifest$enums[[enum]]$permissible_values
        column$values <- vapply(values, function(value) {
            scalar_character(value$value)
        }, character(1))
    }
    commons_compact(column)
}

commons_dictionary_relationships.body:
{
    if (is.null(document) || is.null(document$relationships)) {
        return(NULL)
    }
    Filter(function(relationship) {
        tables <- commons_relationship_tables(document, relationship)
        length(tables) > 0L && all(tables %in% classes)
    }, document$relationships)
}

commons_materialize.body:
{
    manifest <- source$schema$manifest
    tables <- stats::setNames(lapply(classes, function(class_name) {
        definition_target_frame(source, manifest$classes[[class_name]])
    }), classes)
    relations <- Filter(function(relation) {
        owner <- scalar_character(relation$owner_class)
        slot_name <- scalar_character(relation$slot)
        slot <- manifest$classes[[owner]]$slots[[slot_name]]
        owner %in% classes && !scalar_logical(slot$sensitive)
    }, manifest$relations)
    for (relation in relations) {
        tables[[scalar_character(relation$view)]] <- commons_relation_frame(source, relation)
    }
    list(tables = tables, relations = relations)
}

commons_original_column.body:
{
