        return(NULL)
    }
    indexes <- which(vapply(table$columns, function(column) identical(scalar_character(column$name), slot_name), logical(1)))
    if (length(indexes) != 1L) 
        NULL
    else table$columns[[indexes]]
}

commons_original_table.body:
{
