    columns <- if (identical(scalar_character(relation$kind), "object")) {
        list(list(name = "id", type = "string"), list(name = "subject", type = "string"), list(name = "object", type = commons_definition_type(slot)), list(name = "position", type = "number"), list(name = "created_at", type = "datetime"))
    }
    else {
        list(list(name = "owner_id", type = "string"), list(name = "position", type = "number"), list(name = "value", type = commons_definition_type(slot)))
    }
    list(name = scalar_character(relation$view), description = paste0("Normalized accepted values for `", scalar_character(relation$name), "`."), columns = columns, definitions = lapply(seq_len(nrow(definitions)), function(index) {
        commons_definition_dictionary_row(definitions[index, , drop = FALSE])
    }))
