commons_relationship_tables.body:
{
    pairs <- relationship$pairs
    if (!is.null(pairs) && length(pairs) > 0L) {
        return(unique(unlist(lapply(pairs, function(pair) {
            c(pair$left$table, pair$right$table)
        }), use.names = FALSE)))
    }
    join <- scalar_character(relationship$join)
    if (is.na(join) || is.null(document$tables)) {
        return(character())
    }
    table_names <- vapply(document$tables, function(table) scalar_character(table$name), "")
    unique(table_names[vapply(table_names, function(table) grepl(paste0(table, "."), join, fixed = TRUE), logical(1))])
}

commons_selected_classes.body:
{
