    if (!is.character(classes) || length(classes) == 0L || anyNA(classes) || !all(nzchar(classes)) || anyDuplicated(classes)) {
        abort_validation_error("`classes` must contain unique, non-empty public class names.", field = "classes", rule = "commons_classes", observed_value = classes)
    }
    unavailable <- setdiff(classes, available)
    if (length(unavailable) > 0L) {
        abort_validation_error(paste0("Unknown or non-public Commons class selection: ", paste(unavailable, collapse = ", "), "."), field = "classes", rule = "commons_classes", observed_value = unavailable)
    }
    sort(classes, method = "radix")
}

