component_resolution_evidence.body:
{
    evidence <- list()
    supplied <- rows[candidates$supplied_valid[rows] & candidates$supplied_id[rows] == record_id]
    for (row in supplied) {
        evidence[[length(evidence) + 1L]] <- list(kind = "supplied_id", class = candidates$class[[row]], input_row = candidates$input_row[[row]], record_id = record_id)
    }
    stored_identifier_keys <- paste(stored_identifiers$class, stored_identifiers$namespace, stored_identifiers$normalized_value, stored_identifiers$record_id, sep = "\037")
    candidate_identifier_keys <- paste(identifiers$class, identifiers$namespace, identifiers$normalized_value, record_id, sep = "\037")
    matched_identifiers <- identifiers[identifiers$candidate_id %in% rows & candidate_identifier_keys %in% stored_identifier_keys, , drop = FALSE]
    for (index in seq_len(nrow(matched_identifiers))) {
        evidence[[length(evidence) + 1L]] <- list(kind = "external_identifier", class = matched_identifiers$class[[index]], input_row = matched_identifiers$input_row[[index]], slot = matched_identifiers$slot[[index]], namespace = matched_identifiers$namespace[[index]], normalized_value = matched_identifiers$normalized_value[[index]], record_id = record_id)
    }
    stored_origin_keys <- paste(stored_origins$class, stored_origins$producer, stored_origins$origin_key, stored_origins$record_id, sep = "\037")
    candidate_origin_keys <- paste(candidates$class[rows], producer, candidates$origin_key[rows], record_id, sep = "\037")
    matched_origins <- rows[candidate_origin_keys %in% stored_origin_keys]
    for (row in matched_origins) {
        evidence[[length(evidence) + 1L]] <- list(kind = "origin", class = candidates$class[[row]], input_row = candidates$input_row[[row]], producer = producer, origin_key = candidates$origin_key[[row]], record_id = record_id)
    }
    keys <- vapply(evidence, canonical_json, character(1))
    unname(evidence[order(keys, method = "radix")])
}

contract_definition_records.body:
{
    document <- manifest$dictionary$document
    if (is.null(document)) {
        return(NULL)
    }
    rows <- list()
    for (table in document$tables) {
        definitions <- table$definitions
        if (is.null(definitions)) {
            next
        }
        for (definition in definitions) {
            rows[[length(rows) + 1L]] <- data.frame(name = scalar_character(definition$name), target = scalar_character(table$name), expr = scalar_character(definition$expr), label = scalar_character(definition$label), description = scalar_character(definition$description), details = scalar_character(definition$details), stringsAsFactors = FALSE)
        }
    }
    if (length(rows) == 0L) {
        return(NULL)
    }
    do.call(rbind, rows)
}

