data_dict_cli_version.body:
{
    result <- run_data_dict_process(cli, "--version", operation = "version")
    if (!identical(result$status, 0L)) {
        abort_schema_error(paste0("Could not determine the data-dict CLI version: ", data_dict_process_diagnostics(result)), cli_path = cli, exit_status = result$status, cli_output = c(result$stdout, result$stderr))
    }
    output <- paste(result$stdout, collapse = "\n")
    match <- regexec("(?:^|[[:space:]])data-dict[[:space:]]+([^[:space:]]+)", output)
    parts <- regmatches(output, match)[[1L]]
    if (length(parts) != 2L || !nzchar(parts[[2L]])) {
        abort_schema_error(paste0("Could not parse the data-dict CLI version from `", output, "`."), cli_path = cli, cli_output = output)
