data_dict_compile_column.body:
{
    if ("fields" %in% names(column)) {
        data_dict_abort("Nested column fields are not supported by the graft-table-v1 profile.", field = paste0(path, ".fields"), rule = "unsupported_nested_fields")
    }
    type <- column$type
    if (!data_dict_is_string(type)) {
        data_dict_abort("Each column must have one resolved canonical type.", field = paste0(path, ".type"), rule = "canonical_column_type")
    }
    parsed <- data_dict_parse_type(type, paste0(path, ".type"))
    time_zone <- column$time_zone
    if (!is.null(time_zone)) {
        if (!identical(parsed$base, "datetime") || !data_dict_is_string(time_zone) || !identical(time_zone, "UTC")) {
            data_dict_abort("The graft-table-v1 profile supports only `time_zone: UTC`.", field = paste0(path, ".time_zone"), rule = "datetime_time_zone", observed_value = time_zone, supported_value = "UTC")
        }
    }
    datetime_format <- if (!identical(parsed$base, "datetime")) {
        NULL
    }
    else if (is.null(time_zone)) {
        "offset"
    }
    else {
        "local_utc"
    }
    display <- data_dict_display(column, path)
    constraints <- data_dict_constraints(column, path)
    identifier <- "primary_key" %in% constraints
    if (identifier && (parsed$multivalued || !identical(parsed$base, "string"))) {
        data_dict_abort("A primary `id` must use scalar type `string`.", field = paste0(path, ".type"), rule = "primary_id_type", observed_value = type)
    }
    if (identifier && identical(display, "restricted")) {
        data_dict_abort("A primary `id` cannot use `display: restricted` in Graft.", field = paste0(path, ".display"), rule = "public_identifier")
    }
    reference <- column$references
    if (identifier && ("foreign_key" %in% constraints || !is.null(reference))) {
        data_dict_abort(paste("A primary `id` cannot also be a foreign key because Graft IDs are", "globally unique across tables."), field = paste0(path, ".constraints"), rule = "primary_foreign_key")
    }
    if ("foreign_key" %in% constraints && is.null(reference)) {
        data_dict_abort("A foreign-key column must include resolved `references` metadata.", field = paste0(path, ".references"), rule = "resolved_foreign_key")
    }
    if (!is.null(reference) && !"foreign_key" %in% constraints) {
        data_dict_abort("Resolved `references` metadata requires a `foreign_key` constraint.", field = paste0(path, ".references"), rule = "resolved_foreign_key")
    }
    object_reference <- "foreign_key" %in% constraints
    target_class <- NULL
    if (object_reference) {
        if (parsed$multivalued) {
            data_dict_abort("A list column cannot be used as a foreign key.", field = paste0(path, ".references"), rule = "scalar_foreign_key")
        }
        if (!identical(parsed$base, "string")) {
            data_dict_abort("A foreign key must use scalar type `string` in Graft.", field = paste0(path, ".type"), rule = "foreign_key_type", observed_value = type)
        }
        if (!is.list(reference) || is.object(reference) || is.null(names(reference)) || anyDuplicated(names(reference)) || !setequal(names(reference), c("table", "column")) || !data_dict_is_string(reference$table) || !data_dict_is_string(reference$column)) {
            data_dict_abort("`references` must resolve to one table and column.", field = paste0(path, ".references"), rule = "resolved_foreign_key")
        }
        if (!(reference$table %in% table_names)) {
            data_dict_abort(paste0("Foreign key target table `", reference$table, "` does not exist."), field = paste0(path, ".references.table"), rule = "foreign_key_target", observed_value = reference$table)
        }
        if (!identical(reference$column, identities[[reference$table]]$column)) {
            data_dict_abort("Foreign keys must reference the target table's primary `id`.", field = paste0(path, ".references.column"), rule = "foreign_key_identity", observed_value = reference$column)
        }
        target_class <- reference$table
    }
    enum <- NULL
    enum_name <- NULL
    if (identical(parsed$base, "enum")) {
        enum_name <- paste(table_name, column_name, "enum", sep = ".")
        enum <- data_dict_enum_contract(enum_name, column$values, paste0(path, ".values"))
    }
    primitive <- data_dict_primitive_contract(parsed$base, path)
    range <- if (object_reference) {
        target_class
    }
    else if (!is.null(enum_name)) {
        enum_name
    }
    else {
        primitive$range
    }
    duckdb_type <- if (object_reference) 
        "VARCHAR"
    else primitive$duckdb_type
    slot <- list(name = column_name, view_column = if (parsed$multivalued) {
        NULL
    } else {
        projection_snake_case(column_name)
    }, range = range, duckdb_type = duckdb_type, required = identifier || "required" %in% constraints, multivalued = parsed$multivalued, ordered = parsed$multivalued, identifier = identifier, object_reference = object_reference, enum = enum_name, meaning = NULL, pattern = NULL, datetime_format = datetime_format, minimum_value = NULL, maximum_value = NULL, external_identifier = NULL, search_weight = NULL, sensitive = identical(display, "restricted"))
    relation <- NULL
    if (parsed$multivalued) {
        relation <- list(name = paste(table_name, column_name, sep = "."), view = paste0(table_view, "__", projection_snake_case(column_name)), owner_class = table_name, owner_view = table_view, slot = column_name, kind = if (object_reference) "object" else "value", ordered = TRUE, predicate = paste0("urn:data-dict:slot:", utils::URLencode(table_name, reserved = TRUE), ".", utils::URLencode(column_name, reserved = TRUE)))
    }
    list(slot = slot, enum = enum, relation = relation)
}

data_dict_compile_table.body:
{
    columns <- table$columns
    path <- paste0("tables[", table_index, "]")
    slots <- stats::setNames(list(), character())
    enums <- stats::setNames(list(), character())
    relations <- list()
    for (column_index in seq_along(columns)) {
        column <- columns[[column_index]]
        column_name <- column_names[[table_name]][[column_index]]
        column_path <- paste0(path, ".columns[", column_index, "]")
        compiled <- data_dict_compile_column(column, column_name, column_path, table_name, table_view, table_names, identities)
        slots[[column_name]] <- compiled$slot
        if (!is.null(compiled$enum)) {
            enums[[compiled$enum$name]] <- compiled$enum
        }
        if (!is.null(compiled$relation)) {
            relations[[length(relations) + 1L]] <- compiled$relation
        }
    }
    candidates <- names(Filter(function(slot) {
        !slot$identifier && !slot$multivalued && !slot$object_reference && !slot$sensitive && identical(slot$duckdb_type, "VARCHAR")
    }, slots))
    preferred <- intersect(c("label", "title", "name", "description"), candidates)
    label_slot <- if (length(preferred) > 0L) {
        preferred[[1L]]
    }
    else if (length(candidates) > 0L) {
        candidates[[1L]]
    }
    else {
        NULL
    }
    class_relations <- as.list(sort(vapply(relations, function(relation) relation$name, character(1)), method = "radix"))
    class <- list(name = table_name, is_a = NULL, ancestors = list(), type_uri = paste0(source$id, "#", utils::URLencode(table_name, reserved = TRUE)), role = "node", statement_shape = NULL, view = table_view, id_policy = "require", id_format = "linkml", label_slot = label_slot, search_slots = as.list(sort(candidates, method = "radix")), origin_key_slots = list(), qualifier_slots = list(), fixed_predicate = NULL, slots = slots, relations = class_relations)
    list(class = class, enums = enums, relations = relations)
}

data_dict_compile_tables.body:
{
    tables <- dictionary$tables
    table_names <- vapply(seq_along(tables), function(index) data_dict_table_name(tables[[index]], index), character(1))
    if (anyDuplicated(table_names)) {
        data_dict_abort("Table names must be unique.", field = "tables", rule = "unique_table_names", observed_value = table_names)
    }
    table_views <- vapply(table_names, projection_snake_case, character(1))
    if (!all(nzchar(table_views)) || any(startsWith(table_views, "_graft_")) || anyDuplicated(tolower(table_views))) {
        data_dict_abort("Table names must produce valid, unique Graft projection names.", field = "tables", rule = "unique_projection_names", observed_value = table_views)
    }
    identities <- vector("list", length(tables))
    names(identities) <- table_names
    column_names <- vector("list", length(tables))
    names(column_names) <- table_names
    for (index in seq_along(tables)) {
        table <- tables[[index]]
        path <- paste0("tables[", index, "]")
        columns <- table$columns
        if (!data_dict_is_array(columns) || length(columns) == 0L) {
            data_dict_abort(paste0("Table `", table_names[[index]], "` must contain columns."), field = paste0(path, ".columns"), rule = "nonempty_columns")
        }
        names_for_table <- vapply(seq_along(columns), function(column_index) {
            data_dict_column_name(columns[[column_index]], path, column_index)
        }, character(1))
        if (anyDuplicated(names_for_table)) {
            data_dict_abort(paste0("Column names for table `", table_names[[index]], "` must be unique."), field = paste0(path, ".columns"), rule = "unique_column_names", observed_value = names_for_table)
        }
        views <- vapply(names_for_table, projection_snake_case, character(1))
        if (!all(nzchar(views)) || anyDuplicated(tolower(views))) {
            data_dict_abort(paste0("Columns for table `", table_names[[index]], "` must produce unique projection names."), field = paste0(path, ".columns"), rule = "unique_projection_columns", observed_value = views)
        }
        primary <- which(vapply(seq_along(columns), function(column_index) {
            "primary_key" %in% data_dict_constraints(columns[[column_index]], paste0(path, ".columns[", column_index, "]"))
        }, logical(1)))
        if (length(primary) != 1L) {
            data_dict_abort(paste0("Table `", table_names[[index]], "` must declare exactly one primary key."), field = paste0(path, ".columns"), rule = "unambiguous_identity", observed_value = names_for_table[primary])
        }
        if (!identical(names_for_table[[primary]], "id")) {
            data_dict_abort(paste0("The primary key for table `", table_names[[index]], "` must be named `id`."), field = paste0(path, ".columns[", primary, "].name"), rule = "primary_id", observed_value = names_for_table[[primary]])
        }
        identities[[table_names[[index]]]] <- list(column = "id", index = primary, type = columns[[primary]]$type)
        column_names[[table_names[[index]]]] <- names_for_table
    }
    contract_keys <- unlist(Map(function(table_name, names_for_table) {
        paste(table_name, names_for_table, sep = ".")
    }, names(column_names), column_names), use.names = FALSE)
    duplicated_keys <- unique(contract_keys[duplicated(contract_keys) | duplicated(contract_keys, fromLast = TRUE)])
    if (length(duplicated_keys) > 0L) {
        data_dict_abort(paste0("Table and column names produce ambiguous Graft contract keys: ", paste(duplicated_keys, collapse = ", "), "."), field = "tables", rule = "ambiguous_contract_keys", observed_value = duplicated_keys)
    }
    classes <- stats::setNames(list(), character())
    slots <- stats::setNames(list(), character())
    enums <- stats::setNames(list(), character())
    relations <- list()
    for (index in seq_along(tables)) {
        result <- data_dict_compile_table(table = tables[[index]], table_index = index, table_name = table_names[[index]], table_view = table_views[[index]], table_names = table_names, identities = identities, column_names = column_names, source = source)
        classes[[table_names[[index]]]] <- result$class
        for (slot_name in names(result$class$slots)) {
            slots[[paste(table_names[[index]], slot_name, sep = ".")]] <- data_dict_global_slot(result$class$slots[[slot_name]])
        }
        if (length(result$enums) > 0L) {
            enums <- c(enums, result$enums)
        }
        relations <- c(relations, result$relations)
    }
    relations <- relations[order(vapply(relations, function(relation) relation$name, character(1)), method = "radix")]
    list(classes = classes, slots = slots, enums = enums, relations = relations)
}

