data_dict_document_version.body:
{
    if (is.null(version)) {
        return(NULL)
    }
    allowed <- c("number", "date", "hash")
    if (!is.list(version) || is.null(names(version)) || length(version) != 1L || !names(version)[[1L]] %in% allowed || !data_dict_is_string(version[[1L]])) {
        data_dict_abort(paste("Resolved data-dict `version` must be an object containing exactly", "one scalar string field named number, date, or hash."), field = "version", rule = "data_version")
    }
    kind <- names(version)[[1L]]
    value <- version[[1L]]
    if (identical(kind, "number") && !grepl(paste0("^[0-9]+\\.[0-9]+\\.[0-9]+", "(?:-[A-Za-z0-9-]+(?:\\.[A-Za-z0-9-]+)*)?", "(?:\\+[A-Za-z0-9-]+(?:\\.[A-Za-z0-9-]+)*)?$"), value, perl = TRUE)) {
        data_dict_abort(paste("Resolved data-dict `version$number` must have three", "dot-separated numeric components with optional pre-release or", "build suffixes."), field = "version.number", rule = "data_version", observed_value = value)
    }
    if (identical(kind, "date")) {
        parsed <- suppressWarnings(as.Date(value, format = "%Y-%m-%d"))
        valid <- grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$", value) && !is.na(parsed) && identical(format(parsed, "%Y-%m-%d"), value)
        if (!valid) {
            data_dict_abort("Resolved data-dict `version$date` must be a valid ISO 8601 date.", field = "version.date", rule = "data_version", observed_value = value)
        }
    }
    value
}

