data_dict_provider_metadata.body:
{
    if (!is.list(provider) || is.object(provider)) {
        data_dict_abort("`provider` must be a metadata object.", field = "provider", rule = "provider_metadata")
    }
    public_fields <- c("name", "export_format_version", "source_spec_version", "cli_version", "cli_digest", "revision", "source_format")
    allowed_fields <- c(public_fields, "source_path")
    unexpected <- setdiff(names(provider), allowed_fields)
    if (is.null(names(provider)) || anyDuplicated(names(provider)) || length(unexpected) > 0L) {
        data_dict_abort("`provider` contains unsupported or duplicate metadata fields.", field = "provider", rule = "provider_metadata", unexpected_fields = unexpected)
    }
    for (field in c("name", "export_format_version")) {
        if (!data_dict_is_string(provider[[field]])) {
            data_dict_abort(paste0("`provider$", field, "` must be one non-empty string."), field = paste0("provider.", field), rule = "provider_metadata")
        }
    }
    if (!identical(provider$name, "data-dict")) {
        data_dict_abort("`provider$name` must be `data-dict`.", field = "provider.name", rule = "provider_metadata", observed_value = provider$name)
    }
    if (!identical(provider$export_format_version, dictionary[["$version"]])) {
        data_dict_abort(paste0("`provider$export_format_version` must match the resolved export ", "`$version`."), field = "provider.export_format_version", rule = "provider_export_format_version", observed_value = provider$export_format_version, expected_value = dictionary[["$version"]])
    }
    if (is.null(provider$source_format)) {
        provider$source_format <- "resolved_json"
    }
    for (field in c("source_spec_version", "cli_version", "revision")) {
        if (!is.null(provider[[field]]) && !data_dict_is_string(provider[[field]])) {
            data_dict_abort(paste0("`provider$", field, "` must be `NULL` or one non-empty string."), field = paste0("provider.", field), rule = "provider_metadata")
        }
    }
    if (!is.null(provider$cli_digest) && !is_graft_digest(provider$cli_digest)) {
        data_dict_abort("`provider$cli_digest` must be `NULL` or a canonical SHA-256 digest.", field = "provider.cli_digest", rule = "provider_metadata")
    }
    if (!data_dict_is_string(provider$source_format) || !provider$source_format %in% c("yaml", "resolved_json")) {
        data_dict_abort("`provider$source_format` must be `yaml` or `resolved_json`.", field = "provider.source_format", rule = "provider_metadata", observed_value = provider$source_format)
    }
    if (!is.null(provider$source_path) && !data_dict_is_string(provider$source_path)) {
        data_dict_abort("`provider$source_path` must be `NULL` or one non-empty string.", field = "provider.source_path", rule = "provider_metadata")
    }
    yaml_provider <- identical(provider$source_format, "yaml") && data_dict_is_string(provider$source_spec_version) && data_dict_is_string(provider$cli_version) && is_graft_digest(provider$cli_digest)
    resolved_provider <- identical(provider$source_format, "resolved_json") && is.null(provider$source_spec_version) && is.null(provider$cli_version) && is.null(provider$cli_digest)
    if (!yaml_provider && !resolved_provider) {
        data_dict_abort("`provider` metadata is inconsistent with its source format.", field = "provider", rule = "provider_source_format")
    }
    provider[intersect(public_fields, names(provider))]
}

