data_dict_reject_unsafe_json_numbers.body:
{
    if (is.numeric(value)) {
        unsafe <- !is.finite(value) | abs(value) > 2^53 - 1
        if (any(unsafe)) {
            data_dict_abort(paste("The resolved data-dict contains a numeric value outside R's exact", "integer range; use a quoted string contract instead."), field = path, rule = "unsafe_json_number")
        }
        return(invisible(value))
    }
    if (!is.list(value)) {
        return(invisible(value))
    }
    value_names <- names(value)
    for (index in seq_along(value)) {
        name <- if (!is.null(value_names) && length(value_names) >= index && nzchar(value_names[[index]])) {
            value_names[[index]]
        }
        else {
            NULL
        }
        child_path <- if (is.null(name)) {
            paste0(path, "[", index, "]")
        }
        else if (identical(path, "$")) {
            paste0(path, ".", name)
        }
        else {
            paste(path, name, sep = ".")
        }
        data_dict_reject_unsafe_json_numbers(value[[index]], child_path)
    }
    invisible(value)
}

