    allowed <- c("id", "name", "version", "content_digest")
    unexpected <- setdiff(names(source), allowed)
    if (length(unexpected) > 0L) {
        data_dict_abort("`source` contains unsupported metadata fields.", field = "source", rule = "source_metadata", unexpected_fields = unexpected)
    }
    for (field in c("id", "name")) {
        if (!data_dict_is_string(source[[field]])) {
            data_dict_abort(paste0("`source$", field, "` must be one non-empty string."), field = paste0("source.", field), rule = "source_metadata")
        }
    }
    version <- source$version
    if (!is.null(version) && !data_dict_is_string(version)) {
        data_dict_abort("`source$version` must be `NULL` or one non-empty string.", field = "source.version", rule = "source_metadata")
    }
    content_digest <- source$content_digest
    if (is.null(content_digest)) {
        content_digest <- graft_sha256(canonical_json(dictionary))
    }
    else if (!is_graft_digest(content_digest)) {
        data_dict_abort("`source$content_digest` must be a canonical SHA-256 digest.", field = "source.content_digest", rule = "source_metadata", observed_value = content_digest)
    }
    list(id = source$id, name = source$name, version = version, content_digest = content_digest)
}

data_dict_source_snapshot.body:
{
    connection <- tryCatch(file(path, open = "rb"), error = function(error) {
        abort_schema_error(paste0("Could not read data-dict source `", path, "`."), schema_path = path, parent = error)
    })
    connection_open <- TRUE
    on.exit(if (connection_open) close(connection), add = TRUE)
    chunks <- list()
    repeat {
        chunk <- tryCatch(readBin(connection, what = "raw", n = 65536L), error = function(error) {
            abort_schema_error(paste0("Could not read data-dict source `", path, "`."), schema_path = path, parent = error)
        })
        if (length(chunk) == 0L) {
            break
        }
        chunks[[length(chunks) + 1L]] <- chunk
    }
    bytes <- if (length(chunks) == 0L) {
        raw()
    }
    else {
        do.call(c, chunks)
    }
    text <- tryCatch(rawToChar(bytes), error = function(error) {
        abort_schema_error(paste0("Data-dict source `", path, "` is not valid text."), schema_path = path, parent = error)
    })
    list(bytes = bytes, text = text, digest = graft_sha256(bytes))
}

