data_dict_validate_root.body:
{
    if (!is.list(dictionary) || is.object(dictionary)) {
        data_dict_abort("`dictionary` must be a resolved data-dict export-spec object.", field = "dictionary", rule = "resolved_export_spec")
    }
    data_dict_reject_duplicate_json_keys(dictionary)
    version <- dictionary[["$version"]]
    if (!data_dict_is_string(version)) {
        data_dict_abort("The resolved data-dict export must declare `$version`.", field = "$version", rule = "export_format_version")
    }
    if (!identical(version, data_dict_export_format_version)) {
        data_dict_abort(paste0("Unsupported data-dict export-spec version `", version, "`."), field = "$version", rule = "export_format_version", observed_value = version, supported_value = data_dict_export_format_version)
    }
    if (!data_dict_is_array(dictionary$tables) || length(dictionary$tables) == 0L) {
        data_dict_abort("The resolved data-dict export must contain at least one table.", field = "tables", rule = "nonempty_tables")
    }
    if (!data_dict_is_string(dictionary$name)) {
        data_dict_abort("A data-dict used as a Graft contract must declare `name`.", field = "name", rule = "graft_contract_name")
    }
    data_dict_reject_export_data(dictionary)
    data_dict_reject_unsafe_json_numbers(dictionary)
    invisible(dictionary)
}

