deep_integrity_issues.body:
{
    issues <- list()
    cache <- new.env(parent = emptyenv())
    add_issue <- function(issue) {
        if (length(issues) <= limit) {
            issues[[length(issues) + 1L]] <<- issue
        }
    }
    revisions <- DBI::dbSendQuery(store$connection, paste0("SELECT revision_id, record_id, class, batch_id, payload_json, ", "content_digest, schema_build_digest FROM ", quote_identifier(store$connection, "_graft_record_revisions"), " ORDER BY revision_id"))
    on.exit({
        if (!is.null(revisions)) {
            DBI::dbClearResult(revisions)
        }
    }, add = TRUE)
    repeat {
        rows <- DBI::dbFetch(revisions, n = 500L)
        if (nrow(rows) == 0L) {
            break
        }
        for (index in seq_len(nrow(rows))) {
            payload <- tryCatch(parse_revision_payload(rows$payload_json[[index]]), error = identity)
            if (inherits(payload, "error")) {
                add_issue(integrity_issue_row("invalid_revision_payload", rows$record_id[[index]], rows$class[[index]], rows$revision_id[[index]], rows$batch_id[[index]], "Revision payload is not valid canonical JSON."))
                next
            }
            schema <- tryCatch(historical_schema(store, rows$schema_build_digest[[index]], cache), error = identity)
            contract <- if (inherits(schema, "error")) {
                NULL
            }
            else {
                schema$manifest$classes[[rows$class[[index]]]]
            }
            if (is.null(contract)) {
                next
            }
            payload <- tryCatch(canonical_manifest_payload(payload, contract), error = identity)
            if (inherits(payload, "error")) {
                add_issue(integrity_issue_row("noncanonical_revision_payload", rows$record_id[[index]], rows$class[[index]], rows$revision_id[[index]], rows$batch_id[[index]], "Revision payload does not conform to its historical schema."))
                next
            }
            digest <- logical_record_content_digest(payload)
            if (!identical(digest, rows$content_digest[[index]])) {
                add_issue(integrity_issue_row("revision_digest_mismatch", rows$record_id[[index]], rows$class[[index]], rows$revision_id[[index]], rows$batch_id[[index]], "Revision payload does not match its content digest."))
            }
        }
    }
    DBI::dbClearResult(revisions)
    revisions <- NULL
    issues
}

definition_calculation_catalog.body:
{
    selectors <- lapply(references, definition_reference_parts, argument = "metrics")
    rows <- definition_current_rows(source, names = unique(vapply(selectors, `[[`, character(1), "name")))
    if (nrow(rows) == 0L) {
        return(empty_definition_catalog())
    }
    payloads <- lapply(rows$payload_json, jsonlite::fromJSON, simplifyVector = FALSE)
    candidates <- data.frame(target = vapply(payloads, function(payload) scalar_character(payload$target), ""), name = vapply(payloads, function(payload) scalar_character(payload$name), ""), stringsAsFactors = FALSE)
    matched <- vapply(seq_len(nrow(candidates)), function(index) {
        any(vapply(selectors, function(selector) {
            identical(selector$name, candidates$name[[index]]) && (is.null(selector$target) || identical(selector$target, candidates$target[[index]]))
        }, logical(1)))
    }, logical(1))
    targets <- sort(unique(candidates$target[matched]), method = "radix")
    if (length(targets) == 0L) {
        return(empty_definition_catalog())
    }
    catalogs <- lapply(targets, function(target) definition_catalog(source, target, bounded = FALSE))
    catalog <- dplyr::bind_rows(catalogs)
    catalog[order(catalog$target, catalog$name, method = "radix"), , drop = FALSE]
}

definition_catalog.body:
{
    validate_graft_retrieval(source)
    if (!is.null(target)) {
        target <- validate_scalar_text(target, "target")
        definition_target_contract(source$schema$manifest, target)
    }
    limit <- graft_retrieval_limits$definitions
    rows <- definition_current_rows(source, targets = target, limit = if (bounded) 
        limit
    else NULL)
    if (nrow(rows) == 0L) {
        result <- empty_definition_catalog()
        if (bounded) {
            return(trim_bounded_rows(result, source, limit))
        }
        return(result)
    }
    payloads <- lapply(rows$payload_json, jsonlite::fromJSON, simplifyVector = FALSE)
    catalog <- dplyr::bind_rows(lapply(seq_len(nrow(rows)), function(index) {
        payload <- payloads[[index]]
        data.frame(id = rows$record_id[[index]], revision_id = rows$revision_id[[index]], name = scalar_character(payload$name), target = scalar_character(payload$target), expr = scalar_character(payload$expr), label = scalar_character(payload$label), description = scalar_character(payload$description), details = scalar_character(payload$details), stringsAsFactors = FALSE)
    }))
    analyses <- definition_catalog_analyses(source, catalog)
    catalog$kind <- vapply(analyses, `[[`, character(1), "kind")
    catalog$dependencies <- lapply(analyses, `[[`, "dependencies")
    catalog$columns <- lapply(catalog$target, function(target_name) {
        definition_public_scalar_columns(definition_target_contract(source$schema$manifest, target_name))
    })
    catalog <- catalog[c("id", "revision_id", "name", "target", "kind", "expr", "label", "description", "details", "dependencies", "columns")]
    catalog <- catalog[order(catalog$target, catalog$name, method = "radix"), , drop = FALSE]
    if (bounded) {
        return(trim_bounded_rows(catalog, source, limit))
    }
    rownames(catalog) <- NULL
    catalog
}

definition_catalog_analyses.body:
{
    analyses <- vector("list", nrow(catalog))
    for (target in unique(catalog$target)) {
        indexes <- which(catalog$target == target)
        contract <- definition_target_contract(source$schema$manifest, target)
        columns <- definition_public_scalar_columns(contract)
        compiler <- new.env(parent = emptyenv())
        compiler$catalog <- catalog[indexes, , drop = FALSE]
        compiler$columns <- columns
        compiler$target <- target
        compiler$compiled <- list()
        compiler$active <- character()
        source_sql <- definition_empty_source_sql(source$connection, contract)
        shapes <- stats::setNames(rep(NA_character_, length(indexes)), catalog$id[indexes])
        analyze <- function(index) {
            id <- catalog$id[[index]]
            if (!is.na(shapes[[id]])) {
                return(analyses[[index]])
            }
            basic <- definition_expr_analyze(catalog$expr[[index]], columns, catalog$name[indexes])
            if (nrow(basic$issues) > 0L) {
                abort_backend_error("An accepted definition no longer compiles.", operation = "definition_catalog", definition_id = id, issues = basic$issues)
            }
            dependency_shapes <- vapply(basic$dependencies, function(name) {
                dependency <- indexes[catalog$name[indexes] == name]
                if (length(dependency) != 1L) {
                  abort_backend_error("An accepted definition dependency is missing or ambiguous.", operation = "definition_catalog", definition_id = id, dependency = name)
                }
                analyze(dependency)
                shapes[[catalog$id[[dependency]]]]
            }, character(1))
            shape <- if (basic$has_aggregate || any(dependency_shapes == "aggregate")) {
                "aggregate"
            }
            else if (basic$has_row_reference || any(dependency_shapes == "row")) {
                "row"
            }
            else {
                "constant"
            }
            compiled <- tryCatch(definition_compile_row(catalog[index, , drop = FALSE], compiler), error = function(error) {
                abort_backend_error("An accepted definition no longer compiles.", operation = "definition_catalog", definition_id = id, parent = error)
            })
            type <- tryCatch(definition_describe_sql(source$connection, compiled$sql, source_sql), error = function(error) {
                abort_backend_error("An accepted definition no longer type-checks.", operation = "definition_catalog", definition_id = id, parent = error)
            })
            basic$kind <- if (shape %in% c("aggregate", "constant")) {
                "metric"
            }
            else if (grepl("^BOOLEAN", toupper(type))) {
                "filter"
            }
            else {
                "derived"
            }
            shapes[[id]] <<- shape
            analyses[[index]] <<- basic
            basic
        }
        for (index in indexes) {
            analyze(index)
        }
    }
    analyses
}

definition_column_values.body:
{
    scalars <- vapply(raw, function(value) {
        if (is.null(value) || length(value) != 1L) {
            NA_character_
        }
        else {
            as.character(value)
        }
    }, character(1))
    if (!typed) {
        return(scalars)
    }
    type <- toupper(duckdb_type)
    if (type %in% c("DOUBLE", "FLOAT", "DECIMAL", "BIGINT", "INTEGER")) {
        return(suppressWarnings(as.numeric(scalars)))
    }
    if (identical(type, "BOOLEAN")) {
        return(as.logical(scalars))
    }
    if (identical(type, "DATE")) {
        return(as.Date(scalars))
    }
    if (identical(type, "TIMESTAMP")) {
        return(as.POSIXct(scalars, tz = "UTC"))
    }
    scalars
}

definition_compile_row.body:
{
    id <- row$id[[1L]]
    cached <- compiler$compiled[[id]]
    if (!is.null(cached)) {
        return(cached)
    }
    if (id %in% compiler$active) {
        abort_calculation_error("An accepted definition dependency cycle reached evaluation.", rule = "definition_cycle", definition_id = id)
    }
    compiler$active <- c(compiler$active, id)
    on.exit({
        compiler$active <- setdiff(compiler$active, id)
    }, add = TRUE)
    local_names <- compiler$catalog$name[compiler$catalog$target == compiler$target]
    analysis <- definition_expr_analyze(row$expr[[1L]], compiler$columns, local_names)
    if (nrow(analysis$issues) > 0L) {
        abort_calculation_error("An accepted definition no longer compiles; this indicates a Graft bug.", rule = "definition_integrity", definition_id = id, issues = analysis$issues)
    }
    sql <- analysis$sql
    definition_ids <- id
    for (dependency in analysis$dependencies) {
        dependency_row <- compiler$catalog[compiler$catalog$target == compiler$target & compiler$catalog$name == dependency, , drop = FALSE]
        if (nrow(dependency_row) != 1L) {
            abort_calculation_error(paste0("Accepted definition dependency `", dependency, "` is missing."), rule = "definition_dependency", definition_id = id, dependency = dependency)
        }
        compiled <- definition_compile_row(dependency_row, compiler)
        sql <- gsub(definition_sql_identifier(dependency), paste0("(", compiled$sql, ")"), sql, fixed = TRUE)
        definition_ids <- c(definition_ids, compiled$definition_ids)
    }
    result <- list(sql = sql, definition_ids = unique(definition_ids))
    compiler$compiled[[id]] <- result
    result
}

