definition_current_rows.body:
{
    where <- "class = ?"
    params <- list(graft_definition_class_name)
    add_payload_filter <- function(field, values) {
        values <- unique(as.character(values))
        if (length(values) == 0L) {
            return(FALSE)
        }
        fragments <- vapply(values, function(value) paste0("\"", field, "\":", canonical_json(value)), "")
        where <<- c(where, paste0("(", paste(rep("strpos(payload_json, ?) > 0", length(values)), collapse = " OR "), ")"))
        params <<- c(params, unname(as.list(fragments)))
        TRUE
    }
    if (!is.null(targets) && !add_payload_filter("target", targets)) {
        return(data.frame())
    }
    if (!is.null(names) && !add_payload_filter("name", names)) {
        return(data.frame())
    }
    limit_sql <- if (is.null(limit)) {
        ""
    }
    else {
        paste0(" LIMIT ", limit + 1L)
    }
    retrieval_query(source$connection, paste0("SELECT * FROM (", graft_read_source_sql(source), ") definitions WHERE ", paste(where, collapse = " AND "), " ORDER BY class, record_id, revision_id", limit_sql), params = params)
}

definition_cycle_members.body:
{
    if (length(graph) == 0L) {
        return(character())
    }
    state <- stats::setNames(integer(length(graph)), names(graph))
    stack <- character()
    cycles <- character()
    visit <- function(name) {
        if (state[[name]] == 2L) {
            return(invisible(NULL))
        }
        if (state[[name]] == 1L) {
            start <- match(name, stack)
            cycles <<- unique(c(cycles, stack[seq.int(start, length(stack))]))
            return(invisible(NULL))
        }
        state[[name]] <<- 1L
        stack <<- c(stack, name)
        for (dependency in graph[[name]]) {
            if (dependency %in% names(graph)) {
                visit(dependency)
            }
        }
        stack <<- utils::head(stack, -1L)
        state[[name]] <<- 2L
        invisible(NULL)
    }
    for (name in names(graph)) {
        visit(name)
    }
    sort(unique(cycles), method = "radix")
}

