definition_expr_analyze.body:
{
    checked <- definition_expr_check(expr, c(columns, definition_names), selection_columns = columns)
    if (nrow(checked$issues) > 0L) {
        return(list(issues = checked$issues, sql = NA_character_, kind = NA_character_, dependencies = character(), has_aggregate = FALSE, has_row_reference = FALSE, has_selection = FALSE))
    }
    tokens <- definition_expr_tokenize(expr)
    texts <- vapply(tokens, `[[`, character(1), "text")
    types <- vapply(tokens, `[[`, character(1), "type")
    names <- texts
    quoted <- types == "quoted_identifier"
    names[quoted] <- vapply(texts[quoted], function(text) {
        gsub("``", "`", substr(text, 2L, nchar(text) - 1L), fixed = TRUE)
    }, character(1))
    upper <- toupper(texts)
    following <- c(texts[-1L], "")
    calls <- upper[types == "identifier" & following == "("]
    identifiers <- names[types %in% c("identifier", "quoted_identifier") & (types == "quoted_identifier" | following != "(")]
    reserved <- c("AND", "OR", "NOT", "TRUE", "FALSE", "DISTINCT")
    dependencies <- unique(identifiers[!toupper(identifiers) %in% reserved & identifiers %in% definition_names & !identifiers %in% columns])
    has_aggregate <- any(calls %in% definition_expr_aggregates)
    has_row_reference <- any(identifiers %in% columns) || any(calls %in% "COLUMNS")
    has_predicate <- any(types == "operator" & texts %in% c("=", "!=", "<", "<=", ">", ">=")) || any(calls %in% c("STARTS_WITH", "ENDS_WITH", "IS_FINITE", "IS_INFINITE", "IS_NAN")) || any(upper %in% c("AND", "OR", "NOT", "TRUE", "FALSE", "IS", "BETWEEN", "IN", "LIKE", "SIMILAR"))
    kind <- if (has_aggregate) {
        "metric"
    }
    else if (!has_row_reference && length(dependencies) == 0L) {
        "metric"
    }
    else if (has_predicate) {
        "filter"
    }
    else {
        "derived"
    }
    list(issues = definition_expr_no_issues(), sql = checked$sql, kind = kind, dependencies = dependencies, has_aggregate = has_aggregate, has_row_reference = has_row_reference, has_selection = !is.null(checked$selection))
}

definition_expr_check.body:
{
    tokens <- tryCatch(definition_expr_tokenize(expr), graft_definition_expr_error = function(condition) condition)
    if (rlang::is_condition(tokens)) {
        return(list(issues = definition_expr_issue("definition_expr_parse", conditionMessage(tokens)), sql = NA_character_, selection = NULL))
    }
    state <- new.env(parent = emptyenv())
    state$tokens <- tokens
    state$position <- 1L
    state$issues <- definition_expr_no_issues()
    state$columns <- columns
    state$selection_columns <- selection_columns
    state$selection <- NULL
    sql <- tryCatch({
        out <- definition_expr_parse_or(state)
        remaining <- definition_expr_peek(state)
        if (!is.null(remaining)) {
            definition_expr_abort(paste0("Unexpected `", remaining$text, "` after end of expression."))
        }
        if (is.null(state$selection)) {
            out
        }
        else {
            expanded <- vapply(state$selection, function(column) {
                sub(definition_expr_selection_marker, paste0("\"", gsub("\"", "\"\"", column, fixed = TRUE), "\""), out, fixed = TRUE)
            }, character(1))
            if (grepl("\\b(AND|OR)\\b", out)) {
                expanded <- paste0("(", expanded, ")")
            }
            paste(expanded, collapse = " AND ")
        }
    }, graft_definition_expr_error = function(condition) {
        state$issues <- rbind(state$issues, definition_expr_issue("definition_expr_parse", conditionMessage(condition)))
        NA_character_
    })
    if (nrow(state$issues) > 0L) {
        sql <- NA_character_
    }
    list(issues = state$issues, sql = sql, selection = state$selection)
}

definition_expr_expect.body:
{
    token <- definition_expr_peek(state)
    if (is.null(token) || !identical(toupper(token$text), toupper(text))) {
        observed <- if (is.null(token)) {
            "end of expression"
        }
        else {
            paste0("`", token$text, "`")
        }
        definition_expr_abort(paste0("Expected `", text, "` but found ", observed, "."))
    }
    definition_expr_advance(state)
}

definition_expr_issue.body:
{
    data.frame(rule = rule, message = message, stringsAsFactors = FALSE)
}

definition_expr_no_issues.body:
{
    data.frame(rule = character(), message = character(), stringsAsFactors = FALSE)
}

definition_expr_parse_additive.body:
{
    left <- definition_expr_parse_multiplicative(state)
    repeat {
        token <- definition_expr_peek(state)
        if (is.null(token) || !identical(token$type, "operator") || !(token$text %in% c("+", "-"))) {
            return(left)
        }
        definition_expr_advance(state)
        left <- paste(left, token$text, definition_expr_parse_multiplicative(state))
    }
}

definition_expr_parse_and.body:
{
    left <- definition_expr_parse_not(state)
    while (definition_expr_keyword(definition_expr_peek(state), "AND")) {
        definition_expr_advance(state)
        left <- paste(left, "AND", definition_expr_parse_not(state))
    }
    left
}

definition_expr_parse_arguments.body:
{
    token <- definition_expr_peek(state)
    if (!is.null(token) && identical(token$text, ")")) {
        return(character())
    }
    arguments <- definition_expr_parse_or(state)
    while (!is.null(definition_expr_peek(state)) && identical(definition_expr_peek(state)$type, "comma")) {
        definition_expr_advance(state)
        arguments <- c(arguments, definition_expr_parse_or(state))
    }
    arguments
}

definition_expr_parse_case.body:
{
    branches <- character()
    while (definition_expr_keyword(definition_expr_peek(state), "WHEN")) {
        definition_expr_advance(state)
        condition <- definition_expr_parse_or(state)
        definition_expr_expect(state, "THEN")
        value <- definition_expr_parse_or(state)
        branches <- c(branches, paste("WHEN", condition, "THEN", value))
    }
    if (length(branches) == 0L) {
        definition_expr_abort("`CASE` requires at least one `WHEN ... THEN ...`.")
    }
    otherwise <- ""
    if (definition_expr_keyword(definition_expr_peek(state), "ELSE")) {
        definition_expr_advance(state)
        otherwise <- paste("ELSE", definition_expr_parse_or(state))
    }
    definition_expr_expect(state, "END")
    paste("CASE", paste(branches, collapse = " "), otherwise, "END")
}

definition_expr_parse_columns.body:
{
    if (!is.null(state$selection)) {
        definition_expr_abort("A definition may use at most one `COLUMNS()` selection.")
    }
    token <- definition_expr_peek(state)
    if (!is.null(token) && identical(token$type, "operator") && identical(token$text, "*")) {
        definition_expr_advance(state)
        selected <- state$selection_columns
    }
    else if (!is.null(token) && identical(token$type, "bracket") && identical(token$text, "[")) {
        definition_expr_advance(state)
        selected <- character()
        repeat {
            item <- definition_expr_advance(state)
            if (is.null(item) || !item$type %in% c("identifier", "quoted_identifier")) {
                definition_expr_abort("`COLUMNS([...])` requires column names.")
            }
            name <- if (identical(item$type, "quoted_identifier")) {
                gsub("``", "`", substr(item$text, 2L, nchar(item$text) - 1L), fixed = TRUE)
            }
            else {
                item$text
            }
            selected <- c(selected, name)
            next_token <- definition_expr_peek(state)
            if (!is.null(next_token) && identical(next_token$type, "comma")) {
                definition_expr_advance(state)
                next
            }
            if (is.null(next_token) || !identical(next_token$type, "bracket") || !identical(next_token$text, "]")) {
                definition_expr_abort("`COLUMNS([...])` requires a closing `]`.")
            }
            definition_expr_advance(state)
            break
        }
        missing <- setdiff(selected, state$selection_columns)
        if (length(missing) > 0L) {
            definition_expr_abort(paste0("Columns not found: ", paste(missing, collapse = ", "), "."))
        }
    }
    else if (!is.null(token) && identical(token$type, "string")) {
        definition_expr_advance(state)
        pattern <- substr(token$text, 2L, nchar(token$text) - 1L)
        pattern <- gsub("''", "'", pattern, fixed = TRUE)
        unsupported <- grepl("\\(\\?(?:[=!>]|<[=!])|\\\\[1-9]", pattern, perl = TRUE)
        valid <- tryCatch({
            grepl(pattern, "", perl = TRUE)
            TRUE
        }, warning = function(warning) FALSE, error = function(error) FALSE)
        if (unsupported || !valid) {
            definition_expr_abort("`COLUMNS()` contains an invalid regular expression.")
        }
        selected <- state$selection_columns[vapply(state$selection_columns, function(column) grepl(pattern, column, perl = TRUE), logical(1))]
    }
    else {
        definition_expr_abort("`COLUMNS()` requires `*`, a column list, or a regular expression.")
    }
    definition_expr_expect(state, ")")
    if (length(selected) == 0L) {
        definition_expr_abort("`COLUMNS()` must select at least one column.")
    }
    state$selection <- selected
    definition_expr_selection_marker
}

definition_expr_parse_comparison.body:
{
    left <- definition_expr_parse_additive(state)
    token <- definition_expr_peek(state)
    if (!is.null(token) && identical(token$type, "operator") && token$text %in% c("=", "!=", "<>", "<", "<=", ">", ">=")) {
        definition_expr_advance(state)
        return(paste(left, token$text, definition_expr_parse_additive(state)))
    }
    if (definition_expr_keyword(token, "IS")) {
        definition_expr_advance(state)
        negated <- FALSE
        if (definition_expr_keyword(definition_expr_peek(state), "NOT")) {
            definition_expr_advance(state)
            negated <- TRUE
        }
        definition_expr_expect(state, "NULL")
        return(paste(left, "IS", if (negated) "NOT NULL" else "NULL"))
    }
    negated <- FALSE
    if (definition_expr_keyword(token, "NOT")) {
        definition_expr_advance(state)
        negated <- TRUE
        token <- definition_expr_peek(state)
    }
    if (definition_expr_keyword(token, "BETWEEN")) {
        definition_expr_advance(state)
        lower <- definition_expr_parse_additive(state)
        definition_expr_expect(state, "AND")
        upper <- definition_expr_parse_additive(state)
        return(paste(left, if (negated) "NOT BETWEEN" else "BETWEEN", lower, "AND", upper))
    }
    if (definition_expr_keyword(token, "IN")) {
        definition_expr_advance(state)
        definition_expr_expect(state, "(")
        values <- list(definition_expr_parse_or(state))
        while (!is.null(definition_expr_peek(state)) && identical(definition_expr_peek(state)$type, "comma")) {
            definition_expr_advance(state)
            values[[length(values) + 1L]] <- definition_expr_parse_or(state)
        }
        definition_expr_expect(state, ")")
        return(paste0(left, if (negated) " NOT IN (" else " IN (", paste(unlist(values, use.names = FALSE), collapse = ", "), ")"))
    }
    if (definition_expr_keyword(token, "LIKE")) {
        definition_expr_advance(state)
        pattern <- definition_expr_parse_additive(state)
        return(paste(left, if (negated) "NOT LIKE" else "LIKE", pattern))
    }
    if (definition_expr_keyword(token, "SIMILAR")) {
        definition_expr_advance(state)
        definition_expr_expect(state, "TO")
        pattern <- definition_expr_parse_additive(state)
        return(paste(left, if (negated) "NOT SIMILAR TO" else "SIMILAR TO", pattern))
    }
    if (negated) {
        definition_expr_abort("Expected `BETWEEN`, `IN`, `LIKE`, or `SIMILAR TO` after `NOT`.")
    }
    left
}

definition_expr_parse_field_path.body:
{
    path <- first
    while (!is.null(definition_expr_peek(state)) && identical(definition_expr_peek(state)$type, "dot")) {
        definition_expr_advance(state)
        token <- definition_expr_advance(state)
        if (is.null(token) || !token$type %in% c("identifier", "quoted_identifier")) {
            definition_expr_abort("Expected a field name after `.`.")
        }
        name <- if (identical(token$type, "quoted_identifier")) {
            gsub("``", "`", substr(token$text, 2L, nchar(token$text) - 1L), fixed = TRUE)
        }
        else {
            token$text
        }
        path <- c(path, name)
    }
    reference <- paste(path, collapse = ".")
    if (!(reference %in% state$columns)) {
        state$issues <- rbind(state$issues, definition_expr_issue("definition_expr_column", paste0("Column or sibling definition `", reference, "` is not available on the target table.")))
    }
    paste0("\"", paste(gsub("\"", "\"\"", path, fixed = TRUE), collapse = "\".\""), "\"")
}

definition_expr_parse_multiplicative.body:
{
    left <- definition_expr_parse_primary(state)
    repeat {
        token <- definition_expr_peek(state)
        if (is.null(token) || !identical(token$type, "operator") || !(token$text %in% c("*", "/"))) {
            return(left)
        }
        definition_expr_advance(state)
        left <- paste(left, token$text, definition_expr_parse_primary(state))
    }
}

definition_expr_parse_or.body:
{
    left <- definition_expr_parse_and(state)
    while (definition_expr_keyword(definition_expr_peek(state), "OR")) {
        definition_expr_advance(state)
        left <- paste(left, "OR", definition_expr_parse_and(state))
    }
    left
}

definition_expr_parse_primary.body:
{
    token <- definition_expr_peek(state)
    if (is.null(token)) {
        definition_expr_abort("Unexpected end of definition expression.")
    }
    if (identical(token$type, "number")) {
        definition_expr_advance(state)
        return(token$text)
    }
    if (identical(token$type, "string")) {
        definition_expr_advance(state)
        return(token$text)
    }
    if (identical(token$type, "quoted_identifier")) {
        definition_expr_advance(state)
        name <- substr(token$text, 2L, nchar(token$text) - 1L)
        name <- gsub("``", "`", name, fixed = TRUE)
        return(definition_expr_parse_field_path(state, name))
    }
    if (identical(token$type, "operator") && identical(token$text, "(")) {
        definition_expr_advance(state)
        inner <- definition_expr_parse_or(state)
        definition_expr_expect(state, ")")
        return(paste0("(", inner, ")"))
    }
    if (identical(token$type, "operator") && identical(token$text, "-")) {
        definition_expr_advance(state)
        return(paste0("-", definition_expr_parse_primary(state)))
    }
    if (identical(token$type, "identifier")) {
        upper <- toupper(token$text)
        if (upper %in% c("TRUE", "FALSE")) {
            definition_expr_advance(state)
            return(upper)
        }
        if (identical(upper, "NULL")) {
            definition_expr_advance(state)
            return("NULL")
        }
        if (upper %in% c("INF", "NAN")) {
            definition_expr_advance(state)
            return(paste0("CAST('", if (identical(upper, "INF")) "Infinity" else "NaN", "' AS DOUBLE)"))
        }
        if (identical(upper, "CASE")) {
            definition_expr_advance(state)
            return(definition_expr_parse_case(state))
        }
        following <- if (state$position < length(state$tokens)) {
            state$tokens[[state$position + 1L]]
        }
        is_call <- !is.null(following) && identical(following$type, "operator") && identical(following$text, "(")
        if (is_call) {
            definition_expr_advance(state)
            definition_expr_advance(state)
            if (identical(upper, "COLUMNS")) {
                return(definition_expr_parse_columns(state))
            }
            if (identical(upper, "NOW")) {
                definition_expr_expect(state, ")")
                return("CURRENT_TIMESTAMP")
            }
            if (identical(upper, "INTERVAL")) {
                value <- definition_expr_parse_or(state)
                token <- definition_expr_peek(state)
                if (is.null(token) || !identical(token$type, "comma")) {
                  definition_expr_abort("`INTERVAL()` requires a value and unit.")
                }
                definition_expr_advance(state)
                unit <- definition_expr_advance(state)
                if (is.null(unit) || !identical(unit$type, "identifier") || !tolower(unit$text) %in% c("seconds", "minutes", "hours", "days", "weeks")) {
                  definition_expr_abort("Interval units must be seconds, minutes, hours, days, or weeks.")
                }
                definition_expr_expect(state, ")")
                return(paste0("(", value, " * INTERVAL 1 ", toupper(sub("s$", "", unit$text)), ")"))
            }
            if (!(upper %in% definition_expr_functions)) {
                state$issues <- rbind(state$issues, definition_expr_issue("definition_expr_function", paste0("Function `", token$text, "` is not in the definition whitelist (", paste(definition_expr_functions, collapse = ", "), ").")))
            }
            arguments <- definition_expr_parse_arguments(state)
            definition_expr_expect(state, ")")
            allowed <- definition_expr_arities[[upper]]
            if (!is.null(allowed) && !length(arguments) %in% allowed) {
                state$issues <- rbind(state$issues, definition_expr_issue("definition_expr_function", paste0("Function `", token$text, "` takes ", paste(allowed, collapse = " or "), " argument(s), not ", length(arguments), ".")))
            }
            inner <- paste(arguments, collapse = ", ")
            if (identical(upper, "ROW_COUNT")) {
                return("COUNT(*)")
            }
            if (identical(upper, "COUNT_DISTINCT")) {
                return(paste0("COUNT(DISTINCT ", inner, ")"))
            }
            if (identical(upper, "ANY")) {
                return(paste0("BOOL_OR(", inner, ")"))
            }
            if (identical(upper, "ALL")) {
                return(paste0("BOOL_AND(", inner, ")"))
            }
            if (identical(upper, "IS_FINITE")) {
                return(paste0("ISFINITE(", inner, ")"))
            }
            if (identical(upper, "IS_INFINITE")) {
                return(paste0("ISINF(", inner, ")"))
            }
            if (identical(upper, "IS_NAN")) {
                return(paste0("ISNAN(", inner, ")"))
            }
            if (identical(upper, "MOD") && length(arguments) == 2L) {
                return(paste0("MOD(MOD(", arguments[[1L]], ", ", arguments[[2L]], ") + ", arguments[[2L]], ", ", arguments[[2L]], ")"))
            }
            return(paste0(upper, "(", inner, ")"))
        }
        definition_expr_advance(state)
        return(definition_expr_parse_field_path(state, token$text))
    }
    definition_expr_abort(paste0("Unexpected `", token$text, "` in definition expression."))
}

definition_expr_tokenize.body:
{
    if (!is_nonempty_string(expr)) {
        definition_expr_abort("A definition expression must be one non-empty string.")
    }
    source <- expr
    tokens <- list()
    while (nzchar(source)) {
        whitespace <- regmatches(source, regexpr("^\\s+", source))
        if (length(whitespace) == 1L) {
            source <- substr(source, nchar(whitespace) + 1L, nchar(source))
            next
        }
        matched <- FALSE
        for (spec in list(c("number", "^[0-9]+(\\.[0-9]+)?([eE][+-]?[0-9]+)?"), c("string", "^'([^']|'')*'"), c("quoted_identifier", "^`([^`]|``)*`"), c("identifier", "^[A-Za-z_][A-Za-z0-9_]*"), c("operator", "^(<>|!=|<=|>=|[=<>+*/()-])"), c("comma", "^,"), c("dot", "^\\."), c("bracket", "^(\\[|\\])"))) {
            text <- regmatches(source, regexpr(spec[[2L]], source))
            if (length(text) == 1L) {
                tokens[[length(tokens) + 1L]] <- list(type = spec[[1L]], text = text)
                source <- substr(source, nchar(text) + 1L, nchar(source))
                matched <- TRUE
                break
            }
        }
        if (!matched) {
            definition_expr_abort(paste0("Unexpected character `", substr(source, 1L, 1L), "` in definition expression."))
        }
    }
    if (length(tokens) == 0L) {
        definition_expr_abort("A definition expression must be one non-empty string.")
    }
    tokens
}

definition_name_argument.body:
{
    if (is.null(value)) {
        value <- character()
    }
    if (is.factor(value)) {
        value <- as.character(value)
    }
    valid <- is.character(value) && !anyNA(value) && all(nzchar(value)) && !anyDuplicated(value)
    if (!valid || (required && length(value) == 0L)) {
        abort_calculation_error(paste0("`", argument, "` must contain ", if (required) 
            "one or more "
        else "unique ", "non-empty definition names."), field = argument, rule = "calculation_names", observed_value = value)
    }
    value
}

definition_reference_parts.body:
{
    parts <- strsplit(reference, "::", fixed = TRUE)[[1L]]
    if (length(parts) > 2L || !all(nzchar(parts))) {
        abort_calculation_error(paste0("Invalid definition reference `", reference, "`."), field = argument, rule = "definition_reference", observed_value = reference)
    }
    list(target = if (length(parts) == 2L) parts[[1L]] else NULL, name = if (length(parts) == 2L) parts[[2L]] else parts[[1L]])
}

definition_relation_contract.body:
{
    relation_slot <- function(name, duckdb_type, range = "string", identifier = FALSE) {
        graft_definition_slot(name, range = range, duckdb_type = duckdb_type, required = FALSE, identifier = identifier)
    }
    slots <- if (identical(scalar_character(relation$kind), "object")) {
        list(id = relation_slot("id", "VARCHAR", "uriorcurie", identifier = TRUE), subject = relation_slot("subject", "VARCHAR", "uriorcurie"), object = relation_slot("object", "VARCHAR", "uriorcurie"), position = relation_slot("position", "BIGINT", "integer"), created_at = relation_slot("created_at", "TIMESTAMP", "datetime"))
    }
    else {
        value <- relation_slot("value", scalar_character(value_slot$duckdb_type), scalar_character(value_slot$range))
        value$enum <- value_slot$enum
        list(owner_id = relation_slot("owner_id", "VARCHAR", "uriorcurie"), position = relation_slot("position", "BIGINT", "integer"), value = value)
    }
    list(name = scalar_character(relation$view), slots = slots, relation = relation)
}

definition_resolve_dimensions.body:
{
    lapply(dimensions, function(reference) {
        if (!grepl("::", reference, fixed = TRUE) && reference %in% columns) {
            return(list(name = reference, kind = "column", row = NULL))
        }
        row <- definition_resolve_one(catalog, reference, kind = "derived", target = target, argument = "dimensions")
        list(name = row$name[[1L]], kind = "derived", row = row)
    })
}

definition_resolve_many.body:
{
    if (length(references) == 0L) {
        return(catalog[integer(), , drop = FALSE])
    }
    rows <- lapply(references, function(reference) {
        definition_resolve_one(catalog, reference, kind = kind, target = target, argument = argument)
    })
    dplyr::bind_rows(rows)
}

definition_resolve_one.body:
{
    parts <- definition_reference_parts(reference, argument)
    qualified_target <- parts$target
    name <- parts$name
    if (!is.null(target) && !is.null(qualified_target) && !identical(target, qualified_target)) {
        abort_calculation_error(paste0("Definition `", reference, "` does not target `", target, "`."), field = argument, rule = "calculation_single_target", observed_value = reference)
    }
    candidates <- catalog[catalog$name == name, , drop = FALSE]
    effective_target <- if (!is.null(qualified_target)) {
        qualified_target
    }
    else {
        target
    }
    if (!is.null(effective_target)) {
        candidates <- candidates[candidates$target == effective_target, , drop = FALSE]
    }
    if (nrow(candidates) == 0L) {
        abort_calculation_error(paste0("No accepted definition resolves `", reference, "`."), field = argument, rule = "definition_exists", observed_value = reference)
    }
    if (nrow(candidates) > 1L) {
        abort_calculation_error(paste0("Definition `", reference, "` is ambiguous; qualify it as `target::name`."), field = argument, rule = "definition_ambiguous", observed_value = reference)
    }
    if (!identical(candidates$kind[[1L]], kind)) {
        abort_calculation_error(paste0("Definition `", reference, "` is `", candidates$kind[[1L]], "`, not `", kind, "`."), field = argument, rule = "definition_kind", observed_value = candidates$kind[[1L]], expected_value = kind)
    }
    candidates
}

definition_target_contract.body:
{
    contract <- definition_target_contract_or_null(manifest, target)
    if (is.null(contract)) {
        abort_validation_error(paste0("Unknown public definition target `", target, "`."), field = "target", rule = "definition_target", observed_value = target)
    }
    contract
}

definition_target_contract_or_null.body:
{
    if (is.na(target) || identical(target, graft_definition_class_name)) {
        return(NULL)
    }
    contract <- manifest$classes[[target]]
    if (!is.null(contract)) {
        return(contract)
    }
    matches <- Filter(function(relation) identical(scalar_character(relation$view), target), manifest$relations)
    if (length(matches) != 1L) {
        return(NULL)
    }
    relation <- matches[[1L]]
    owner <- scalar_character(relation$owner_class)
    slot <- manifest$classes[[owner]]$slots[[scalar_character(relation$slot)]]
    if (scalar_logical(slot$sensitive)) {
        return(NULL)
    }
    definition_relation_contract(relation, slot)
}

definition_target_frame.body:
{
    relation <- contract[["relation", exact = TRUE]]
    if (!is.null(relation)) {
        frame <- commons_relation_frame(source, relation)
        if (!typed) {
            frame[] <- lapply(frame, as.character)
        }
        return(frame)
    }
    rows <- retrieval_query(source$connection, paste0("SELECT payload_json FROM (", graft_read_source_sql(source), ") definition_source WHERE class = ?"), params = list(scalar_character(contract$name)))
    columns <- definition_public_scalar_columns(contract)
    payloads <- lapply(rows$payload_json, jsonlite::fromJSON, simplifyVector = FALSE, bigint_as_char = !typed)
    values <- lapply(columns, function(column) {
        slot <- contract$slots[[column]]
        raw <- lapply(payloads, function(payload) payload[[column]])
        definition_column_values(raw, scalar_character(slot$duckdb_type), typed = typed)
    })
    stats::setNames(data.frame(values, stringsAsFactors = FALSE), columns)
}

definition_target_source_sql.body:
{
    columns <- definition_public_scalar_columns(contract)
    selections <- vapply(columns, function(column) {
        identifier <- quote_identifier(connection, column)
        type <- safe_duckdb_type(scalar_character(contract$slots[[column]]$duckdb_type))
        paste0("CAST(", identifier, " AS ", type, ") AS ", identifier)
    }, character(1))
    paste0("SELECT ", paste(selections, collapse = ", "), " FROM ", quote_identifier(connection, view_name))
}

definition_where_date.body:
{
    if (!grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$", value)) {
        return(as.Date(NA))
    }
    parsed <- tryCatch(suppressWarnings(as.Date(value)), error = function(condition) as.Date(NA))
    if (is.na(parsed) || !identical(format(parsed, "%Y-%m-%d"), value)) {
        return(as.Date(NA))
    }
    parsed
}

definition_where_integer.body:
{
    if (!grepl("^[+-]?[0-9]+$", value)) {
        return(NA_character_)
    }
    negative <- startsWith(value, "-")
    digits <- sub("^[+-]", "", value)
    digits <- sub("^0+", "", digits)
    if (!nzchar(digits)) {
        digits <- "0"
    }
    limit <- switch(type, INTEGER = if (negative) "2147483648" else "2147483647", BIGINT = if (negative) "9223372036854775808" else "9223372036854775807")
    if (nchar(digits) > nchar(limit) || (nchar(digits) == nchar(limit) && digits > limit)) {
        return(NA_character_)
    }
    value
}

definition_where_predicates.body:
{
    if (is.null(where)) {
        return(list(sql = character(), params = list()))
    }
    if (!is.list(where) || is.data.frame(where)) {
        abort_calculation_error("`where` must be a list of predicate objects.", field = "where", rule = "calculation_where")
    }
    sql <- character()
    params <- list()
    for (index in seq_along(where)) {
        predicate <- where[[index]]
        if (!is.list(predicate) || is.object(predicate) || length(names(predicate)) != 3L || !setequal(names(predicate), c("column", "op", "value")) || !is_nonempty_string(predicate$column) || !is_nonempty_string(predicate$op) || !is.character(predicate$value) || length(predicate$value) != 1L || is.na(predicate$value)) {
            abort_calculation_error("Every `where` predicate needs string `column`, `op`, and `value` fields.", field = "where", rule = "calculation_where", predicate_index = index)
        }
        if (!predicate$op %in% c("=", "!=", "<", "<=", ">", ">=")) {
            abort_calculation_error(paste0("Unsupported `where` operator `", predicate$op, "`."), field = "where", rule = "calculation_where_operator", predicate_index = index)
        }
        slot <- contract$slots[[predicate$column]]
        if (is.null(slot) || !predicate$column %in% definition_public_scalar_columns(contract)) {
            abort_calculation_error(paste0("Unknown public predicate column `", predicate$column, "`."), field = "where", rule = "calculation_where_column", predicate_index = index)
        }
        sql <- c(sql, paste0("\"", gsub("\"", "\"\"", predicate$column, fixed = TRUE), "\" ", predicate$op, " ?"))
        params <- c(params, list(definition_where_value(predicate$value, slot, manifest)))
    }
    list(sql = sql, params = params)
}

definition_where_timestamp.body:
{
    pattern <- paste0("^[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt ]", "[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]+)?", "([Zz]|[+-][0-9]{2}:[0-9]{2})?$")
    if (!grepl(pattern, value)) {
        return(as.POSIXct(NA, tz = "UTC"))
    }
    normalized <- sub("[Tt ]", "T", value)
    normalized <- sub("[Zz]$", "+0000", normalized)
    normalized <- sub("([+-][0-9]{2}):([0-9]{2})$", "\\1\\2", normalized)
    format <- if (grepl("[+-][0-9]{4}$", normalized)) {
        "%Y-%m-%dT%H:%M:%OS%z"
    }
    else {
        "%Y-%m-%dT%H:%M:%OS"
    }
