definition_where_value.body:
{
    enum <- scalar_character(slot$enum)
    if (!is.na(enum)) {
        permissible <- vapply(manifest$enums[[enum]]$permissible_values, function(item) scalar_character(item$value), character(1))
        if (!value %in% permissible) {
            abort_calculation_error(paste0("Predicate value `", value, "` is not in enum `", enum, "`."), field = "where", rule = "calculation_where_value", observed_value = value, expected_type = enum)
        }
        return(value)
    }
    type <- toupper(scalar_character(slot$duckdb_type, "VARCHAR"))
    converted <- switch(type, DOUBLE = definition_where_number(value), FLOAT = definition_where_number(value), DECIMAL = definition_where_number(value), BIGINT = definition_where_integer(value, type), INTEGER = definition_where_integer(value, type), BOOLEAN = if (tolower(value) %in% c("true", "false")) {
        identical(tolower(value), "true")
    } else {
        NA
    }, DATE = definition_where_date(value), TIME = definition_where_time(value), TIMESTAMP = definition_where_timestamp(value), value)
    if (length(converted) != 1L || is.na(converted) || (is.numeric(converted) && !is.finite(converted))) {
        abort_calculation_error(paste0("Predicate value `", value, "` is invalid for `", type, "`."), field = "where", rule = "calculation_where_value", observed_value = value, expected_type = type)
    }
    converted
}

derive_origin_key.body:
{
    explicit <- row[[".graft_origin_key"]]
    if (!is.null(explicit)) {
        value <- explicit[[1L]]
        if (!is.null(value) && length(value) == 1L && !is.na(value)) {
            value <- trimws(as.character(value))
            if (nzchar(value)) {
                return(value)
            }
        }
    }
    slots <- empty_character(class_contract$origin_key_slots)
    if (length(slots) == 0L || !all(slots %in% names(row))) {
        return(NA_character_)
    }
    values <- lapply(slots, function(slot) {
        value <- row[[slot]][[1L]]
        if (is.null(value) || length(value) == 0L || all(is.na(value))) {
            return(NULL)
        }
        unname(value)
    })
    if (any(vapply(values, is.null, logical(1)))) {
        return(NA_character_)
    }
    names(values) <- slots
    paste0("graft-origin-v1:", digest::digest(canonical_identity_value(values), algo = "sha256", serialize = FALSE))
}

deterministic_graft_id.body:
{
    payload <- paste0(graft_identity_algorithm, "\037", record_class, "\037", canonical_identity_value(values))
