exact_numeric_lexeme_fits_storage.body:
{
    negative <- startsWith(value, "-")
    unsigned <- sub("^-", "", value)
    if (integer) {
        limit <- if (negative) {
            "9223372036854775808"
        }
        else {
            "9223372036854775807"
        }
        return(decimal_digits_less_than_or_equal(unsigned, limit))
    }
    parts <- strsplit(unsigned, ".", fixed = TRUE)[[1L]]
    whole <- parts[[1L]]
    fraction <- if (length(parts) == 1L) 
        ""
    else parts[[2L]]
    nchar(whole) <= 15L && nchar(fraction) <= 3L
}

