graft_calculate.body:
{
    read_source <- as_graft_read_store_internal(source, "source")
    validate_graft_retrieval(read_source)
    if (!is_graft_snapshot_backend(read_source)) {
        read_source <- as_graft_read_store_internal(graft_at(source, graft_snapshot(source)), "source")
    }
    metrics <- definition_name_argument(metrics, "metrics", required = TRUE)
    dimensions <- definition_name_argument(dimensions, "dimensions")
    filters <- definition_name_argument(filters, "filters")
    catalog <- definition_calculation_catalog(read_source, metrics)
    selected_metrics <- definition_resolve_many(catalog, metrics, kind = "metric", argument = "metrics")
    targets <- unique(selected_metrics$target)
    if (length(targets) != 1L) {
        abort_calculation_error("All requested metrics must target the same public table.", field = "metrics", rule = "calculation_single_target", observed_value = targets)
    }
    target <- targets[[1L]]
    contract <- definition_target_contract(read_source$schema$manifest, target)
    columns <- definition_public_scalar_columns(contract)
    selected_filters <- definition_resolve_many(catalog, filters, kind = "filter", target = target, argument = "filters")
    selected_dimensions <- definition_resolve_dimensions(catalog, dimensions, target, columns)
    compiler <- new.env(parent = emptyenv())
    compiler$catalog <- catalog
    compiler$columns <- columns
    compiler$target <- target
    compiler$compiled <- list()
    compiler$active <- character()
    metric_code <- lapply(seq_len(nrow(selected_metrics)), function(index) definition_compile_row(selected_metrics[index, ], compiler))
    filter_code <- lapply(seq_len(nrow(selected_filters)), function(index) definition_compile_row(selected_filters[index, ], compiler))
    dimension_code <- lapply(selected_dimensions, function(dimension) {
        if (identical(dimension$kind, "column")) {
            return(list(sql = as.character(quote_identifier(read_source$connection, dimension$name)), definition_ids = character()))
        }
        definition_compile_row(dimension$row, compiler)
    })
    where <- definition_where_predicates(where, contract, read_source$schema$manifest)
    frame <- definition_target_frame(read_source, contract, typed = FALSE)
    view_name <- "_graft_definition_target"
    duckdb::duckdb_register(read_source$connection, view_name, frame)
    on.exit(duckdb::duckdb_unregister(read_source$connection, view_name), add = TRUE)
    source_sql <- definition_target_source_sql(read_source$connection, view_name, contract)
    dimension_select <- Map(function(dimension, code) {
        paste0(code$sql, " AS ", quote_identifier(read_source$connection, dimension$name))
    }, selected_dimensions, dimension_code)
    metric_select <- Map(function(index, code) {
        paste0(code$sql, " AS ", quote_identifier(read_source$connection, selected_metrics$name[[index]]))
    }, seq_len(nrow(selected_metrics)), metric_code)
    predicates <- c(vapply(filter_code, `[[`, character(1), "sql"), where$sql)
    grouped <- vapply(dimension_code, `[[`, character(1), "sql")
    limit <- graft_retrieval_limits$calculation_rows
    query <- paste0("SELECT ", paste(c(dimension_select, metric_select), collapse = ", "), " FROM ", "(", source_sql, ") definition_target", if (length(predicates) > 0L) {
        paste0(" WHERE ", paste0("(", predicates, ")", collapse = " AND "))
    }
    else {
        ""
    }, if (length(grouped) > 0L) {
        paste0(" GROUP BY ", paste(grouped, collapse = ", "), " ORDER BY ", paste(grouped, collapse = ", "))
    }
    else {
        " HAVING COUNT(*) >= 0"
    }, " LIMIT ", limit + 1L)
    result <- tryCatch(retrieval_query(read_source$connection, query, params = where$params), error = function(error) {
        abort_calculation_error("The accepted calculation could not be evaluated.", rule = "calculation_execution", parent = error)
    })
    if (nrow(result) > limit) {
        abort_calculation_error(paste0("The grouped calculation exceeds the hard row bound of ", limit, "."), rule = "calculation_row_bound", limit = limit)
    }
    definition_ids <- unique(c(unlist(lapply(metric_code, `[[`, "definition_ids"), use.names = FALSE), unlist(lapply(filter_code, `[[`, "definition_ids"), use.names = FALSE), unlist(lapply(dimension_code, `[[`, "definition_ids"), use.names = FALSE)))
    receipt_definitions <- catalog[match(definition_ids, catalog$id), c("id", "revision_id", "kind"), drop = FALSE]
    receipt_definitions <- receipt_definitions[order(receipt_definitions$id, method = "radix"), , drop = FALSE]
    rownames(result) <- NULL
    attr(result, "definitions") <- receipt_definitions
    attr(result, "store_schema_digest") <- store_schema_digest(read_source)
    result
}

graft_calculate_tool.body:
{
    ellmer::tool(function(metrics, dimensions = NULL, filters = NULL, where = NULL) {
        context <- graft_tool_context(store)
        result <- graft_calculate(context$store, metrics = metrics, dimensions = dimensions, filters = filters, where = where)
        definitions <- attr(result, "definitions")
        context$receipt$definitions <- lapply(seq_len(nrow(definitions)), function(index) {
            list(id = definitions$id[[index]], revision_id = definitions$revision_id[[index]], kind = definitions$kind[[index]])
        })
        graft_tool_result(result, truncated = FALSE, limit = graft_retrieval_limits$calculation_rows, receipt = context$receipt)
    }, name = "graft_calculate", description = paste("Compose accepted same-table metrics, dimensions, filters, and simple", "predicates over one exact accepted boundary. No SQL is accepted."), arguments = list(metrics = ellmer::type_array(ellmer::type_string("An accepted metric name."), "One or more accepted metrics."), dimensions = ellmer::type_array(ellmer::type_string("A public column or accepted derived definition."), "Optional grouping dimensions.", required = FALSE), filters = ellmer::type_array(ellmer::type_string("An accepted filter definition."), 
        "Optional accepted filters.", required = FALSE), where = graft_tool_where_type(required = FALSE)), annotations = annotations)
}

