    retrieval_query(store$connection, paste0("SELECT * FROM (", paste(branches, collapse = " UNION ALL "), ") candidates", restriction, " ORDER BY class, record_id, revision_id LIMIT ", page_size), params = c(params, cursor_params))
}

graft_claim_result_matches.body:
{
    matches_entity <- vapply(seq_len(nrow(result)), function(index) {
        if (identical(result$statement_shape[[index]], "narrative")) {
            identical(result$primary_subject[[index]], entity_id) || entity_id %in% result$about[[index]]
        }
        else {
            identical(result$subject[[index]], entity_id) || identical(result$object_entity[[index]], entity_id)
        }
    }, logical(1))
    keep <- matches_entity
    if (!include_superseded) {
        keep <- keep & (is.na(result$status) | result$status == "active")
    }
    if (!is.null(predicate)) {
        keep <- keep & !is.na(result$predicate) & result$predicate == predicate
    }
    keep
}

graft_claim_rows.body:
{
    limit <- validate_result_limit(limit, hard_limit = graft_retrieval_limits$claims)
    predicate <- validate_optional_scalar_text(predicate, "predicate")
    include_superseded <- validate_graft_include_superseded(include_superseded)
    classes <- statement_classes(store)
    branches <- list()
    params <- list()
    for (record_class in sort(classes, method = "radix")) {
        branches[[length(branches) + 1L]] <- paste0("SELECT current.record_id, current.class, current.revision_id, ", "current.schema_build_digest, current.payload_json, ", "current.content_digest, current.recorded_at FROM (", graft_read_source_sql(store), ") current WHERE current.class = ", graft_sql_string(store$connection, record_class), " AND LOWER(current.payload_json) LIKE ? ESCAPE '\\'")
        params <- c(params, list(paste0("%", escape_graft_like(tolower(canonical_json(entity_id))), "%")))
    }
    if (length(branches) == 0L) {
        return(empty_graft_claims(store, limit))
    }
    rows <- graft_collect_candidate_rows(store, branches, params, limit, function(page) {
        result <- bind_public_rows(lapply(seq_len(nrow(page)), function(index) {
            graft_claim_result_row(store, page[index, , drop = FALSE])
        }))
