graft_collect_candidate_rows.body:
{
    page_size <- graft_candidate_page_size()
    cursor <- NULL
    matches <- list()
    match_count <- 0L
    target <- limit + 1L
    repeat {
        page <- graft_candidate_page(store, branches, params, cursor, page_size)
        if (nrow(page) == 0L) {
            break
        }
        keep <- keep_page(page)
        if (!is.logical(keep) || length(keep) != nrow(page) || anyNA(keep)) {
            abort_backend_error("A retrieval page filter returned an invalid selection.", operation = "graft_retrieval")
        }
        if (any(keep)) {
            selected <- page[keep, , drop = FALSE]
            matches[[length(matches) + 1L]] <- selected
            match_count <- match_count + nrow(selected)
        }
        if (match_count >= target) {
            break
        }
        cursor <- page[nrow(page), c("class", "record_id", "revision_id")]
        if (nrow(page) < page_size) {
            break
        }
    }
    if (length(matches) == 0L) {
        return(data.frame(record_id = character(), class = character(), revision_id = character(), schema_build_digest = character(), payload_json = character(), content_digest = character(), recorded_at = as.POSIXct(character(), tz = "UTC")))
    }
    rows <- dplyr::bind_rows(matches)
    if (nrow(rows) > target) {
        rows <- rows[seq_len(target), , drop = FALSE]
    }
    rows
}

