graft_evidence_rows.body:
{
    limit <- validate_result_limit(limit, hard_limit = graft_retrieval_limits$evidence)
    support_type <- validate_optional_scalar_text(support_type, "support_type")
    classes <- role_classes(store, "evidence")
    branches <- list()
    params <- list()
    for (record_class in sort(classes, method = "radix")) {
        contract <- store$schema$manifest$classes[[record_class]]
        where <- character()
        branch_params <- list()
        if (!is.null(statement_ids)) {
            statement_ids <- unique(as.character(statement_ids))
            where <- c(where, paste0("(", paste(rep("LOWER(current.payload_json) LIKE ? ESCAPE '\\'", length(statement_ids)), collapse = " OR "), ")"))
            branch_params <- c(branch_params, lapply(statement_ids, function(id) {
                paste0("%", escape_graft_like(tolower(canonical_json(id))), "%")
            }))
        }
        if (!is.null(source_id)) {
            where <- c(where, "LOWER(current.payload_json) LIKE ? ESCAPE '\\'")
            branch_params <- c(branch_params, list(paste0("%", escape_graft_like(tolower(canonical_json(source_id))), "%")))
        }
        if (!is.null(support_type)) {
            validate_graft_evidence_support_type(store, contract, support_type)
            where <- c(where, "LOWER(current.payload_json) LIKE ? ESCAPE '\\'")
            branch_params <- c(branch_params, list(paste0("%", escape_graft_like(tolower(canonical_json(support_type))), "%")))
        }
        branches[[length(branches) + 1L]] <- paste0("SELECT current.record_id, current.class, current.revision_id, ", "current.schema_build_digest, current.payload_json, ", "current.content_digest, current.recorded_at FROM (", graft_read_source_sql(store), ") current WHERE current.class = ", graft_sql_string(store$connection, record_class), if (length(where) > 0L) {
            paste0(" AND ", paste(where, collapse = " AND "))
        }
        else {
            ""
        })
        params <- c(params, branch_params)
    }
    if (length(branches) == 0L) {
        return(empty_graft_evidence(store, limit))
    }
    rows <- graft_collect_candidate_rows(store, branches, params, limit, function(page) {
        records <- lapply(seq_len(nrow(page)), function(index) {
            graft_public_current_record(store, page[index, , drop = FALSE])
        })
        graft_evidence_records_match(store, records, statement_ids, source_id, support_type, entity_id)
    })
    if (nrow(rows) == 0L) {
        return(empty_graft_evidence(store, limit))
    }
    records <- lapply(seq_len(nrow(rows)), function(index) {
        graft_public_current_record(store, rows[index, , drop = FALSE])
    })
    truncated <- nrow(rows) > limit
    if (nrow(rows) > limit) {
        rows <- rows[seq_len(limit), , drop = FALSE]
        records <- records[seq_len(limit)]
    }
    if (nrow(rows) == 0L) {
        return(empty_graft_evidence(store, limit))
    }
    source_ids <- unique(vapply(records, function(record) as.character(retrieval_record_scalar(record, "source_id")), character(1)))
    sources <- graft_current_rows(store, ids = source_ids, limit = length(source_ids))
    source_map <- list()
    for (index in seq_len(nrow(sources))) {
        source_record <- graft_public_current_record(store, sources[index, , drop = FALSE])
        source_map[[sources$record_id[[index]]]] <- list(class = sources$class[[index]], record = source_record)
    }
    result <- bind_public_rows(lapply(seq_len(nrow(rows)), function(index) {
        graft_evidence_result_row(store, rows$class[[index]], records[[index]], source_map)
    }))
    bounded_data_frame(result, store, limit, truncated)
}

graft_find.body:
{
    store <- as_graft_read_store_internal(store, "store")
    validate_graft_retrieval(store)
    query <- validate_scalar_text(query, "query")
    limit <- validate_result_limit(limit, hard_limit = graft_retrieval_limits$find)
    classes <- if (is.null(class)) {
        public_class_names(store)
    }
    else {
        validate_public_class(store, class)
        class
    }
    branches <- list()
    params <- list()
    for (record_class in sort(classes, method = "radix")) {
        contract <- store$schema$manifest$classes[[record_class]]
        fields <- graft_search_fields(contract)
        if (length(fields) == 0L) {
            next
        }
        branches[[length(branches) + 1L]] <- paste0("SELECT current.record_id, current.class, current.revision_id, ", "current.schema_build_digest, current.payload_json, ", "current.content_digest, current.recorded_at FROM (", graft_read_source_sql(store), ") AS current WHERE current.class = ", graft_sql_string(store$connection, record_class), " AND LOWER(current.payload_json) LIKE ? ESCAPE '\\'")
        params <- c(params, list(paste0("%", escape_graft_like(tolower(query)), "%")))
    }
    if (length(branches) == 0L) {
        return(empty_graft_find(store, limit))
    }
    rows <- graft_collect_candidate_rows(store, branches, params, limit, function(page) {
        records <- lapply(seq_len(nrow(page)), function(index) {
            graft_public_current_record(store, page[index, , drop = FALSE])
        })
        vapply(seq_len(nrow(page)), function(index) {
            contract <- store$schema$manifest$classes[[page$class[[index]]]]
            fields <- graft_search_fields(contract)
            any(vapply(fields, function(field) {
                value <- records[[index]][[field]]
                !is.null(value) && grepl(tolower(query), tolower(canonical_json(value)), fixed = TRUE)
            }, logical(1)))
        }, logical(1))
    })
    records <- lapply(seq_len(nrow(rows)), function(index) {
        graft_public_current_record(store, rows[index, , drop = FALSE])
    })
    matched <- lapply(seq_len(nrow(rows)), function(index) {
        contract <- store$schema$manifest$classes[[rows$class[[index]]]]
        fields <- graft_search_fields(contract)
        fields[vapply(fields, function(field) {
            value <- records[[index]][[field]]
            !is.null(value) && grepl(tolower(query), tolower(canonical_json(value)), fixed = TRUE)
        }, logical(1))]
    })
    keep <- lengths(matched) > 0L
    rows <- rows[keep, , drop = FALSE]
    records <- records[keep]
    matched <- matched[keep]
    truncated <- nrow(rows) > limit
    if (nrow(rows) > limit) {
        rows <- rows[seq_len(limit), , drop = FALSE]
        records <- records[seq_len(limit)]
        matched <- matched[seq_len(limit)]
    }
    labels <- vapply(seq_len(nrow(rows)), function(index) {
        contract <- store$schema$manifest$classes[[rows$class[[index]]]]
        graft_record_label(records[[index]], contract)
    }, character(1))
    result <- data.frame(id = rows$record_id, class = rows$class, label = labels, stringsAsFactors = FALSE)
    result$matched_fields <- I(matched)
    result$record <- I(records)
    bounded_data_frame(result, store, limit, truncated)
}

graft_get.body:
{
    store <- as_graft_read_store_internal(store, "store")
    validate_graft_retrieval(store)
    id <- validate_scalar_text(id, "id", condition = abort_reference_error)
    include <- validate_graft_get_include(include)
    limits <- validate_graft_get_limits(limits)
    row <- graft_current_rows(store, ids = id, limit = 1L)
    if (nrow(row) == 0L) {
        abort_reference_error(paste0("Record `", id, "` was not found."), record_id = id, field = "id", rule = "record_exists", observed_value = id)
    }
    record <- graft_public_current_record(store, row[1L, , drop = FALSE])
    related <- list()
    truncated <- list()
    if ("identifiers" %in% include) {
        related$identifiers <- graft_identifier_rows(store, id, limits$identifiers)
        truncated$identifiers <- isTRUE(attr(related$identifiers, "truncated"))
    }
    claims <- NULL
    if ("claims" %in% include || "evidence" %in% include) {
        claims <- graft_claim_rows(store, id, limit = limits$claims)
        if ("claims" %in% include) {
            related$claims <- claims
            truncated$claims <- isTRUE(attr(claims, "truncated"))
        }
    }
    if ("evidence" %in% include) {
        role <- scalar_character(store$schema$manifest$classes[[row$class[[1L]]]]$role)
        related$evidence <- if (identical(role, "statement")) {
            graft_evidence_rows(store, statement_ids = id, limit = limits$evidence)
        }
        else if (identical(role, "source")) {
            graft_evidence_rows(store, source_id = id, limit = limits$evidence)
        }
        else if (identical(role, "node")) {
            graft_evidence_rows(store, entity_id = id, limit = limits$evidence)
        }
        else {
            empty_graft_evidence(store, limits$evidence)
        }
        truncated$evidence <- isTRUE(attr(related$evidence, "truncated"))
    }
    list(id = id, class = row$class[[1L]], record = record, related = related, limits = limits[include], truncated = truncated, store_schema_digest = store_schema_digest(store))
}

