graft_history_engine.body:
{
    validate_retrieval_store(store)
    id <- validate_scalar_text(id, "id", condition = abort_reference_error)
    limit <- validate_result_limit(limit, hard_limit = graft_retrieval_limits$history)
    boundary <- resolve_effective_history_boundary(store, as_of)
    class_boundary_sql <- ""
    class_params <- list(id)
    if (!is.null(boundary$commit_order)) {
        class_boundary_sql <- " AND r.commit_order <= ?"
        class_params <- c(class_params, list(boundary$commit_order))
    }
    record_classes <- with_duckdb_error("record_history_class", DBI::dbGetQuery(store$connection, paste0("SELECT DISTINCT r.class FROM ", quote_identifier(store$connection, "_graft_record_revisions"), " r INNER JOIN ", quote_identifier(store$connection, "_graft_batches"), " b ON r.batch_id = b.batch_id WHERE b.status = 'committed' ", "AND r.record_id = ?", class_boundary_sql, " ORDER BY r.class"), params = class_params))
    if (nrow(record_classes) == 0L) {
        abort_reference_error(paste0("Record `", id, "` has no accepted history."), record_id = id, field = "id", rule = "record_history_exists", observed_value = id)
    }
    if (nrow(record_classes) != 1L) {
        abort_identity_error(paste0("Record `", id, "` has history in multiple classes."), record_id = id, field = "id", rule = "unique_record_history_class", observed_value = id, matched_classes = record_classes$class)
    }
    values <- list(record_id = id)
    columns <- c(record_id = "r.record_id")
    operators <- character()
    if (!is.null(boundary$commit_order)) {
        values$commit_order <- boundary$commit_order
        columns <- c(columns, commit_order = "r.commit_order")
        operators <- c(operators, commit_order = "<=")
    }
    filters <- history_sql_filters(store, values = values, columns = columns, operators = operators)
    rows <- query_history_revisions(store, filters, limit)
    if (nrow(rows) == 0L) {
        graft_abort("graft_history_boundary_error", paste0("Record `", id, "` was not accepted at the requested history boundary."), record_id = id, as_of = as_of, boundary_commit_order = boundary$commit_order)
    }
    result <- hydrate_history_rows(rows, store, limit)
    attr(result, "as_of") <- as_of
    attr(result, "as_of_commit_order") <- boundary$commit_order
    attr(result, "as_of_batch_id") <- boundary$batch_id
    result
}

