{
    namespace <- validate_scalar_text(namespace, "namespace")
    value <- validate_scalar_text(value, "value")
    versions <- store$schema$manifest$identifier_normalization_versions
    if (!namespace %in% names(versions)) {
        abort_validation_error(paste0("Unknown identifier namespace `", namespace, "` for the active manifest."), field = "namespace", rule = "manifest_identifier_namespace", observed_value = namespace)
    }
    eligible <- graft_identifier_namespace_classes(store, namespace)
    if (length(eligible) == 0L) {
        abort_validation_error(paste0("Identifier namespace `", namespace, "` is not declared by a public concrete class."), field = "namespace", rule = "public_identifier_namespace", observed_value = namespace)
    }
    if (!is.null(class)) {
        validate_public_class(store, class)
        if (!class %in% eligible) {
            abort_validation_error(paste0("Class `", class, "` does not declare identifier namespace `", namespace, "`."), record_class = class, field = "namespace", rule = "class_identifier_namespace", observed_value = namespace)
        }
        eligible <- class
    }
    normalized <- normalize_graft_identifier(store, namespace, value)
    if (is.na(normalized) || !nzchar(normalized)) {
        abort_validation_error("`value` is empty after identifier normalization.", field = "value", rule = "normalized_identifier", observed_value = value, namespace = namespace)
    }
    if (is_graft_snapshot_backend(store)) {
        rows <- snapshot_identifier_registry(store)
        rows <- rows[rows$namespace == namespace & rows$normalized_value == normalized & rows$status %in% c("primary", "equivalent") & rows$class %in% eligible, , drop = FALSE]
        rows <- rows[order(rows$class, rows$record_id, rows$status, rows$created_at), , drop = FALSE]
        rownames(rows) <- NULL
    }
    else {
        placeholders <- paste(rep("?", length(eligible)), collapse = ", ")
        rows <- retrieval_query(store$connection, paste0("SELECT record_id, class, namespace, value, normalized_value, ", "status, assigned_by, confidence, created_at FROM ", quote_identifier(store$connection, "_graft_identifiers"), " WHERE namespace = ? AND normalized_value = ?", " AND status IN ('primary', 'equivalent')", " AND class IN (", placeholders, ") ORDER BY class, record_id, status, created_at"), params = c(list(namespace, normalized), as.list(eligible)))
    }
    duplicate <- split(rows$record_id, rows$class)
    inconsistent <- names(Filter(function(.x) length(unique(.x)) > 1L, duplicate))
    if (length(inconsistent) > 0L) {
        abort_identity_error(paste0("The active identifier maps to multiple records in class `", inconsistent[[1L]], "`."), record_class = inconsistent[[1L]], field = "value", rule = "unique_active_identifier", observed_value = value, namespace = namespace, normalized_value = normalized, matched_record_ids = unique(duplicate[[inconsistent[[1L]]]]))
    }
    bounded_data_frame(rows, store, limit = max(1L, length(eligible)), truncated = FALSE)
}

