    commit_order <- format(snapshot$commit_order, scientific = FALSE, trim = TRUE)
    revision <- quote_identifier(store$connection, "_graft_record_revisions")
    batch <- quote_identifier(store$connection, "_graft_batches")
    paste0("SELECT record_id, class, revision_id, revision_number, ", "schema_build_digest, payload_json, content_digest, recorded_at, ", "commit_order FROM (SELECT r.record_id, r.class, r.revision_id, ", "r.revision_number, r.schema_build_digest, r.payload_json, ", "r.content_digest, r.recorded_at, r.commit_order, r.operation, ", "ROW_NUMBER() OVER (PARTITION BY r.class, r.record_id ORDER BY ", "r.commit_order DESC, r.revision_number DESC, r.revision_id ASC) ", "AS graft_snapshot_rank FROM ", revision, 
        " r INNER JOIN ", batch, " b ON r.batch_id = b.batch_id WHERE b.status = 'committed' ", "AND r.commit_order <= ", commit_order, ") snapshot_current WHERE graft_snapshot_rank = 1 ", "AND operation <> 'delete'")
}

