graft_verification_blockquote_candidates.body:
{
    lines <- strsplit(text, "\\r?\\n", perl = TRUE)[[1L]]
    is_marker <- grepl("^[ ]{0,3}>", lines, perl = TRUE)
    blocks <- list()
    index <- 1L
    while (index <= length(lines)) {
        if (!is_marker[[index]]) {
            index <- index + 1L
            next
        }
        block <- character()
        paragraph_active <- FALSE
        while (index <= length(lines)) {
            line <- lines[[index]]
            if (is_marker[[index]]) {
                stripped <- sub("^(?:[ ]{0,3}>[ \\t]?)+", "", line, perl = TRUE)
                block <- c(block, stripped)
                paragraph_active <- graft_verification_markdown_paragraph_line(stripped)
            }
            else if (paragraph_active && nzchar(trimws(line)) && (grepl("^(?: {4}|\\t)", line, perl = TRUE) || graft_verification_markdown_paragraph_line(line))) {
                block <- c(block, line)
            }
            else {
                break
            }
            index <- index + 1L
        }
        blocks[[length(blocks) + 1L]] <- paste(block, collapse = "\n")
    }
    candidates <- lapply(blocks, function(candidate) graft_verification_candidate(candidate, "blockquote"))
    Filter(Negate(is.null), candidates)
}

