graft_verification_classify.body:
{
    if (length(window$tool_calls) == 0L && !window$unsupported) {
        return(list(label = "untrusted", reason_codes = "no_evidence", citations = list(), diagnostics = character()))
    }
    reason_order <- c("governed_calculation_only", "matched_citations", "no_evidence", "non_graft_tool", "tool_error", "invalid_receipt", "unmatched_citation", "unsupported_trace")
    reasons <- stats::setNames(rep(FALSE, length(reason_order)), reason_order)
    reasons[["unsupported_trace"]] <- window$unsupported
    calculation_count <- 0L
    generic_count <- 0L
    matched_generic_count <- 0L
    citations <- list()
    truncated <- FALSE
    boundary_keys <- character()
    supported <- c("graft_find", "graft_get", "graft_query", "graft_history", "graft_definitions", "graft_calculate")
    for (call_index in seq_along(window$tool_calls)) {
        call <- window$tool_calls[[call_index]]
        request <- call$request
        result <- call$result
        if (!is.null(result) && !is.null(result@error)) {
            reasons[["tool_error"]] <- TRUE
        }
        if (is.null(request)) {
            next
        }
        name <- request@name
        if (!name %in% supported) {
            reasons[["non_graft_tool"]] <- TRUE
            next
        }
        if (is.null(result)) {
            next
        }
        if (!is.null(result@error)) {
            next
        }
        if (!graft_verification_receipt_valid(name, result@value)) {
            reasons[["invalid_receipt"]] <- TRUE
            next
        }
        truncated <- truncated || result@value$truncated
        receipt <- result@value$receipt
        boundary_keys <- c(boundary_keys, canonical_json(list(store_id = receipt$store$id, batch_id = receipt$boundary$batch_id, commit_order = receipt$boundary$commit_order)))
        if (identical(name, "graft_calculate")) {
            calculation_count <- calculation_count + 1L
        }
        else {
            generic_count <- generic_count + 1L
            matches <- graft_verification_match_citations(answer_text, result@value$result, call_index)
            if (length(matches) == 0L) {
                reasons[["unmatched_citation"]] <- TRUE
            }
            else {
                matched_generic_count <- matched_generic_count + 1L
                citations <- c(citations, matches)
            }
        }
    }
    observed <- names(reasons)[reasons]
    diagnostics <- character()
    if (truncated) {
        diagnostics <- c(diagnostics, "truncated_result")
    }
    if (length(unique(boundary_keys)) > 1L) {
        diagnostics <- c(diagnostics, "mixed_boundaries")
    }
    if (length(observed) == 0L && generic_count > 0L && identical(matched_generic_count, generic_count)) {
        return(list(label = "cited", reason_codes = "matched_citations", citations = citations, diagnostics = diagnostics))
    }
    if (length(observed) == 0L && calculation_count > 0L) {
        return(list(label = "verified", reason_codes = "governed_calculation_only", citations = citations, diagnostics = diagnostics))
    }
    list(label = "untrusted", reason_codes = observed, citations = citations, diagnostics = diagnostics)
}

