graft_verification_strip_emphasis.body:
{
    xml <- commonmark::markdown_xml(text, sourcepos = TRUE)
    pattern <- paste0("<(emph|strong) sourcepos=\"", "([0-9]+):([0-9]+)-([0-9]+):([0-9]+)\"")
    matches <- regmatches(xml, gregexpr(pattern, xml, perl = TRUE))[[1L]]
    if (length(matches) == 0L) {
        return(text)
    }
    captures <- do.call(rbind, lapply(matches, function(match) {
        regmatches(match, regexec(pattern, match, perl = TRUE))[[1L]]
    }))
    ranges <- data.frame(type = captures[, 2L], start_line = as.integer(captures[, 3L]), start_column = as.integer(captures[, 4L]), end_line = as.integer(captures[, 5L]), end_column = as.integer(captures[, 6L]))
    ranges$width <- ifelse(ranges$type == "strong", 2L, 1L)
    range_key <- paste(ranges$start_line, ranges$start_column, ranges$end_line, ranges$end_column, sep = ":")
    groups <- split(seq_len(nrow(ranges)), range_key)
    lines <- strsplit(text, "\\r?\\n", perl = TRUE)[[1L]]
    bytes <- lapply(lines, charToRaw)
    removed <- lapply(bytes, function(line) rep(FALSE, length(line)))
    for (indices in groups) {
        range <- ranges[indices[[1L]], , drop = FALSE]
        width <- sum(ranges$width[indices])
        if (range$start_line > length(bytes) || range$end_line > length(bytes)) {
            next
        }
        start <- range$start_column + seq_len(width) - 1L
        end <- seq.int(range$end_column - width + 1L, range$end_column)
        if (any(start > length(bytes[[range$start_line]])) || any(end < 1L) || any(end > length(bytes[[range$end_line]]))) {
            next
        }
        markers <- c(bytes[[range$start_line]][start], bytes[[range$end_line]][end])
        if (!all(as.integer(markers) %in% c(42L, 95L)) || length(unique(as.integer(markers))) != 1L) {
            next
        }
        removed[[range$start_line]][start] <- TRUE
        removed[[range$end_line]][end] <- TRUE
    }
    lines <- Map(function(line, drop) rawToChar(line[!drop]), bytes, removed)
    paste(unlist(lines, use.names = FALSE), collapse = "\n")
}

