            }
            else if (inherits(content, "ellmer::ContentToolResult")) {
                if (!inherits(turn, "ellmer::UserTurn")) {
                  unsupported <- TRUE
                }
                results[[length(results) + 1L]] <- content
            }
            else {
                unsupported <- TRUE
            }
        }
    }
    calls <- lapply(requests, function(request) list(request = request, result = NULL))
    ids <- vapply(requests, function(request) {
        if (is_nonempty_string(request@id)) 
            request@id
        else NA_character_
    }, character(1))
    request_names <- vapply(requests, function(request) {
        if (is_nonempty_string(request@name)) 
            request@name
        else NA_character_
    }, character(1))
    if (anyNA(ids) || anyNA(request_names) || anyDuplicated(ids[!is.na(ids)])) {
        unsupported <- TRUE
    }
    seen_result_ids <- character()
    for (result in results) {
        linked <- result@request
        linked_valid <- !is.null(linked) && inherits(linked, "ellmer::ContentToolRequest") && is_nonempty_string(linked@id) && is_nonempty_string(linked@name)
        if (!linked_valid) {
            unsupported <- TRUE
            calls[[length(calls) + 1L]] <- list(request = NULL, result = result)
            next
        }
        if (linked@id %in% seen_result_ids) {
            unsupported <- TRUE
        }
        seen_result_ids <- c(seen_result_ids, linked@id)
        matching <- which(ids == linked@id & request_names == linked@name)
        if (length(matching) == 1L && is.null(calls[[matching]]$result)) {
            calls[[matching]]$result <- result
            next
        }
        if (length(matching) > 0L || any(ids == linked@id, na.rm = TRUE)) {
            unsupported <- TRUE
        }
        calls[[length(calls) + 1L]] <- list(request = linked, result = result)
    }
    if (length(calls) > 0L && any(vapply(calls, function(call) is.null(call$result), logical(1)))) {
        unsupported <- TRUE
    }
    list(tool_calls = calls, receipts = lapply(calls, function(call) {
        value <- if (is.null(call$result)) NULL else call$result@value
        if (is.list(value)) value[["receipt", exact = TRUE]] else NULL
    }), unsupported = unsupported)
}

graft_verify.body:
{
    if (!inherits(chat, "Chat")) {
        abort_validation_error("`chat` must be an ellmer Chat object.", argument = "chat")
    }
    turns <- tryCatch(chat$get_turns(), error = function(error) {
        abort_validation_error("`chat$get_turns()` failed while reading recorded turns.", argument = "chat", parent = error)
    })
    if (!is.list(turns)) {
        abort_validation_error("`chat$get_turns()` must return a list of turns.", argument = "chat")
    }
    answer_turns <- which(vapply(turns, is_graft_verification_answer, logical(1)))
    if (length(answer_turns) == 0L) {
        return(new_graft_verification())
    }
    window_starts <- c(1L, utils::head(answer_turns, -1L) + 1L)
    windows <- Map(function(start, end) graft_verification_window(turns[start:end]), window_starts, answer_turns)
    answer_text <- vapply(turns[answer_turns], function(turn) turn@text, character(1))
    classifications <- Map(graft_verification_classify, windows, answer_text)
    result <- data.frame(answer_index = seq_along(answer_turns), turn_index = as.integer(answer_turns), answer_text = answer_text, label = vapply(classifications, `[[`, character(1), "label"))
    result$reason_codes <- lapply(classifications, `[[`, "reason_codes")
    result$receipts <- lapply(windows, `[[`, "receipts")
    result$citations <- lapply(classifications, `[[`, "citations")
    result$tool_calls <- lapply(windows, `[[`, "tool_calls")
    result$diagnostics <- lapply(classifications, `[[`, "diagnostics")
    new_graft_verification(result)
}

