graph_collect_frontier_edges.body:
{
    if (!is.null(graph)) {
        rows <- if (identical(projection, "semantic")) {
            graph$semantic
        }
        else if (identical(projection, "provenance")) {
            graph$provenance
        }
        else {
            dplyr::bind_rows(graph$semantic, graph$provenance)
        }
        return(graph_filter_frontier_edges(rows, frontier, predicate, direction, limit))
    }
    if (is_graft_snapshot_backend(store)) {
        return(snapshot_graph_frontier_edges(store, frontier, predicate, direction, projection, limit))
    }
    connection <- store$connection
    placeholders <- paste(rep("?", length(frontier)), collapse = ", ")
    if (identical(direction, "out")) {
        incidence <- paste0("subject IN (", placeholders, ")")
        params <- as.list(frontier)
    }
    else if (identical(direction, "in")) {
        incidence <- paste0("object IN (", placeholders, ")")
        params <- as.list(frontier)
    }
    else {
        incidence <- paste0("(subject IN (", placeholders, ") OR object IN (", placeholders, "))")
        params <- c(as.list(frontier), as.list(frontier))
    }
    predicate_sql <- ""
    if (!is.null(predicate)) {
        predicate_sql <- " AND predicate = ?"
        params <- c(params, list(predicate))
    }
    sql <- paste0("SELECT edge_id, subject, predicate, object, edge_class, source_table, ", "created_at FROM (", graph_normalized_edges_sql(connection, projection), ") AS graft_graph_edges WHERE ", incidence, predicate_sql, graph_edge_order_sql(), " LIMIT ", limit + 1L)
    rows <- with_duckdb_error("graph_neighbors", DBI::dbGetQuery(connection, sql, params = params))
    truncated <- nrow(rows) > limit
    if (truncated) {
        rows <- rows[seq_len(limit), , drop = FALSE]
    }
    rownames(rows) <- NULL
    attr(rows, "truncated") <- truncated
    rows
}

graph_collect_nodes.body:
{
    if (length(ids) == 0L) {
        return(graph_empty_node_data())
    }
    if (!is.null(graph)) {
        rows <- graph$nodes[graph$nodes$id %in% ids, , drop = FALSE]
        rows <- rows[order(rows$id, rows$class), , drop = FALSE]
        rownames(rows) <- NULL
        return(rows)
    }
    if (is_graft_snapshot_backend(store)) {
        return(snapshot_graph_nodes_for_ids(store, ids))
    }
    placeholders <- paste(rep("?", length(ids)), collapse = ", ")
    sql <- paste0("SELECT id, class, label, role, statement_shape, type_uri, created_at FROM ", quote_identifier(store$connection, "_graft_nodes"), " WHERE id IN (", placeholders, ") ORDER BY id ASC, class ASC")
    rows <- with_duckdb_error("graph_nodes", DBI::dbGetQuery(store$connection, sql, params = as.list(ids)))
    rownames(rows) <- NULL
    rows
}

