graph_expand.body:
{
    visited <- sort(unique(roots))
    frontier <- visited
    edges <- graph_empty_edge_data()
    truncated <- FALSE
    for (predicate in predicates) {
        if (length(frontier) == 0L) {
            break
        }
        remaining_edges <- limits$max_edges - nrow(edges)
        candidates <- graph_collect_frontier_edges(store = store, frontier = frontier, predicate = predicate, direction = direction, projection = projection, limit = remaining_edges, graph = graph)
        truncated <- truncated || isTRUE(attr(candidates, "truncated"))
        attr(candidates, "truncated") <- NULL
        if (nrow(candidates) == 0L) {
            frontier <- character()
            next
        }
        graph_assert_edge_endpoints(store, candidates, graph = graph)
        existing_keys <- graph_edge_keys(edges)
        candidates <- candidates[!graph_edge_keys(candidates) %in% existing_keys, , drop = FALSE]
        candidate_nodes <- sort(unique(c(as.character(candidates$subject), as.character(candidates$object))))
        new_nodes <- setdiff(candidate_nodes, visited)
        remaining_nodes <- limits$max_nodes - length(visited)
        if (length(new_nodes) > remaining_nodes) {
            truncated <- TRUE
            new_nodes <- if (remaining_nodes > 0L) {
                new_nodes[seq_len(remaining_nodes)]
            }
            else {
                character()
            }
        }
        retained_nodes <- c(visited, new_nodes)
        retained_edges <- candidates[candidates$subject %in% retained_nodes & candidates$object %in% retained_nodes, , drop = FALSE]
        if (nrow(retained_edges) < nrow(candidates)) {
            truncated <- TRUE
        }
        edges <- dplyr::bind_rows(edges, retained_edges)
        edges <- graph_order_edges(edges)
        visited <- sort(unique(retained_nodes))
        frontier <- sort(unique(new_nodes))
    }
    nodes <- graph_collect_nodes(store, visited, graph = graph)
    graph_assert_collected_nodes(nodes, visited, field = "graph", rule = "graph_endpoint_exists")
    list(nodes = nodes, edges = graph_order_edges(edges), truncated = truncated)
}

graph_filter_frontier_edges.body:
{
    incident <- if (identical(direction, "out")) {
        rows$subject %in% frontier
    }
    else if (identical(direction, "in")) {
        rows$object %in% frontier
    }
    else {
        rows$subject %in% frontier | rows$object %in% frontier
    }
    if (!is.null(predicate)) {
        incident <- incident & !is.na(rows$predicate) & rows$predicate == predicate
    }
    incident[is.na(incident)] <- FALSE
    rows <- graph_order_edges(rows[incident, , drop = FALSE])
    truncated <- nrow(rows) > limit
    if (truncated) {
        rows <- rows[seq_len(limit), , drop = FALSE]
    }
    rownames(rows) <- NULL
    attr(rows, "truncated") <- truncated
    rows
}

graph_label_expression.body:
{
