        paste0("NULLIF(TRIM(CAST(", graph_slot_identifier(connection, contract, slot_name), " AS VARCHAR)), '')")
    }, character(1))
    paste0("COALESCE(", paste(columns, collapse = ", "), ")")
}

graph_label_slots.body:
{
