    candidates <- candidates[!is.na(candidates) & candidates %in% names(contract$slots)]
    candidates <- Filter(function(slot_name) {
        slot <- contract$slots[[slot_name]]
        !scalar_logical(slot$multivalued) && !scalar_logical(slot$sensitive) && !scalar_logical(slot$object_reference) && !is.na(scalar_character(slot$view_column))
    }, candidates)
}

