graph_projection_classes.body:
{
    manifest <- schema$manifest
    declared <- manifest$graph_projections[[projection]]
    classes <- manifest$classes
    if (identical(projection, "node_classes")) {
        declared_names <- empty_character(declared)
        if (length(declared_names) == 0L) {
            declared_names <- names(Filter(function(.x) {
                scalar_character(.x$role) %in% c("node", "statement", "evidence", "source")
            }, classes))
        }
        mention_classes <- names(Filter(function(.x) identical(scalar_character(.x$role), "mention"), classes))
        return(sort(unique(c(declared_names, mention_classes))))
    }
    empty_character(declared)
}

graph_projection_contract.body:
{
