    }
    contract
}

graph_provenance_edges_view_sql.body:
{
    manifest <- schema$manifest
    projection <- manifest$graph_projections$provenance_edges
    narrative <- empty_character(projection$narrative_statement_classes)
    if (length(narrative) == 0L) {
        narrative <- names(Filter(function(.x) identical(scalar_character(.x$statement_shape), "narrative"), manifest$classes))
    }
    parts <- list()
    narrative_slots <- empty_character(projection$narrative_slots)
    if (length(narrative_slots) == 0L) {
        narrative_slots <- c("about", "primary_subject")
    }
    if ("about" %in% narrative_slots) {
        relations <- Filter(function(.x) {
            scalar_character(.x$owner_class) %in% narrative && identical(scalar_character(.x$slot), "about") && identical(scalar_character(.x$kind), "object")
        }, manifest$relations)
        parts <- c(parts, lapply(relations, function(relation) {
            graph_relation_provenance_select_sql(connection, relation)
        }))
    }
    if ("primary_subject" %in% narrative_slots) {
        parts <- c(parts, lapply(narrative, function(record_class) {
            contract <- graph_projection_contract(schema, record_class, "provenance edges")
            graph_scalar_provenance_select_sql(connection, contract, subject_slot = "id", object_slot = "primary_subject", predicate = graph_slot_predicate(contract, "primary_subject"), edge_kind = "primary_subject")
        }))
    }
    if (scalar_logical(projection$statement_to_evidence, TRUE)) {
        evidence <- graph_role_class_names(schema, "evidence")
        parts <- c(parts, lapply(evidence, function(record_class) {
            contract <- manifest$classes[[record_class]]
            graph_scalar_provenance_select_sql(connection, contract, subject_slot = "statement_id", object_slot = "id", predicate = graft_predicate_uri("evidence"), edge_kind = "statement_evidence", edge_owner_slot = "id")
        }))
    }
    if (scalar_logical(projection$evidence_to_source, TRUE)) {
        evidence <- graph_role_class_names(schema, "evidence")
        parts <- c(parts, lapply(evidence, function(record_class) {
            contract <- manifest$classes[[record_class]]
            graph_scalar_provenance_select_sql(connection, contract, subject_slot = "id", object_slot = "source_id", predicate = graph_slot_predicate(contract, "source_id"), edge_kind = "evidence_source")
        }))
    }
    if (scalar_logical(projection$supersession, TRUE)) {
        statements <- graph_role_class_names(schema, "statement")
        parts <- c(parts, lapply(statements, function(record_class) {
            contract <- manifest$classes[[record_class]]
            graph_scalar_provenance_select_sql(connection, contract, subject_slot = "id", object_slot = "superseded_by", predicate = graph_slot_predicate(contract, "superseded_by"), edge_kind = "superseded_by")
        }))
    }
    if (scalar_logical(projection$mention_resolution, TRUE)) {
        mentions <- graph_role_class_names(schema, "mention")
        parts <- c(parts, lapply(mentions, function(record_class) {
            contract <- manifest$classes[[record_class]]
            graph_scalar_provenance_select_sql(connection, contract, subject_slot = "id", object_slot = "entity_id", predicate = graph_slot_predicate(contract, "entity_id"), edge_kind = "mention_entity")
        }))
    }
    if (scalar_logical(projection$semantic_derivation, TRUE)) {
        semantic <- names(Filter(function(.x) identical(scalar_character(.x$statement_shape), "semantic"), manifest$classes))
        parts <- c(parts, lapply(semantic, function(record_class) {
            contract <- manifest$classes[[record_class]]
            graph_scalar_provenance_select_sql(connection, contract, subject_slot = "id", object_slot = "derived_from_statement", predicate = graph_slot_predicate(contract, "derived_from_statement"), edge_kind = "semantic_derivation")
        }))
    }
    graph_union_sql(parts, graph_empty_provenance_edges_sql())
}

graph_relation_provenance_select_sql.body:
