graph_slot_identifier.body:
{
    slot <- contract$slots[[slot_name]]
    column <- scalar_character(slot$view_column)
    if (is.null(slot) || is.na(column)) {
        abort_schema_error(paste0("Graph projection requires scalar slot `", slot_name, "` on class `", scalar_character(contract$name), "`."), record_class = scalar_character(contract$name), slot = slot_name)
    }
    quote_identifier(connection, column)
}

