historical_schema.body:
{
    if (exists(build_digest, envir = cache, inherits = FALSE)) {
        return(get(build_digest, envir = cache, inherits = FALSE))
    }
    version <- read_schema_version(store$connection, build_digest)
    schema <- historical_schema_version(version, build_digest)
    assign(build_digest, schema, envir = cache)
    schema
}

historical_schema_version.body:
{
    if (nrow(version) != 1L) {
        abort_backend_error("A revision does not have exactly one registered historical manifest.", operation = "record_history", build_digest = build_digest, schema_version_count = nrow(version))
    }
    schema <- compiled_schema_from_json(version$manifest_json[[1L]])
    validate_manifest_integrity(schema)
    fingerprints <- schema$manifest$fingerprints
    if (!identical(scalar_character(version$structural_digest), scalar_character(fingerprints$structural_digest)) || !identical(scalar_character(version$source_digest), scalar_character(fingerprints$source_digest)) || !identical(scalar_character(version$build_digest), scalar_character(fingerprints$build_digest))) {
        abort_backend_error("A historical schema registry row does not match its manifest.", operation = "record_history", build_digest = build_digest)
    }
    schema
}

historical_schemas.body:
{
    build_digests <- unique(as.character(build_digests))
    if (length(build_digests) == 0L) {
        return(list())
    }
    versions <- with_duckdb_error("record_history_schemas", DBI::dbGetQuery(store$connection, paste0("SELECT structural_digest, source_digest, build_digest, ", "manifest_json FROM ", quote_identifier(store$connection, "_graft_schema_versions"), " WHERE build_digest IN (", paste(rep("?", length(build_digests)), collapse = ", "), ") ORDER BY build_digest"), params = as.list(build_digests)))
    schemas <- list()
    for (build_digest in build_digests) {
        version <- versions[versions$build_digest == build_digest, , drop = FALSE]
        schemas[[build_digest]] <- historical_schema_version(version, build_digest)
    }
    schemas
}

history_sql_filters.body:
{
    clauses <- character()
    params <- list()
    for (name in names(values)) {
        value <- values[[name]]
        if (is.null(value)) {
            next
        }
        column <- columns[[name]]
        operator <- if (name %in% names(operators)) 
            operators[[name]]
        else "="
        stopifnot(operator %in% c("=", ">=", "<="))
        if (grepl("\\.", column, fixed = FALSE)) {
            parts <- strsplit(column, ".", fixed = TRUE)[[1L]]
            column <- paste(vapply(parts, function(.x) quote_identifier(store$connection, .x), character(1)), collapse = ".")
        }
        else {
            column <- quote_identifier(store$connection, column)
        }
        clauses <- c(clauses, paste0(" AND ", column, " ", operator, " ?"))
        params <- c(params, list(value))
    }
    list(sql = paste0(clauses, collapse = ""), params = params)
}

hydrate_history_rows.body:
{
    truncated <- nrow(rows) > limit
    if (truncated) {
        rows <- rows[seq_len(limit), , drop = FALSE]
    }
    schemas <- historical_schemas(store, unique(rows$schema_build_digest))
    records <- vector("list", nrow(rows))
    changed_fields <- vector("list", nrow(rows))
    for (index in seq_len(nrow(rows))) {
        schema <- schemas[[rows$schema_build_digest[[index]]]]
        contract <- schema$manifest$classes[[rows$class[[index]]]]
        if (is.null(contract)) {
            abort_backend_error("A revision class is absent from its historical manifest.", operation = "record_history", record_id = rows$record_id[[index]], record_class = rows$class[[index]], build_digest = rows$schema_build_digest[[index]])
        }
        records[[index]] <- validated_public_revision_record(rows$payload_json[[index]], rows$content_digest[[index]], contract, record_id = rows$record_id[[index]], revision_id = rows$revision_id[[index]])
        changed_fields[[index]] <- public_changed_fields(rows$changed_fields_json[[index]], contract)
    }
    rows$payload_json <- NULL
    rows$content_digest <- NULL
    rows$changed_fields_json <- NULL
    rows$changed_fields <- I(changed_fields)
    rows$record <- I(records)
    finalize_history_rows(rows, store, limit, truncated)
}

initialize_store_backend.body:
{
    validate_store_backend(store)
    validate_manifest_integrity(store$schema)
    if (duckdb_table_exists(store$connection, "_graft_store")) {
        if (isTRUE(store$read_only)) {
            verify_initialized_store(store)
            verify_projection_views(store$connection, store$schema)
        }
        else {
            with_duckdb_error("initialize_existing_store", DBI::dbWithTransaction(store$connection, {
                verify_initialized_store(store)
                rebuild_projection_views(store$connection, store$schema)
            }))
        }
        mark_store_verified(store)
        return(invisible(store))
    }
    if (isTRUE(store$read_only)) {
        abort_backend_error("A read-only store cannot initialize a blank database.", operation = "initialize", store_path = store$path)
    }
    validate_store_writable(store, "initialize")
    existing <- duckdb_table_names(store$connection)
    if (length(existing) > 0L) {
        abort_backend_error(paste0("Cannot initialize a non-empty database without `_graft_store`; ", "found: ", paste(sort(existing), collapse = ", "), "."), operation = "initialize", existing_tables = existing, store_path = store$path)
    }
    with_duckdb_error("initialize", DBI::dbWithTransaction(store$connection, {
        create_metadata_tables(store$connection)
        insert_store_metadata(store)
        register_initial_schema(store)
        rebuild_projection_views(store$connection, store$schema)
    }))
    mark_store_verified(store)
    invisible(store)
}

install_compiled_manifest.body:
{
    if (dir.exists(output)) {
        abort_schema_error("The compiled manifest output path is an existing directory.", output_path = output, call = call)
    }
    if (!file.exists(output)) {
        if (!file.rename(stage, output)) {
            abort_schema_error("Could not install the validated compiled manifest.", output_path = output, call = call)
        }
        return(invisible(output))
    }
    backup <- tempfile(pattern = paste0(".", basename(output), "-backup-"), tmpdir = dirname(output))
    if (!file.rename(output, backup)) {
        abort_schema_error("Could not stage the existing compiled manifest for replacement.", output_path = output, call = call)
    }
    installed <- file.rename(stage, output)
    if (!installed) {
        restored <- file.rename(backup, output)
        abort_schema_error(paste0("Could not install the validated compiled manifest", if (restored) 
            "."
        else " or restore the previous output."), output_path = output, call = call)
    }
    unlink(backup, force = TRUE)
    invisible(output)
}

integrity_issue_row.body:
{
