is_canonical_snapshot_timestamp.body:
{
    if (!is.character(value) || length(value) != 1L || is.na(value) || !grepl(paste0("^[0-9]{4}-[0-9]{2}-[0-9]{2}T", "[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{6}Z$"), value)) {
        return(FALSE)
    }
    whole_seconds <- substr(value, 1L, 19L)
    parsed <- suppressWarnings(as.POSIXct(whole_seconds, format = "%Y-%m-%dT%H:%M:%S", tz = "UTC"))
    !is.na(parsed) && identical(format(parsed, "%Y-%m-%dT%H:%M:%S", tz = "UTC"), whole_seconds)
}

is_data_dict_document.body:
{
    if (!data_dict_is_scalar_text(path) || !file.exists(path) || dir.exists(path)) {
        return(FALSE)
    }
    extension <- data_dict_file_extension(path)
    if (!extension %in% c("json", "yaml", "yml")) {
        return(FALSE)
    }
    if (extension %in% c("yaml", "yml") && tolower(basename(path)) %in% c("data-dict.yaml", "data-dict.yml")) {
        return(TRUE)
    }
    document <- tryCatch(if (identical(extension, "json")) {
        jsonlite::fromJSON(path, simplifyVector = FALSE)
    }
    else {
        yaml::read_yaml(path, eval.expr = FALSE)
    }, error = function(error) NULL)
    data_dict_has_resolved_header(document)
}

is_graft_snapshot_backend.body:
{
    if (!is_store_backend(x)) {
        return(FALSE)
    }
    fields <- c("schema", "connection", "owns_connection", "read_only", "path", "closed", "capabilities", "okf_mode", "okf_path", "okf_expected", "verification", "snapshot", "source_backend")
    if (!identical(sort(ls(x, all.names = TRUE)), sort(fields))) {
        return(FALSE)
    }
    if (!is_store_backend(x$source_backend) || !identical(x$connection, x$source_backend$connection) || !identical(x$read_only, TRUE) || !identical(x$owns_connection, FALSE) || !is.null(snapshot_validation_problem(x$snapshot))) {
        return(FALSE)
    }
    identical(scalar_character(x$schema$manifest$fingerprints$build_digest), x$snapshot$schema_build_digest)
}

is_missing_value.body:
{
    if (is.null(value) || length(value) == 0L || all(is.na(value))) {
        return(TRUE)
    }
    if (!multivalued && is.character(value) && !any(nzchar(trimws(value)))) {
        return(TRUE)
    }
