}

linkml_reference_is_valid.body:
{
    range <- match.arg(range)
    if (!is.character(x)) {
        return(rep(FALSE, length(x)))
    }
    patterns <- linkml_reference_patterns()
    valid <- !is.na(x) & nzchar(x) & grepl(patterns$uri, x, perl = TRUE)
    if (identical(range, "uriorcurie")) {
        valid <- valid | (!is.na(x) & nzchar(x) & grepl(patterns$curie, x, perl = TRUE))
    }
    valid
}

load_schema_manifest.body:
{
    if (!is.character(path) || length(path) != 1L || is.na(path) || !nzchar(path)) {
        abort_schema_error("`path` must be one non-empty manifest path.", argument = "path")
    }
    if (!file.exists(path)) {
        abort_schema_error(paste0("Schema manifest does not exist: `", path, "`."), manifest_path = path)
    }
    normalized_path <- normalizePath(path, winslash = "/", mustWork = TRUE)
    snapshot <- schema_manifest_source_snapshot(normalized_path)
    manifest <- tryCatch(jsonlite::fromJSON(snapshot$text, simplifyVector = FALSE), error = function(error) {
        abort_schema_error(paste0("Could not parse schema manifest `", normalized_path, "`: ", conditionMessage(error)), manifest_path = normalized_path, parent = error)
    })
    validate_data_dict_json_numbers(manifest, snapshot$text, normalized_path, subject = "schema manifest")
    validate_manifest_header(manifest, normalized_path)
    new_compiled_schema(manifest, normalized_path)
}

locate_data_dict_cli.body:
