    content$fingerprints$build_digest <- NULL
    graft_sha256(canonical_json(content))
}

manifest_class_annotation_problem.body:
{
    slots <- class$slots
    label_slot <- class$label_slot
    if (!is.null(label_slot)) {
        label <- slots[[label_slot]]
        if (is.null(label) || label$multivalued || label$object_reference || !identical(label$duckdb_type, "VARCHAR") || label$sensitive) {
            return(manifest_contract_problem("A label slot must resolve to a public scalar text slot.", paste0("classes.", class_name, ".label_slot"), "class_annotation_contract"))
        }
    }
    annotations <- list(search_slots = unlist(class$search_slots, use.names = FALSE), origin_key_slots = unlist(class$origin_key_slots, use.names = FALSE), qualifier_slots = unlist(class$qualifier_slots, use.names = FALSE))
    for (field in names(annotations)) {
        values <- annotations[[field]]
        if (anyDuplicated(values) || length(setdiff(values, names(slots))) > 0L) {
            return(manifest_contract_problem("Class slot annotations must name unique slots on that class.", paste("classes", class_name, field, sep = "."), "class_annotation_contract"))
        }
    }
    if (identical(class$id_policy, "deterministic") && length(annotations$origin_key_slots) == 0L) {
        return(manifest_contract_problem("A deterministic identity policy requires at least one origin-key slot.", paste0("classes.", class_name, ".origin_key_slots"), "class_identifier_contract"))
    }
    for (slot_name in annotations$search_slots) {
        slot <- slots[[slot_name]]
        if (slot$multivalued || slot$object_reference || !identical(slot$duckdb_type, "VARCHAR") || slot$sensitive) {
            return(manifest_contract_problem("Search slots must be public scalar text slots.", paste0("classes.", class_name, ".search_slots"), "class_annotation_contract"))
        }
    }
    core_statement_fields <- c("id", "created_at", "updated_at", "polarity", "confidence", "status", "valid_from", "valid_to", "asserted_at", "superseded_by")
    if (length(annotations$qualifier_slots) > 0L && (!identical(class$role, "statement") || length(intersect(annotations$qualifier_slots, core_statement_fields)) > 0L)) {
        return(manifest_contract_problem("Qualifier slots must be non-core fields on a statement class.", paste0("classes.", class_name, ".qualifier_slots"), "class_annotation_contract"))
    }
    NULL
}

manifest_class_hierarchy_problem.body:
{
    core_parent <- manifest_core_class_parents()
    observed_parent <- character()
    for (class_name in names(classes)) {
        if (identical(class_name, graft_definition_class_name)) {
            next
        }
        class <- classes[[class_name]]
        ancestors <- unlist(class$ancestors, use.names = FALSE)
        if (data_dict) {
            if (!is.null(class$is_a) || length(ancestors) > 0L) {
                return(manifest_contract_problem("Data-dict classes cannot declare an inheritance hierarchy.", paste0("classes.", class_name, ".ancestors"), "class_hierarchy_contract"))
            }
            next
        }
        if (length(ancestors) == 0L || !identical(ancestors[[1L]], class_name) || anyDuplicated(ancestors)) {
            return(manifest_contract_problem("A LinkML class must declare a unique self-first ancestor path.", paste0("classes.", class_name, ".ancestors"), "class_hierarchy_contract"))
        }
        direct_parent <- if (length(ancestors) > 1L) {
            ancestors[[2L]]
        }
        else {
            NULL
        }
        if (!identical(class$is_a, direct_parent)) {
            return(manifest_contract_problem("A class parent does not match its ancestor path.", paste0("classes.", class_name, ".is_a"), "class_hierarchy_contract"))
        }
        if (length(ancestors) > 2L) {
            unknown_seen <- FALSE
            for (ancestor in ancestors[-1L]) {
                if (ancestor %in% names(classes) && unknown_seen) {
                  return(manifest_contract_problem(paste("An undeclared ancestor cannot bridge to a declared class in", "an ancestor path."), paste0("classes.", class_name, ".ancestors"), "class_hierarchy_contract"))
                }
                if (!ancestor %in% c(names(classes), names(core_parent))) {
                  unknown_seen <- TRUE
                }
            }
        }
        if (length(ancestors) > 1L) {
            for (index in seq_len(length(ancestors) - 1L)) {
                child <- ancestors[[index]]
                parent <- ancestors[[index + 1L]]
                if (child %in% names(classes) && !identical(classes[[child]]$is_a, parent)) {
                  return(manifest_contract_problem("A declared class has inconsistent ancestor paths.", paste0("classes.", class_name, ".ancestors"), "class_hierarchy_contract"))
                }
                if (child %in% names(core_parent) && !identical(unname(core_parent[[child]]), parent)) {
                  return(manifest_contract_problem("A Graft core class has an invalid parent in an ancestor path.", paste0("classes.", class_name, ".ancestors"), "class_hierarchy_contract"))
                }
                if (child %in% names(observed_parent) && !identical(unname(observed_parent[[child]]), parent)) {
                  return(manifest_contract_problem("Ancestor paths disagree about a class parent.", paste0("classes.", class_name, ".ancestors"), "class_hierarchy_contract"))
                }
                observed_parent[[child]] <- parent
            }
        }
        terminal <- ancestors[[length(ancestors)]]
        terminal_parent <- if (terminal %in% names(classes)) {
            classes[[terminal]]$is_a
        }
        else if (terminal %in% names(core_parent)) {
            unname(core_parent[[terminal]])
        }
        else {
            NULL
        }
        if (!is.null(terminal_parent) && nzchar(terminal_parent)) {
            return(manifest_contract_problem("A class ancestor path ends before its declared root.", paste0("classes.", class_name, ".ancestors"), "class_hierarchy_contract"))
        }
    }
    NULL
}

manifest_class_role_problem.body:
{
    ancestors <- unlist(class$ancestors, use.names = FALSE)
    uses_graft_core <- "GraftRecord" %in% ancestors
    core_roles <- c(GraftNarrativeStatement = "statement", GraftSemanticStatement = "statement", GraftStatement = "statement", GraftEdge = "edge", GraftEvidence = "evidence", GraftSource = "source", GraftMention = "mention", GraftNode = "node", GraftMetadata = "metadata", GraftRecord = "metadata")
    role_ancestors <- ancestors[ancestors %in% names(core_roles)]
    expected_role <- if (data_dict) {
        "node"
    }
    else if (length(role_ancestors) > 0L) {
        unname(core_roles[[role_ancestors[[1L]]]])
    }
    else {
        class$role
    }
    expected_shape <- if ("GraftNarrativeStatement" %in% ancestors) {
        "narrative"
    }
    else if ("GraftSemanticStatement" %in% ancestors) {
        "semantic"
    }
    else {
        NULL
    }
    if (!identical(class$role, expected_role) || !identical(class$statement_shape, expected_shape)) {
        return(manifest_contract_problem("A class role or statement shape does not match its inheritance.", paste0("classes.", class_name), "class_role_contract"))
    }
    if (!data_dict && !uses_graft_core && class$role %in% c("edge", "statement", "evidence", "mention")) {
        return(manifest_contract_problem(paste("Edge, statement, evidence, and mention roles require Graft core", "inheritance."), paste0("classes.", class_name, ".role"), "class_role_contract"))
    }
    if (!is.null(class$fixed_predicate) && !identical(expected_role, "edge")) {
        return(manifest_contract_problem("Only edge classes may declare a fixed predicate.", paste0("classes.", class_name, ".fixed_predicate"), "class_role_contract"))
    }
    required_slots <- switch(expected_role, edge = c("subject", "predicate", "object"), statement = c("polarity", "confidence", "status", "valid_from", "valid_to", "asserted_at", "superseded_by"), evidence = c("statement_id", "source_id", "support_type", "locator_type", "locator_value", "page_start", "page_end", "excerpt", "source_content_hash", "extraction_method", "extraction_version"), mention = c("source_id", "surface_form", "locator_type", "locator_value", "entity_id"), character())
    if (identical(expected_shape, "narrative")) {
        required_slots <- c(required_slots, "statement_text", "primary_subject", "about")
    }
    else if (identical(expected_shape, "semantic")) {
        required_slots <- c(required_slots, "subject", "predicate", "object_entity", "object_value", "object_datatype", "derived_from_statement")
    }
    if (length(setdiff(required_slots, names(class$slots))) > 0L) {
        return(manifest_contract_problem("A class is missing slots required by its role or statement shape.", paste0("classes.", class_name, ".slots"), "class_role_contract"))
    }
    if (!data_dict) {
        core_problem <- manifest_core_class_slot_problem(class, class_name)
        if (!is.null(core_problem)) {
            return(core_problem)
        }
    }
    NULL
}

manifest_class_shape_problem.body:
{
    required <- c("name", "role", "view", "id_policy", "id_format", "type_uri", "slots", "relations")
    allowed <- c(required, "is_a", "ancestors", "statement_shape", "label_slot", "search_slots", "origin_key_slots", "qualifier_slots", "fixed_predicate")
    problem <- manifest_object_fields_problem(class, field, required, allowed)
    if (!is.null(problem)) {
        return(problem)
    }
    string_fields <- c("name", "view")
    if (!all(vapply(class[string_fields], manifest_json_nonblank_string, logical(1)))) {
        return(manifest_contract_problem("Manifest class name and view must be nonblank strings.", field))
    }
    if (!manifest_json_string(class$role) || !class$role %in% c("node", "edge", "statement", "evidence", "source", "mention", "metadata") || !manifest_json_string(class$id_policy) || !class$id_policy %in% c("require", "mint", "resolve_exact", "deterministic") || !manifest_json_string(class$id_format) || !class$id_format %in% c("graft", "linkml")) {
        return(manifest_contract_problem("Manifest class role or identity policy is invalid.", field))
    }
    nullable_strings <- intersect(c("is_a", "label_slot", "fixed_predicate"), names(class))
    if (!all(vapply(class[nullable_strings], manifest_json_nullable_nonblank_string, logical(1)))) {
        return(manifest_contract_problem("Manifest class metadata must use strings or null.", field))
    }
    if (!manifest_json_linkml_reference(class$type_uri, "uri")) {
        return(manifest_contract_problem("Manifest class type URI must be a valid complete URI.", paste0(field, ".type_uri"), "manifest_reference_contract"))
    }
    if (!manifest_json_nullable_linkml_reference(class$fixed_predicate)) {
        return(manifest_contract_problem("Manifest fixed predicate must be a valid URI or CURIE.", paste0(field, ".fixed_predicate"), "manifest_reference_contract"))
    }
    if ("statement_shape" %in% names(class) && (!manifest_json_nullable_string(class$statement_shape) || (!is.null(class$statement_shape) && !class$statement_shape %in% c("narrative", "semantic")))) {
        return(manifest_contract_problem("Manifest class statement shape is invalid.", paste0(field, ".statement_shape")))
    }
    array_fields <- intersect(c("ancestors", "search_slots", "origin_key_slots", "qualifier_slots", "relations"), names(class))
    if (!all(vapply(class[array_fields], manifest_json_nonblank_string_array, logical(1)))) {
        return(manifest_contract_problem("Manifest class string collections must be JSON arrays.", field))
    }
    if (!manifest_json_object(class$slots)) {
        return(manifest_contract_problem("Manifest class slots must be a JSON object.", paste0(field, ".slots")))
    }
    if (length(class$slots) > 0L && !all(vapply(names(class$slots), manifest_json_nonblank_string, logical(1)))) {
        return(manifest_contract_problem("Manifest class slot keys must be nonblank strings.", paste0(field, ".slots")))
    }
    for (slot_name in names(class$slots)) {
        problem <- manifest_slot_shape_problem(class$slots[[slot_name]], paste(field, "slots", slot_name, sep = "."))
        if (!is.null(problem)) {
            return(problem)
        }
    }
    NULL
}

