    core_slots <- manifest_core_slots_by_class()
    inherited <- intersect(ancestors, names(core_slots))
    if (!"GraftRecord" %in% inherited) {
        return(NULL)
    }
    slot_names <- unique(unlist(core_slots[inherited], use.names = FALSE))
    missing <- setdiff(slot_names, names(class$slots))
    if (length(missing) > 0L) {
        return(manifest_contract_problem("A Graft core-derived class is missing inherited core slots.", paste0("classes.", class_name, ".slots"), "core_slot_contract"))
    }
    contracts <- manifest_core_slot_contracts()
    exact_fields <- c("range", "duckdb_type", "multivalued", "ordered", "identifier", "object_reference", "enum")
    for (slot_name in slot_names) {
        observed <- class$slots[[slot_name]]
        expected <- contracts[[slot_name]]
        exact <- all(vapply(exact_fields, function(field) identical(observed[[field]], expected[[field]]), logical(1)))
        required_is_safe <- !expected$required || observed$required
        minimum_is_safe <- is.null(expected$minimum_value) || (!is.null(observed$minimum_value) && observed$minimum_value >= expected$minimum_value)
        maximum_is_safe <- is.null(expected$maximum_value) || (!is.null(observed$maximum_value) && observed$maximum_value <= expected$maximum_value)
        if (!exact || !required_is_safe || !minimum_is_safe || !maximum_is_safe || !is.null(observed$datetime_format) || (identical(slot_name, "id") && (observed$sensitive || !is.null(observed$external_identifier)))) {
            return(manifest_contract_problem("A class-local slot weakens or changes its Graft core contract.", paste("classes", class_name, "slots", slot_name, sep = "."), "core_slot_contract"))
        }
    }
    NULL
}

