manifest_semantic_contract_problem.body:
{
    hierarchy_problem <- manifest_class_hierarchy_problem(manifest$classes, data_dict)
    if (!is.null(hierarchy_problem)) {
        return(hierarchy_problem)
    }
    class_names <- names(manifest$classes)
    user_classes <- manifest$classes[setdiff(class_names, graft_definition_class_name)]
    ancestors <- unlist(lapply(user_classes, function(class) class$ancestors), use.names = FALSE)
    known_class_ranges <- unique(c(class_names, ancestors, if (data_dict) character() else names(manifest_core_class_parents())))
    enum_names <- names(manifest$enums)
    global_slot_names <- names(manifest$slots)
    uses_graft_core <- !data_dict && "GraftRecord" %in% ancestors
    if (uses_graft_core) {
        core_global_problem <- manifest_core_global_slot_problem(manifest$slots)
        if (!is.null(core_global_problem)) {
            return(core_global_problem)
        }
    }
    for (enum_name in enum_names) {
        enum <- manifest$enums[[enum_name]]
        if (!identical(enum$name, enum_name)) {
            return(manifest_contract_problem("An enum key must match its declared name.", paste0("enums.", enum_name, ".name"), "enum_identity_contract"))
        }
        values <- vapply(enum$permissible_values, function(value) value$value, character(1))
        if (!all(nzchar(trimws(values))) || anyDuplicated(values)) {
            return(manifest_contract_problem("Enum values must be unique strings that are non-empty after trimming.", paste0("enums.", enum_name, ".permissible_values"), "enum_value_contract"))
        }
    }
    for (class_name in class_names) {
        class <- manifest$classes[[class_name]]
        if (identical(class_name, graft_definition_class_name)) {
            contract_matches <- identical(canonical_json(class), canonical_json(graft_definition_class_contract()))
            if (!contract_matches) {
                return(manifest_contract_problem("The GraftDefinition system class does not match its fixed contract.", paste0("classes.", class_name), "system_class_contract"))
            }
            next
        }
        if (!identical(class$name, class_name)) {
            return(manifest_contract_problem("A class key must match its declared name.", paste0("classes.", class_name, ".name"), "class_identity_contract"))
        }
        role_problem <- manifest_class_role_problem(class, class_name, data_dict)
        if (!is.null(role_problem)) {
            return(role_problem)
        }
        annotation_problem <- manifest_class_annotation_problem(class, class_name)
        if (!is.null(annotation_problem)) {
            return(annotation_problem)
        }
        slots <- class$slots
        identifiers <- names(Filter(function(slot) slot$identifier, slots))
        valid_identifier <- length(identifiers) == 1L && identical(identifiers, "id") && slots$id$required && !slots$id$multivalued && !slots$id$object_reference && identical(slots$id$duckdb_type, "VARCHAR")
        if (!valid_identifier) {
            return(manifest_contract_problem("Each class must have one required scalar string identifier named id.", paste0("classes.", class_name, ".slots"), "class_identifier_contract"))
        }
        for (slot_name in names(slots)) {
            global_name <- if (data_dict) {
                paste(class_name, slot_name, sep = ".")
            }
            else {
                slot_name
            }
            has_global_slot <- global_name %in% global_slot_names
            generated_linkml_slot <- !data_dict && slot_name %in% c("id", "created_at", "updated_at")
            if (!has_global_slot && !generated_linkml_slot) {
                return(manifest_contract_problem("A class-local slot has no corresponding global slot contract.", paste("classes", class_name, "slots", slot_name, sep = "."), "class_global_slot_contract"))
            }
            if (has_global_slot && data_dict) {
                contract_fields <- c("name", "range", "duckdb_type", "required", "multivalued", "identifier", "object_reference", "enum", "meaning", "pattern", "datetime_format", "minimum_value", "maximum_value", "external_identifier", "search_weight", "sensitive")
                local_contract <- lapply(contract_fields, function(field) slots[[slot_name]][[field]])
                names(local_contract) <- contract_fields
                global_contract <- lapply(contract_fields, function(field) manifest$slots[[global_name]][[field]])
                names(global_contract) <- contract_fields
                if (!identical(canonical_schema_value(local_contract), canonical_schema_value(global_contract))) {
                  return(manifest_contract_problem("A class-local slot differs from its global slot contract.", paste("classes", class_name, "slots", slot_name, sep = "."), "class_global_slot_contract"))
                }
            }
            else if (has_global_slot && !identical(slots[[slot_name]]$name, manifest$slots[[global_name]]$name)) {
                return(manifest_contract_problem("A class-local slot has a different global slot identity.", paste("classes", class_name, "slots", slot_name, sep = "."), "class_global_slot_contract"))
            }
            problem <- manifest_slot_semantic_problem(slots[[slot_name]], paste("classes", class_name, "slots", slot_name, sep = "."), known_class_ranges, enum_names)
            if (!is.null(problem)) {
                return(problem)
            }
        }
    }
    global_class_ranges <- known_class_ranges
    if (!data_dict) {
        global_object_ranges <- vapply(Filter(function(slot) slot$object_reference, manifest$slots), function(slot) slot$range, character(1))
        global_class_ranges <- unique(c(global_class_ranges, global_object_ranges))
    }
    for (slot_name in global_slot_names) {
        problem <- manifest_slot_semantic_problem(manifest$slots[[slot_name]], paste("slots", slot_name, sep = "."), global_class_ranges, enum_names)
        if (!is.null(problem)) {
            return(problem)
        }
    }
    NULL
}

manifest_shape_problem.body:
{
    problem <- function(message, field, rule = "manifest_shape_contract") {
        list(message = message, field = field, rule = rule)
    }
    if (!manifest_json_object(manifest)) {
        return(problem("The schema manifest must be a JSON object.", "$"))
    }
    object_fields <- c("schema", "classes", "slots", "enums", "graph_projections", "identifier_normalization_versions", "compiler", "fingerprints")
    for (field in object_fields) {
        if (!manifest_json_object(manifest[[field]])) {
            rule <- switch(field, schema = "schema_source_contract", compiler = "compiler_contract", fingerprints = "manifest_fingerprints", "manifest_shape_contract")
            return(problem(paste0("Manifest field `", field, "` must be a JSON object."), field, rule))
        }
    }
    for (field in c("relations", "validation_invariants")) {
        if (!manifest_json_array(manifest[[field]])) {
            return(problem(paste0("Manifest field `", field, "` must be a JSON array."), field))
        }
    }
    if ("dictionary" %in% names(manifest) && !manifest_json_object(manifest$dictionary)) {
        return(problem("Manifest field `dictionary` must be a JSON object when present.", "dictionary", "dictionary_extension_contract"))
    }
    has_dictionary <- "dictionary" %in% names(manifest)
    if (!has_dictionary && manifest_json_object(manifest$compiler) && ("provider" %in% names(manifest$compiler) || identical(manifest$compiler$name, "graft-data-dict-adapter"))) {
        return(problem("A compiler provider requires a matching dictionary extension.", "dictionary", "dictionary_provider_contract"))
    }
    for (field in c("classes", "slots", "enums")) {
        values <- manifest[[field]]
        if (length(values) > 0L && !all(vapply(names(values), manifest_json_nonblank_string, logical(1)))) {
            return(problem(paste0("Every `", field, "` key must be a nonblank string."), field))
        }
        invalid <- which(!vapply(values, manifest_json_object, logical(1)))
        if (length(invalid) > 0L) {
            key <- names(values)[[invalid[[1L]]]]
            return(problem(paste0("Every `", field, "` value must be a JSON object."), paste(field, key, sep = ".")))
        }
    }
    for (class_name in names(manifest$classes)) {
        class_problem <- manifest_class_shape_problem(manifest$classes[[class_name]], paste("classes", class_name, sep = "."))
        if (!is.null(class_problem)) {
            return(class_problem)
        }
    }
    for (slot_name in names(manifest$slots)) {
        slot_problem <- manifest_slot_shape_problem(manifest$slots[[slot_name]], paste("slots", slot_name, sep = "."))
        if (!is.null(slot_problem)) {
            return(slot_problem)
        }
    }
    for (enum_name in names(manifest$enums)) {
        enum_problem <- manifest_enum_shape_problem(manifest$enums[[enum_name]], paste("enums", enum_name, sep = "."))
        if (!is.null(enum_problem)) {
            return(enum_problem)
        }
    }
    invalid_relations <- which(!vapply(manifest$relations, manifest_json_object, logical(1)))
    if (length(invalid_relations) > 0L) {
        index <- invalid_relations[[1L]]
        return(problem("Every `relations` value must be a JSON object.", paste0("relations[", index, "]")))
    }
    for (index in seq_along(manifest$relations)) {
        relation_problem <- manifest_relation_shape_problem(manifest$relations[[index]], paste0("relations[", index, "]"))
        if (!is.null(relation_problem)) {
            return(relation_problem)
        }
    }
    semantic_problem <- manifest_semantic_contract_problem(manifest, data_dict = has_dictionary)
    if (!is.null(semantic_problem)) {
        return(semantic_problem)
    }
    invalid_invariants <- which(!vapply(manifest$validation_invariants, manifest_json_object, logical(1)))
    if (length(invalid_invariants) > 0L) {
        index <- invalid_invariants[[1L]]
        return(problem("Every `validation_invariants` value must be a JSON object.", paste0("validation_invariants[", index, "]")))
    }
    normalization <- manifest$identifier_normalization_versions
    invalid_normalization <- which(!vapply(normalization, manifest_json_string, logical(1)))
    if (length(invalid_normalization) > 0L) {
        key <- names(normalization)[[invalid_normalization[[1L]]]]
        return(problem("Identifier-normalization versions must be strings.", paste("identifier_normalization_versions", key, sep = ".")))
    }
    expected_graph <- manifest_expected_graph_projections(manifest$classes, manifest$relations)
    if (!identical(canonical_schema_value(manifest$graph_projections), canonical_schema_value(expected_graph))) {
        return(problem("Manifest graph projections do not match classes and relations.", "graph_projections", "graph_projection_contract"))
    }
    expected_normalization <- manifest_expected_normalization_versions(manifest$classes)
    if (!identical(canonical_schema_value(normalization), canonical_schema_value(expected_normalization))) {
        return(problem("Identifier normalization metadata does not match global slots.", "identifier_normalization_versions", "identifier_normalization_contract"))
    }
    if (!has_dictionary && !identical(canonical_schema_value(manifest$validation_invariants), canonical_schema_value(manifest_expected_linkml_invariants(manifest$classes)))) {
        return(problem("Manifest validation invariants do not match class semantics.", "validation_invariants", "validation_invariant_contract"))
    }
    schema <- manifest$schema
    schema_required <- c("id", "name", "version", "source_files")
    schema_allowed <- schema_required
    if (!all(schema_required %in% names(schema)) || length(setdiff(names(schema), schema_allowed)) > 0L || !manifest_json_linkml_reference(schema$id, "uri") || !manifest_json_string(schema$name, nonempty = TRUE) || !manifest_json_nullable_nonblank_string(schema$version) || !manifest_json_array(schema$source_files) || length(schema$source_files) == 0L) {
        return(problem("Manifest source identity metadata is invalid.", "schema", "schema_source_contract"))
    }
    source_required <- c("schema_id", "name", "version", "content_digest", "root")
    source_allowed <- source_required
    for (index in seq_along(schema$source_files)) {
        source_file <- schema$source_files[[index]]
        valid <- manifest_json_object(source_file) && all(source_required %in% names(source_file)) && length(setdiff(names(source_file), source_allowed)) == 0L && manifest_json_nonblank_string(source_file$name) && is_graft_digest(source_file$content_digest) && is.logical(source_file$root) && length(source_file$root) == 1L && !is.na(source_file$root) && manifest_json_nullable_linkml_reference(source_file$schema_id, "uri") && manifest_json_nullable_nonblank_string(source_file$version)
        if (!valid) {
            return(problem("Manifest source-file metadata is invalid.", paste0("schema.source_files[", index, "]"), "schema_source_contract"))
        }
    }
    source_schema_ids <- vapply(schema$source_files, function(source_file) {
        if (is.null(source_file$schema_id)) 
            ""
        else source_file$schema_id
    }, character(1))
    source_schema_ids <- source_schema_ids[nzchar(source_schema_ids)]
    source_names <- vapply(schema$source_files, function(source_file) source_file$name, character(1))
    if (anyDuplicated(source_schema_ids) || anyDuplicated(source_names)) {
        return(problem("Manifest source-file schema IDs and names must each be unique.", "schema.source_files", "schema_source_contract"))
    }
    roots <- which(vapply(schema$source_files, function(source_file) source_file$root, logical(1)))
    if (length(roots) != 1L) {
        return(problem("Manifest source files must declare exactly one root.", "schema.source_files", "schema_source_contract"))
    }
    root <- schema$source_files[[roots[[1L]]]]
    if (!identical(root$schema_id, schema$id) || !identical(root$name, schema$name) || !identical(root$version, schema$version)) {
        return(problem("Manifest root source identity does not match the schema identity.", paste0("schema.source_files[", roots[[1L]], "]"), "schema_source_contract"))
    }
    compiler <- manifest$compiler
    compiler_required <- c("name", "version", "script_digest")
    compiler_allowed <- c(compiler_required, "python_version", "linkml_runtime_version", "provider")
    optional_versions <- intersect(c("python_version", "linkml_runtime_version"), names(compiler))
    valid_optional_versions <- all(vapply(compiler[optional_versions], manifest_json_string, logical(1), nonempty = TRUE))
    if (!all(compiler_required %in% names(compiler)) || length(setdiff(names(compiler), compiler_allowed)) > 0L || !manifest_json_string(compiler$name, nonempty = TRUE) || !manifest_json_string(compiler$version, nonempty = TRUE) || !is_graft_digest(compiler$script_digest) || !valid_optional_versions || ("provider" %in% names(compiler) && !manifest_json_object(compiler$provider))) {
        return(problem("Manifest compiler metadata is invalid.", "compiler", if (has_dictionary) {
            "dictionary_compiler_contract"
        } else {
            "compiler_contract"
        }))
    }
    if (has_dictionary) {
        if (integrity && (!setequal(names(compiler), c("name", "version", "script_digest", "provider")) || !identical(compiler$name, "graft-data-dict-adapter") || !identical(compiler$version, data_dict_adapter_version) || !identical(compiler$script_digest, data_dict_adapter_script_digest()))) {
            return(problem("Manifest compiler metadata does not match the data-dict adapter.", "compiler", "dictionary_compiler_contract"))
        }
    }
    else if ("provider" %in% names(compiler) || identical(compiler$name, "graft-data-dict-adapter")) {
        return(problem("A compiler provider requires a matching dictionary extension.", "dictionary", "dictionary_provider_contract"))
    }
    else if (!identical(compiler$name, graft_linkml_compiler_name) || !identical(compiler$version, graft_linkml_compiler_version) || !identical(compiler$script_digest, graft_linkml_compiler_digest())) {
        return(problem("Manifest compiler metadata does not match the packaged LinkML compiler.", "compiler", "compiler_contract"))
    }
    fingerprints <- manifest$fingerprints
    fingerprint_fields <- c("structural_digest", "source_digest", "build_digest")
    if (!setequal(names(fingerprints), fingerprint_fields) || !all(vapply(fingerprints[fingerprint_fields], is_graft_digest, logical(1)))) {
        return(problem("Manifest fingerprints are invalid.", "fingerprints", "manifest_fingerprints"))
    }
    if (!has_dictionary && !identical(fingerprints$source_digest, graft_linkml_source_digest(schema$source_files))) {
        return(problem("The LinkML source digest does not match the source-file closure.", "fingerprints.source_digest", "source_digest_content_mismatch"))
    }
    NULL
}

manifest_slot_semantic_problem.body:
{
    range <- slot$range
    object_reference <- slot$object_reference
    external_identifier <- slot$external_identifier
    primitive_ranges <- names(manifest_primitive_duckdb_types())
    if (!is_nonempty_string(range) || !nzchar(trimws(range))) {
        return(manifest_contract_problem("A slot range must be one non-empty string.", paste0(field, ".range"), "slot_range_contract"))
    }
    if (!is.null(external_identifier) && (!is_nonempty_string(external_identifier) || !nzchar(trimws(external_identifier)) || slot$multivalued || object_reference || !identical(slot$duckdb_type, "VARCHAR") || slot$sensitive)) {
        return(manifest_contract_problem(paste("External identifiers must use a public scalar non-object text slot."), paste0(field, ".external_identifier"), "external_identifier_contract"))
    }
    if (object_reference && !range %in% known_class_ranges) {
        return(manifest_contract_problem("Object-reference slot range does not resolve to a declared class.", paste0(field, ".range"), "slot_range_contract"))
    }
    if (!object_reference && range %in% known_class_ranges) {
        return(manifest_contract_problem("A class-valued slot must be marked as an object reference.", paste0(field, ".object_reference"), "slot_range_contract"))
    }
    enum <- slot$enum
    if ((!is.null(enum) && (!enum %in% enum_names || !identical(range, enum) || object_reference)) || (is.null(enum) && range %in% enum_names)) {
        return(manifest_contract_problem("Slot enum metadata does not resolve to its declared range.", paste0(field, ".enum"), "slot_enum_contract"))
    }
    if (!object_reference && is.null(enum) && !range %in% primitive_ranges) {
        return(manifest_contract_problem("A scalar slot range must be a supported primitive or declared enum.", paste0(field, ".range"), "slot_range_contract"))
    }
    minimum <- slot$minimum_value
    maximum <- slot$maximum_value
    if ((!is.null(minimum) || !is.null(maximum)) && !slot$duckdb_type %in% c("BIGINT", "DECIMAL", "DOUBLE")) {
        return(manifest_contract_problem("Only numeric slots may declare minimum or maximum values.", field, "slot_bound_contract"))
    }
    bounds <- Filter(Negate(is.null), list(minimum, maximum))
    if (identical(slot$duckdb_type, "DECIMAL") && length(bounds) > 0L) {
        return(manifest_contract_problem(paste("Exact DECIMAL bounds are not supported until the manifest can", "represent them without binary floating-point loss."), field, "slot_bound_contract"))
    }
    if (identical(slot$duckdb_type, "BIGINT") && any(vapply(bounds, function(bound) bound != trunc(bound) || abs(bound) > 9007199254740991, logical(1)))) {
        return(manifest_contract_problem("BIGINT bounds must be exact integers within the safe JSON range.", field, "slot_bound_contract"))
    }
    if (!is.null(minimum) && !is.null(maximum) && minimum > maximum) {
        return(manifest_contract_problem("A slot minimum value cannot exceed its maximum value.", field, "slot_bound_contract"))
    }
    NULL
}

manifest_slot_shape_problem.body:
{
    required <- c("name", "range", "duckdb_type", "required", "multivalued", "identifier", "object_reference")
    allowed <- c(required, "view_column", "ordered", "enum", "meaning", "pattern", "datetime_format", "minimum_value", "maximum_value", "external_identifier", "search_weight", "sensitive")
    problem <- manifest_object_fields_problem(slot, field, required, allowed)
    if (!is.null(problem)) {
        return(problem)
    }
    string_fields <- c("name", "range", "duckdb_type")
    if (!all(vapply(slot[string_fields], manifest_json_nonblank_string, logical(1)))) {
        return(manifest_contract_problem("Manifest slot identity and type fields must be nonblank strings.", field))
    }
    if ("meaning" %in% names(slot) && !manifest_json_nullable_linkml_reference(slot$meaning)) {
        return(manifest_contract_problem("Manifest slot meaning must be a valid URI or CURIE.", paste0(field, ".meaning"), "manifest_reference_contract"))
    }
    boolean_fields <- intersect(c("required", "multivalued", "ordered", "identifier", "object_reference", "sensitive"), names(slot))
    if (!all(vapply(slot[boolean_fields], manifest_json_boolean, logical(1)))) {
        return(manifest_contract_problem("Manifest slot flags must be JSON booleans.", field))
    }
    nullable_strings <- intersect(c("view_column", "enum", "meaning", "pattern", "external_identifier"), names(slot))
    if (!all(vapply(slot[nullable_strings], manifest_json_nullable_string, logical(1)))) {
        return(manifest_contract_problem("Manifest slot metadata must use strings or null.", field))
    }
    nonblank_nullable <- intersect(c("view_column", "enum", "meaning", "external_identifier"), names(slot))
    if (!all(vapply(slot[nonblank_nullable], manifest_json_nullable_nonblank_string, logical(1)))) {
        return(manifest_contract_problem("Manifest slot semantic identifiers must be nonblank strings or null.", field))
    }
    if ("datetime_format" %in% names(slot) && (!manifest_json_nullable_string(slot$datetime_format) || (!is.null(slot$datetime_format) && !slot$datetime_format %in% c("offset", "local_utc")))) {
        return(manifest_contract_problem("Manifest slot datetime format is invalid.", paste0(field, ".datetime_format")))
    }
    if ("search_weight" %in% names(slot) && !manifest_json_nullable_number(slot$search_weight)) {
        return(manifest_contract_problem("Manifest slot search weight must be a number or null.", paste0(field, ".search_weight")))
    }
    for (bound in intersect(c("minimum_value", "maximum_value"), names(slot))) {
        if (!manifest_json_nullable_number(slot[[bound]])) {
            return(manifest_contract_problem("Manifest slot bounds must be finite numbers or null.", paste(field, bound, sep = ".")))
        }
    }
    if ("pattern" %in% names(slot) && !manifest_regex_is_valid(slot$pattern)) {
        return(manifest_contract_problem("Manifest slot pattern is not a valid R regular expression.", paste0(field, ".pattern"), "slot_pattern_contract"))
    }
    NULL
}

