normalize_candidate_class.body:
{
    issues <- list()
    if (anyDuplicated(names(data))) {
        issues[[1L]] <- new_plan_issue(record_class = record_class, field = "records", rule = "unique_field_names", message = paste0("`", record_class, "` contains duplicate fields."))
        return(list(staged = empty_candidate_class(record_class, contract), issues = issues))
    }
    allowed <- c(names(contract$slots), ".graft_origin_key")
    unknown <- setdiff(names(data), allowed)
    for (field in unknown) {
        issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, field = field, rule = "known_field", message = paste0("Unknown field `", record_class, ".", field, "`."))
    }
    data <- data[setdiff(names(data), unknown)]
    normalized <- list()
    invalid_fields <- character()
    for (slot_name in names(contract$slots)) {
        slot <- contract$slots[[slot_name]]
        source <- if (slot_name %in% names(data)) 
            data[[slot_name]]
        else NULL
        values <- if (scalar_logical(slot$multivalued)) {
            rep(list(missing_slot_vector(slot, 0L)), nrow(data))
        }
        else {
            missing_slot_vector(slot, nrow(data))
        }
        for (index in seq_len(nrow(data))) {
            result <- normalize_candidate_value(source, index, slot, record_class)
            if (!is.null(result$issue)) {
                issues[[length(issues) + 1L]] <- result$issue
                invalid_fields <- c(invalid_fields, candidate_field_key(index, slot_name))
            }
            if (!is.null(result$value)) {
                values[[index]] <- result$value
            }
        }
        normalized[[slot_name]] <- if (scalar_logical(slot$multivalued)) {
            I(values)
        }
        else {
            values
        }
    }
    origin <- rep(NA_character_, nrow(data))
    if (".graft_origin_key" %in% names(data)) {
        source <- data[[".graft_origin_key"]]
        if (!is.character(source) && !is.factor(source)) {
            for (index in seq_len(nrow(data))) {
                issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, input_row = index, field = ".graft_origin_key", rule = "character", message = "`.graft_origin_key` must be a character value.")
            }
        }
        else {
            origin <- trimws(as.character(source))
            origin[is.na(origin) | !nzchar(origin)] <- NA_character_
        }
    }
    normalized <- as.data.frame(normalized, stringsAsFactors = FALSE, check.names = FALSE, optional = TRUE)
    identities <- vector("list", nrow(normalized))
    for (index in seq_len(nrow(normalized))) {
        row <- normalized[index, , drop = FALSE]
        external <- external_identifiers_for_row(contract, row)
        for (slot_name in names(external$normalized_slots)) {
            normalized[[slot_name]][[index]] <- external$normalized_slots[[slot_name]]
        }
        derived <- derive_origin_key(contract, row)
        if (!is.na(origin[[index]])) {
            derived <- origin[[index]]
        }
        identities[[index]] <- list(supplied_id = scalar_character(row$id[[1L]]), origin_key = derived, identifiers = external$identifiers)
    }
    list(staged = list(class = record_class, contract = contract, data = normalized, input_row = seq_len(nrow(normalized)), invalid_fields = unique(invalid_fields), identities = identities), issues = issues)
}

normalize_candidate_container.body:
{
    issues <- list()
    staged <- list()
    if (!is.list(records) || is.data.frame(records)) {
        issues[[1L]] <- new_plan_issue(field = "records", rule = "named_class_data_frames", message = "`records` must be a named list of data frames.")
        return(list(staged = staged, issues = issues))
    }
    record_names <- names(records)
    if (is.null(record_names)) {
        issues[[1L]] <- new_plan_issue(field = "records", rule = "unique_class_names", message = "`records` must have unique, non-empty class names.")
        return(list(staged = staged, issues = issues))
    }
    invalid_names <- which(is.na(record_names) | !nzchar(record_names))
    for (index in invalid_names) {
        issues[[length(issues) + 1L]] <- new_plan_issue(field = "records", rule = "unique_class_names", message = "A record class name is missing or empty.")
    }
    duplicated_names <- unique(record_names[duplicated(record_names)])
    for (record_class in duplicated_names) {
        issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, field = "records", rule = "unique_class_names", message = paste0("Record class `", record_class, "` occurs more than once."))
    }
    usable <- which(!is.na(record_names) & nzchar(record_names) & !record_names %in% duplicated_names)
    known <- names(store$schema$manifest$classes)
    for (index in usable) {
        record_class <- record_names[[index]]
        data <- records[[index]]
        if (!record_class %in% known) {
            issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, field = "records", rule = "known_concrete_class", message = paste0("Unknown concrete record class `", record_class, "`."))
            next
        }
        if (!is.data.frame(data)) {
            issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, field = record_class, rule = "data_frame", message = paste0("`", record_class, "` must contain a data frame."))
            next
        }
        class_result <- normalize_candidate_class(record_class, data, store$schema$manifest$classes[[record_class]])
        staged[[record_class]] <- class_result$staged
        issues <- c(issues, class_result$issues)
    }
    list(staged = staged, issues = issues)
}

normalize_candidate_value.body:
{
    slot_name <- scalar_character(slot$name)
    multivalued <- scalar_logical(slot$multivalued)
    if (is.null(source)) {
        return(list(value = if (multivalued) NULL else NULL, issue = NULL))
    }
    if (multivalued && !is.list(source)) {
        return(list(value = NULL, issue = new_plan_issue(record_class = record_class, input_row = index, field = slot_name, rule = "list_column", message = paste0("Multivalued field `", record_class, ".", slot_name, "` must be a list-column."))))
    }
    raw <- if (is.list(source) && !inherits(source, "POSIXt")) {
        source[[index]]
    }
    else {
        source[index]
    }
    if (is.null(raw) || length(raw) == 0L) {
        return(list(value = NULL, issue = NULL))
    }
    if (!multivalued && length(raw) != 1L) {
        return(list(value = NULL, issue = new_plan_issue(record_class = record_class, input_row = index, field = slot_name, rule = "scalar_column", message = paste0("Scalar field `", record_class, ".", slot_name, "` must contain one value."))))
    }
    missing_candidate <- if (is.factor(raw)) 
        as.character(raw)
    else raw
    if (!multivalued && !scalar_logical(slot$identifier) && is_missing_value(missing_candidate)) {
        return(list(value = NULL, issue = NULL))
    }
    if (scalar_logical(slot$object_reference)) {
        if (is.factor(raw)) {
            raw <- as.character(raw)
        }
        if (!is.character(raw)) {
            return(list(value = NULL, issue = new_plan_issue(record_class = record_class, input_row = index, field = slot_name, rule = "object_reference_type", message = paste0("Object field `", record_class, ".", slot_name, "` must contain identifiers."))))
        }
        return(list(value = as.character(raw), issue = NULL))
    }
    converted <- coerce_candidate_vector(raw, slot)
    if (is.null(converted) || length(converted) != length(raw)) {
        type <- validation_slot_type(slot)
        range <- scalar_character(slot$range)
        issue_type <- if (identical(type, "VARCHAR") && range %in% c("uri", "uriorcurie")) {
            range
        }
        else {
            tolower(type)
        }
        return(list(value = NULL, issue = new_plan_issue(record_class = record_class, input_row = index, field = slot_name, rule = paste0("type_", issue_type), message = paste0("Field `", record_class, ".", slot_name, "` cannot be coerced to ", type, "."))))
    }
    if (!multivalued && !scalar_logical(slot$identifier) && is_missing_value(converted)) {
        return(list(value = NULL, issue = NULL))
    }
    list(value = converted, issue = NULL)
}

normalize_canonical_url.body:
{
    match <- regexec("^(https?)://([^/?#]*)([^?#]*)(\\?[^#]*)?(?:#.*)?$", value, ignore.case = TRUE, perl = TRUE)
    parts <- regmatches(value, match)[[1L]]
    if (length(parts) == 0L || !nzchar(parts[[3L]])) {
        return(value)
    }
    scheme <- tolower(parts[[2L]])
    authority <- normalize_url_authority(parts[[3L]], scheme)
    if (is.na(authority)) {
        return(value)
    }
    path <- parts[[4L]]
    query <- if (length(parts) >= 5L) 
        parts[[5L]]
    else ""
    if (!nzchar(path)) {
        path <- "/"
    }
    else if (!identical(path, "/") && endsWith(path, "/")) {
        path <- substr(path, 1L, nchar(path) - 1L)
    }
    paste0(scheme, "://", authority, path, query)
}

