normalize_external_identifier.body:
{
    if (is.null(value) || length(value) == 0L || is.na(value[[1L]])) {
        return(NA_character_)
    }
    value <- trimws(as.character(value[[1L]]))
    if (!nzchar(value)) {
        return(NA_character_)
    }
    namespace <- tolower(trimws(namespace))
    switch(namespace, doi = {
        normalized <- tolower(value)
        normalized <- sub("^https?://(dx\\.)?doi\\.org/", "", normalized)
        normalized <- sub("^doi\\s*:\\s*", "", normalized)
        trimws(normalized)
    }, inchikey = toupper(gsub("\\s+", "", value)), cas = toupper(gsub("\\s+", "", sub("^cas\\s*:\\s*", "", value, ignore.case = TRUE))), content_hash = tolower(gsub("\\s+", "", value)), canonical_url = normalize_canonical_url(value), value)
}

