normalize_graft_schema_output.body:
{
    if (is.null(output)) {
        return(normalizePath(tempfile("graft-schema-", fileext = ".graft.json"), winslash = "/", mustWork = FALSE))
    }
    if (!is_nonempty_string(output)) {
        abort_schema_error("`output` must be one non-empty `.graft.json` path or `NULL`.", argument = "output")
    }
    output <- path.expand(output)
    if (!endsWith(tolower(output), ".graft.json")) {
        abort_schema_error("`output` must use the `.graft.json` extension.", argument = "output", output_path = output)
    }
    parent <- dirname(output)
    if (!dir.exists(parent)) {
        abort_schema_error("The parent directory for `output` does not exist.", argument = "output", output_path = output)
    }
    output <- normalizePath(file.path(parent, basename(output)), winslash = "/", mustWork = FALSE)
    if (dir.exists(output)) {
        abort_schema_error("`output` must be a file path, not a directory.", argument = "output", output_path = output)
    }
    output
}

