normalize_url_authority.body:
{
    at <- gregexpr("@", authority, fixed = TRUE)[[1L]]
    if (identical(at, -1L)) {
        userinfo <- ""
        host_port <- authority
    }
    else {
        split_at <- utils::tail(at, 1L)
        userinfo <- substr(authority, 1L, split_at)
        host_port <- substr(authority, split_at + 1L, nchar(authority))
    }
    if (startsWith(host_port, "[")) {
        match <- regexec("^(\\[[^]]+\\])(?::([0-9]+))?$", host_port, perl = TRUE)
    }
    else {
        match <- regexec("^([^:]+)(?::([0-9]+))?$", host_port, perl = TRUE)
    }
    parts <- regmatches(host_port, match)[[1L]]
    if (length(parts) == 0L || !nzchar(parts[[2L]])) {
        return(NA_character_)
    }
    host <- tolower(parts[[2L]])
    if (!startsWith(host, "[") && startsWith(host, "www.")) {
        host <- substring(host, 5L)
    }
    port <- if (length(parts) >= 3L) 
        parts[[3L]]
    else ""
    default_port <- identical(port, "80") && identical(scheme, "http") || identical(port, "443") && identical(scheme, "https")
    if (isTRUE(default_port)) {
        port <- ""
    }
    paste0(userinfo, host, if (nzchar(port)) 
        paste0(":", port)
    else "")
}

okf_batch_actor.body:
{
    producer <- okf_default(okf_scalar_text(producer), "graft")
    if (startsWith(producer, "human:") || startsWith(producer, "process:")) {
        return(producer)
    }
    producer <- gsub("[^A-Za-z0-9._-]+", "-", producer)
    producer <- gsub("(^-+|-+$)", "", producer)
    if (!nzchar(producer)) {
        producer <- "graft"
    }
    version <- okf_default(okf_scalar_text(version), "unknown")
    version <- gsub("[^A-Za-z0-9._-]+", "-", version)
    paste0(producer, "/", version)
}

