okf_bundle_digest.body:
{
    root_link <- Sys.readlink(path)
    if (!is.na(root_link) && nzchar(root_link)) {
        abort_backend_error("Symbolic links are not supported in managed OKF bundles.", operation = "okf_bundle_files", path = path)
    }
    root <- normalizePath(path, winslash = "/", mustWork = TRUE)
    files <- okf_bundle_entries(root, include_directories = FALSE)
    relative <- substring(normalizePath(files, winslash = "/", mustWork = TRUE), nchar(root) + 2L)
    order <- order(relative, method = "radix")
    files <- files[order]
    relative <- relative[order]
    entries <- vapply(seq_along(files), function(index) {
        content_digest <- if (identical(relative[[index]], "index.md")) {
            lines <- readLines(files[[index]], warn = FALSE, encoding = "UTF-8")
            lines <- okf_index_digest_lines(lines)
            digest::digest(paste0(paste(lines, collapse = "\n"), "\n"), algo = "sha256", serialize = FALSE)
        }
        else {
            digest::digest(files[[index]], algo = "sha256", file = TRUE, serialize = FALSE)
        }
        paste0(relative[[index]], "\n", content_digest)
    }, character(1))
    paste0("sha256:", digest::digest(paste(entries, collapse = "\n"), algo = "sha256", serialize = FALSE))
}

okf_bundle_documents.body:
{
    classes <- sort(unique(vapply(concepts, function(.x) .x$class, character(1))), method = "radix")
    grouped <- split(concepts, vapply(concepts, function(.x) .x$class, character(1)))
    class_entries <- vapply(classes, function(class) {
        encoded <- utils::URLencode(class, reserved = TRUE)
        count <- length(grouped[[class]])
        paste0("* [", okf_link_text(class), "](concepts/", encoded, "/) - ", count, if (count == 1L) 
            " concept."
        else " concepts.")
    }, character(1))
    fingerprints <- schema$manifest$fingerprints
    schema_metadata <- schema$manifest$schema
    index_frontmatter <- okf_compact(list(okf_version = graft_okf_version, graft = list(profile = "graft-okf", profile_version = graft_okf_profile_version, schema_id = scalar_character(schema_metadata$id), schema_name = scalar_character(schema_metadata$name), schema_version = scalar_character(schema_metadata$version), schema_build_digest = scalar_character(fingerprints$build_digest), structural_digest = scalar_character(fingerprints$structural_digest), as_of_batch_id = boundary$batch_id, as_of_committed_at = if (is.null(boundary$committed_at)) {
        NULL
    } else {
        okf_datetime(boundary$committed_at)
    }, scope = if (setequal(export_classes, names(schema$manifest$classes))) {
        "complete"
    } else {
        "selected"
    }, classes = sort(export_classes, method = "radix"), concept_count = length(concepts), bundle_digest = bundle_digest)))
    title <- scalar_character(schema_metadata$name, "Graft knowledge")
    body <- c(paste0("# ", title), "", paste("This Open Knowledge Format bundle is a portable projection of accepted", "Graft revisions. Its `graft` metadata preserves the governing schema,", "batch, revision, and stable record identity."), "", "# Concepts", "", if (length(class_entries) == 0L) {
        "No concepts were accepted at this boundary."
    } else {
        class_entries
    })
    documents <- c(stats::setNames(vapply(concepts, function(.x) okf_document(.x$frontmatter, .x$body), character(1)), vapply(concepts, function(.x) .x$path, character(1))), index.md = okf_document(index_frontmatter, paste(body, collapse = "\n")))
    concepts_index <- c("# Concepts", "", if (length(class_entries) == 0L) {
        "No concepts were accepted at this boundary."
    } else {
        sub("](concepts/", "](", class_entries, fixed = TRUE)
    })
    documents[["concepts/index.md"]] <- paste(c(concepts_index, ""), collapse = "\n")
    for (class in classes) {
        class_concepts <- grouped[[class]]
        class_concepts <- class_concepts[order(vapply(class_concepts, function(.x) .x$title, character(1)), method = "radix")]
        entries <- vapply(class_concepts, function(concept) {
            description <- if (is.null(concept$description)) {
                ""
            }
            else {
                paste0(" - ", concept$description)
            }
            paste0("* [", okf_link_text(concept$title), "](", basename(concept$path), ")", description)
        }, character(1))
        relative <- file.path("concepts", utils::URLencode(class, reserved = TRUE), "index.md")
        documents[[relative]] <- paste(c(paste0("# ", okf_heading_text(class)), "", entries, ""), collapse = "\n")
    }
    names(documents) <- gsub("\\\\", "/", names(documents))
    documents
}

