okf_import_proposals.body:
{
    files <- okf_concept_files(path)
    proposals <- list()
    for (file in files) {
        frontmatter <- okf_parse_frontmatter(file)
        graft <- frontmatter$graft
        if (!is.list(graft) || is.null(names(graft))) {
            abort_okf_import(paste0("Concept `", basename(file), "` does not contain an editable Graft record mapping."), path = file)
        }
        record_class <- scalar_character(graft$class, NA_character_)
        record_id <- scalar_character(graft$record_id, NA_character_)
        profile <- scalar_character(graft$profile, "graft-okf")
        record <- graft$record
        if (is.na(record_class) || is.na(record_id) || !identical(profile, "graft-okf") || !is.list(record) || is.null(names(record))) {
            abort_okf_import(paste0("Concept `", basename(file), "` does not contain an editable Graft record mapping."), path = file)
        }
        if (!identical(scalar_character(frontmatter$type), record_class)) {
            abort_okf_import("An OKF concept type does not match its Graft class.", path = file, record_id = record_id, record_class = record_class)
        }
        contract <- store$schema$manifest$classes[[record_class]]
        if (is.null(contract)) {
            abort_okf_import(paste0("Unknown Graft class `", record_class, "`."), path = file, record_class = record_class)
        }
        okf_validate_import_record(record, contract, record_id, file)
        record <- okf_normalize_import_record(record, contract)
        if (!is.null(proposals[[record_id]])) {
            abort_okf_import(paste0("Record `", record_id, "` appears in more than one concept."), record_id = record_id)
        }
        proposals[[record_id]] <- list(class = record_class, record = record, base_digest = scalar_character(graft$public_content_digest, NA_character_), path = file)
    }
    proposals
}

