okf_install_staged_bundle.body:
{
    if (!dir.exists(path)) {
        if (!file.rename(stage, path)) {
            abort_backend_error("Could not install the staged OKF bundle.", operation = "export_okf", path = path)
        }
        return(invisible(path))
    }
    stopifnot(overwrite, okf_is_graft_bundle(path))
    backup <- tempfile(pattern = paste0(".", basename(path), "-backup-"), tmpdir = dirname(path))
    if (!file.rename(path, backup)) {
        abort_backend_error("Could not stage the existing OKF bundle for replacement.", operation = "export_okf", path = path)
    }
    installed <- file.rename(stage, path)
    if (!installed) {
        file.rename(backup, path)
        abort_backend_error("Could not install the replacement OKF bundle.", operation = "export_okf", path = path)
    }
    unlink(backup, recursive = TRUE, force = TRUE)
    invisible(path)
}

