okf_output_path.body:
{
    path <- validate_scalar_text(path, "path")
    path <- path.expand(path)
    if (!okf_is_absolute_path(path)) {
        path <- file.path(getwd(), path)
    }
    parent <- dirname(path)
    if (!dir.exists(parent) && !dir.create(parent, recursive = TRUE)) {
        abort_backend_error(paste0("Could not create the OKF parent directory `", parent, "`."), operation = "export_okf", path = path)
    }
    parent <- normalizePath(parent, winslash = "/", mustWork = TRUE)
    file.path(parent, basename(path))
}

okf_parse_frontmatter.body:
{
    lines <- readLines(path, warn = FALSE, encoding = "UTF-8")
    delimiters <- which(lines == "---")
    if (length(delimiters) < 2L || delimiters[[1L]] != 1L || delimiters[[2L]] <= 2L) {
        abort_backend_error("An OKF document has malformed YAML frontmatter.", operation = "export_okf_validate", path = path)
    }
    text <- paste(lines[seq.int(delimiters[[1L]] + 1L, delimiters[[2L]] - 1L)], collapse = "\n")
    value <- tryCatch(yaml::yaml.load(text, eval.expr = FALSE), error = function(error) {
        abort_backend_error("An OKF document has invalid YAML frontmatter.", operation = "export_okf_validate", path = path, parent = error)
    })
    if (!is.list(value) || is.null(names(value))) {
        abort_backend_error("OKF frontmatter must be a YAML mapping.", operation = "export_okf_validate", path = path)
    }
    value
}

okf_record_body.body:
{
    record <- item$record
    contract <- item$contract
    lines <- c(paste0("# ", okf_heading_text(title)))
    statement_field <- intersect(c("statement", "statement_text", "text"), names(record))
    statement <- if (length(statement_field) > 0L) {
        okf_scalar_text(record[[statement_field[[1L]]]])
    }
    else {
        NULL
    }
    if (!is.null(statement)) {
        citation_marks <- okf_citation_marks(sources$labels)
        lines <- c(lines, "", "## Statement", "", paste0(statement, citation_marks))
    }
    else if (!is.null(description)) {
        citation_marks <- okf_citation_marks(sources$labels)
        lines <- c(lines, "", "## Summary", "", paste0(description, citation_marks))
    }
    relationships <- okf_relationship_lines(record, contract, lookup)
    if (length(relationships) > 0L) {
        lines <- c(lines, "", "## Relationships", "", relationships)
    }
    excluded <- unique(c("id", scalar_character(contract$label_slot), statement_field, "description", "summary", "created_at", "updated_at", names(Filter(function(.x) scalar_logical(.x$object_reference), contract$slots))))
    details <- okf_detail_rows(record, contract, excluded)
    if (length(details) > 0L) {
        lines <- c(lines, "", "## Details", "", "| Field | Value |", "|---|---|", details)
    }
    if (length(sources$labels) > 0L) {
        source_titles <- stats::setNames(vapply(sources$entries, function(.x) .x$title, character(1)), sources$labels)
        footnotes <- paste0("[^", names(source_titles), "]: ", unname(source_titles))
        lines <- c(lines, "", footnotes)
    }
    paste(lines, collapse = "\n")
}

okf_record_date.body:
{
    if (is.null(value) || length(value) != 1L || is.na(value)) {
        return(NULL)
    }
    if (inherits(value, "Date")) {
        return(format(value, "%Y-%m-%d"))
    }
    value <- as.character(value)
    if (grepl("^\\d{4}-\\d{2}-\\d{2}$", value)) 
        value
    else NULL
}

okf_record_description.body:
{
    candidates <- c("description", "summary", "statement", "statement_text", "implication", "text")
    for (candidate in candidates) {
        value <- okf_scalar_text(record[[candidate]])
        if (!is.null(value) && !identical(value, title)) {
            return(gsub("[\r\n]+", " ", value))
        }
    }
    NULL
}

okf_record_sources.body:
{
    record <- item$record
    contract <- item$contract
    source_ids <- character()
    for (slot_name in names(contract$slots)) {
        slot <- contract$slots[[slot_name]]
        if (!scalar_logical(slot$object_reference)) {
            next
        }
        target_role <- okf_lookup_role(lookup, scalar_character(slot$range))
        source_slot <- tolower(slot_name) %in% c("source", "source_id", "sources", "source_documents")
        if (!source_slot && !identical(target_role, "source")) {
            next
        }
        source_ids <- c(source_ids, okf_reference_values(record[[slot_name]]))
    }
    if (identical(scalar_character(contract$role), "statement")) {
        statement_id <- item$metadata$record_id[[1L]]
        evidence_sources <- attr(lookup, "evidence_sources", exact = TRUE)
        source_ids <- c(source_ids, evidence_sources[[statement_id]])
    }
    source_ids <- sort(unique(source_ids), method = "radix")
    entries <- list()
    labels <- character()
    for (source_id in source_ids) {
        if (!exists(source_id, envir = lookup, inherits = FALSE)) {
            next
        }
        source <- get(source_id, envir = lookup, inherits = FALSE)
        label <- paste0("source-", substr(digest::digest(source_id, algo = "sha256", serialize = FALSE), 1L, 12L))
        uri <- okf_source_uri(source$item$record)
        entries[[length(entries) + 1L]] <- list(id = label, resource = okf_default(uri, paste0("/", source$path)), title = source$title)
        labels[[length(labels) + 1L]] <- label
    }
    list(entries = entries, labels = labels)
}

okf_record_status.body:
{
    value <- tolower(okf_default(okf_scalar_text(record$status), "stable"))
    if (value %in% c("draft", "proposed", "pending")) {
        return("draft")
    }
    if (value %in% c("deprecated", "superseded", "retired", "inactive")) {
        return("deprecated")
    }
    "stable"
}

okf_record_title.body:
{
    candidates <- unique(c(scalar_character(contract$label_slot), "title", "name", "headline", "preferred_name", "statement", "statement_text"))
    for (candidate in candidates) {
        value <- okf_scalar_text(record[[candidate]])
        if (!is.null(value)) {
            return(okf_heading_text(value))
        }
    }
    id
}

okf_reference_values.body:
{
    if (is.null(value) || length(value) == 0L) {
        return(character())
    }
    values <- as.character(unlist(value, use.names = FALSE))
    values[!is.na(values) & nzchar(values)]
}

okf_relationship_lines.body:
{
    lines <- character()
    for (slot_name in names(contract$slots)) {
        slot <- contract$slots[[slot_name]]
        if (!scalar_logical(slot$object_reference) || scalar_logical(slot$sensitive)) {
            next
        }
        values <- okf_reference_values(record[[slot_name]])
        if (length(values) == 0L) {
            next
        }
        rendered <- vapply(values, function(value) {
            if (!exists(value, envir = lookup, inherits = FALSE)) {
                return(paste0("`", okf_inline_code(value), "`"))
            }
            target <- get(value, envir = lookup, inherits = FALSE)
            paste0("[", okf_link_text(target$title), "](/", target$path, ")")
        }, character(1))
        label <- gsub("_", " ", slot_name, fixed = TRUE)
        label <- paste0(toupper(substr(label, 1L, 1L)), substring(label, 2L))
        lines <- c(lines, paste0("- **", label, ":** ", paste(rendered, collapse = ", ")))
    }
    lines
}

okf_render_value.body:
{
    if (is.null(value) || length(value) == 0L || all(is.na(value))) {
        return(NULL)
    }
    if (inherits(value, "POSIXt")) {
        return(okf_datetime(value))
    }
    if (inherits(value, "Date")) {
        return(format(value, "%Y-%m-%d"))
    }
    values <- as.character(unlist(value, use.names = FALSE))
    values <- values[!is.na(values)]
    if (length(values) == 0L) 
        NULL
    else paste(values, collapse = ", ")
}

okf_resolve_path.body:
{
    validate_store_backend(store)
    if (!is.null(path)) {
        return(okf_normalize_path(path))
    }
    if (identical(store$okf_mode, "managed") && !is.null(store$okf_path)) {
        return(store$okf_path)
    }
    abort_validation_error(paste("This store does not have a managed OKF directory.", "Supply `path` or connect a file-backed store with `okf = \"managed\"`."), field = "path", rule = "managed_okf_path", observed_value = path)
}

okf_snapshot_bundle.body:
{
    source <- normalizePath(path, winslash = "/", mustWork = TRUE)
    entries <- okf_bundle_entries(source, include_directories = TRUE)
    snapshot <- tempfile("graft-okf-snapshot-")
    if (!dir.create(snapshot)) {
        abort_backend_error("Could not create a stable OKF read snapshot.", operation = "okf_snapshot_bundle", path = snapshot)
    }
    complete <- FALSE
    on.exit(if (!complete) unlink(snapshot, recursive = TRUE, force = TRUE), add = TRUE)
    relative <- substring(entries, nchar(source) + 2L)
    info <- file.info(entries)
    directories <- relative[info$isdir]
    directories <- directories[order(nchar(directories), directories, method = "radix")]
    for (directory in directories) {
        destination <- file.path(snapshot, directory)
        if (!dir.create(destination)) {
            abort_backend_error("Could not create a directory in the stable OKF read snapshot.", operation = "okf_snapshot_bundle", path = destination)
        }
    }
    files <- entries[!info$isdir]
    file_relative <- relative[!info$isdir]
    copied <- vapply(seq_along(files), function(index) {
        file.copy(files[[index]], file.path(snapshot, file_relative[[index]]), overwrite = FALSE, copy.mode = FALSE, copy.date = FALSE)
    }, logical(1))
    if (!all(copied %in% TRUE)) {
        abort_backend_error("Could not create a complete stable OKF read snapshot.", operation = "okf_snapshot_bundle", path = files[which(!(copied %in% TRUE))[[1L]]])
    }
    result <- list(path = snapshot, bundle_digest = okf_bundle_digest(snapshot))
    complete <- TRUE
    result
}

okf_snapshot_concepts.body:
{
    path_map <- okf_snapshot_path_map(snapshot)
    concept_lookup <- okf_snapshot_lookup(snapshot, path_map)
    lapply(seq_along(snapshot), function(index) {
        okf_snapshot_concept(snapshot[[index]], path_map[[index]], concept_lookup)
    })
}

okf_snapshot_latest_time.body:
{
    if (!is.null(boundary$committed_at)) {
        return(okf_datetime(boundary$committed_at))
    }
    if (length(snapshot) == 0L) {
        return(NULL)
    }
    values <- vapply(snapshot, function(.x) as.numeric(.x$metadata$committed_at[[1L]]), numeric(1))
    okf_datetime(as.POSIXct(max(values), origin = "1970-01-01", tz = "UTC"))
}

okf_snapshot_lookup.body:
{
    lookup <- new.env(parent = emptyenv())
    class_roles <- character()
    role_items <- list()
    for (index in seq_along(snapshot)) {
        item <- snapshot[[index]]
        id <- item$metadata$record_id[[1L]]
        title <- okf_record_title(item$record, item$contract, id)
        candidate <- list(item = item, path = path_map[[index]], title = title)
        assign(id, candidate, envir = lookup)
        role <- scalar_character(item$contract$role, "node")
        class <- item$metadata$class[[1L]]
        class_roles[[class]] <- role
        role_candidates <- role_items[[role]]
        role_candidates[[length(role_candidates) + 1L]] <- candidate
        role_items[[role]] <- role_candidates
    }
    evidence_sources <- list()
    evidence <- role_items$evidence
    if (is.null(evidence)) {
        evidence <- list()
    }
    for (candidate in evidence) {
        statement_id <- okf_scalar_text(candidate$item$record$statement_id)
        if (is.null(statement_id)) {
            next
        }
        evidence_sources[[statement_id]] <- c(evidence_sources[[statement_id]], okf_reference_values(candidate$item$record$source_id))
    }
    attr(lookup, "class_roles") <- class_roles
    attr(lookup, "evidence_sources") <- lapply(evidence_sources, function(.x) sort(unique(.x), method = "radix"))
    lookup
}

okf_snapshot_path_map.body:
{
    paths <- vapply(snapshot, function(item) {
        file.path("concepts", utils::URLencode(item$metadata$class[[1L]], reserved = TRUE), paste0(utils::URLencode(item$metadata$record_id[[1L]], reserved = TRUE), ".md"))
    }, character(1))
    gsub("\\\\", "/", paths)
}

okf_snapshot_records.body:
{
    class_placeholders <- paste(rep("?", length(classes)), collapse = ", ")
    boundary_sql <- if (is.null(boundary$commit_order)) {
        ""
    }
    else {
        " AND r.commit_order <= ?"
    }
    params <- c(as.list(classes), if (is.null(boundary$commit_order)) {
        list()
    } else {
        list(boundary$commit_order)
    })
    sql <- paste0("SELECT * EXCLUDE (snapshot_rank) FROM (", "SELECT r.revision_id, r.record_id, r.class, r.batch_id, ", "r.schema_build_digest, r.revision_number, r.payload_json, ", "r.content_digest, r.commit_order, b.committed_at, b.producer, ", "b.producer_version, b.source_run_id, ", "ROW_NUMBER() OVER (PARTITION BY r.class, r.record_id ", "ORDER BY r.revision_number DESC, r.revision_id ASC) AS snapshot_rank ", "FROM ", quote_identifier(store$connection, "_graft_record_revisions"), " r INNER JOIN ", 
        quote_identifier(store$connection, "_graft_batches"), " b ON r.batch_id = b.batch_id ", "WHERE b.status = 'committed' AND r.class IN (", class_placeholders, ")", boundary_sql, ") snapshot WHERE snapshot_rank = 1 ", "ORDER BY class, record_id LIMIT ", limit + 1L)
    rows <- with_duckdb_error("export_okf_snapshot", DBI::dbGetQuery(store$connection, sql, params = params))
    if (nrow(rows) > limit) {
        abort_limit_error(paste0("The OKF export contains more than ", limit, " concepts; no partial bundle was written."), argument = "limit", requested_limit = limit, hard_limit = graft_retrieval_limits$okf_concepts, observed_count = nrow(rows))
    }
    cache <- new.env(parent = emptyenv())
    records <- vector("list", nrow(rows))
    for (index in seq_len(nrow(rows))) {
        schema <- historical_schema(store, rows$schema_build_digest[[index]], cache)
        contract <- schema$manifest$classes[[rows$class[[index]]]]
        if (is.null(contract)) {
            abort_backend_error("An OKF snapshot revision is absent from its historical manifest.", operation = "export_okf_snapshot", record_id = rows$record_id[[index]], record_class = rows$class[[index]])
        }
        records[[index]] <- list(metadata = as.list(rows[index, , drop = FALSE]), record = public_revision_record(rows$payload_json[[index]], contract), contract = contract)
    }
    records
}

okf_source_uri.body:
{
    for (field in c("uri", "url", "locator", "doi")) {
        value <- okf_scalar_text(record[[field]])
        if (!is.null(value)) {
            return(value)
        }
    }
    NULL
}

okf_status.body:
{
    validate_retrieval_store(store)
    deep <- validate_history_flag(deep, "deep")
    configured <- !is.null(path) || (identical(store$okf_mode, "managed") && !is.null(store$okf_path))
    if (!configured) {
        return(new_okf_status(status = "unconfigured", reason = "No managed OKF directory is configured.", path = NULL, configured = FALSE))
    }
    path <- if (is.null(path)) {
        store$okf_path
    }
    else {
        okf_normalize_path(path)
    }
    if (!file.exists(path) && !dir.exists(path)) {
        return(new_okf_status(status = "missing", reason = "The managed OKF bundle has not been synchronized.", path = path))
    }
    if (!dir.exists(path)) {
        return(new_okf_status(status = "incompatible", reason = "The managed OKF path is not a directory.", path = path))
    }
    index <- tryCatch(okf_parse_frontmatter(file.path(path, "index.md")), error = identity)
    if (inherits(index, "error")) {
        return(new_okf_status(status = "incompatible", reason = conditionMessage(index), path = path))
    }
    graft <- index$graft
    if (!is.list(graft) || is.null(names(graft))) {
        return(new_okf_status(status = "incompatible", reason = "The directory is not a supported Graft OKF bundle.", path = path))
    }
    profile <- okf_default(graft$profile, NULL)
    profile_version <- as.character(okf_default(graft$profile_version, NA_character_))
    expected_build <- scalar_character(store$schema$manifest$fingerprints$build_digest)
    expected_structural <- store_schema_digest(store)
    observed_build <- scalar_character(graft$schema_build_digest, NA_character_)
    observed_structural <- scalar_character(graft$structural_digest, NA_character_)
    base_digest <- scalar_character(graft$bundle_digest, NA_character_)
    latest <- okf_current_boundary(store)
    expected_batch <- scalar_character(latest$batch_id, NA_character_)
    observed_batch <- scalar_character(graft$as_of_batch_id, NA_character_)
    common <- list(path = path, profile_version = profile_version, bundle_digest = base_digest, expected_batch_id = expected_batch, observed_batch_id = observed_batch, expected_schema_build_digest = expected_build, observed_schema_build_digest = observed_build)
    if (!identical(profile, "graft-okf") || !identical(profile_version, graft_okf_profile_version)) {
        return(do.call(new_okf_status, c(list(status = "incompatible", reason = "The directory is not a supported Graft OKF bundle."), common)))
    }
    if (!identical(observed_build, expected_build) || !identical(observed_structural, expected_structural)) {
        return(do.call(new_okf_status, c(list(status = "incompatible", reason = "The bundle was produced from a different active schema."), common)))
    }
    if (is.na(base_digest)) {
        return(do.call(new_okf_status, c(list(status = "incompatible", reason = "The bundle predates managed content digests; resynchronize it."), common)))
    }
    observed_digest <- if (deep) {
        tryCatch(okf_bundle_digest(path), error = identity)
    }
    else {
        NA_character_
    }
    if (inherits(observed_digest, "error")) {
        return(do.call(new_okf_status, c(list(status = "incompatible", reason = conditionMessage(observed_digest)), common)))
    }
    common$observed_bundle_digest <- observed_digest
    if (deep && !identical(observed_digest, base_digest)) {
        return(do.call(new_okf_status, c(list(status = "modified", reason = "The OKF working tree differs from its accepted projection."), common)))
    }
    if (!identical(observed_batch, expected_batch)) {
        return(do.call(new_okf_status, c(list(status = "stale", reason = "The store has accepted changes since the last synchronization."), common)))
    }
    if (deep && !identical(base_digest, okf_expected_bundle_digest(store, latest))) {
        return(do.call(new_okf_status, c(list(status = "modified", reason = "The OKF working tree differs from its accepted projection."), common)))
    }
    do.call(new_okf_status, c(list(status = "current", reason = "The OKF working tree matches current accepted Graft state."), common))
}

okf_table_text.body:
{
    value <- gsub("[\r\n]+", " ", value)
    value <- gsub("\\\\", "\\\\\\\\", value)
    gsub("|", "\\\\|", value, fixed = TRUE)
}

okf_validate_import_record.body:
{
    generated <- c("created_at", "updated_at")
    allowed <- setdiff(names(Filter(function(.x) !scalar_logical(.x$sensitive), contract$slots)), generated)
    unknown <- setdiff(names(record), allowed)
    if (length(unknown) > 0L) {
        abort_okf_import(paste0("Editable record `", record_id, "` contains unsupported field(s): ", paste(sort(unknown, method = "radix"), collapse = ", "), "."), path = path, record_id = record_id, fields = unknown)
    }
    identifiers <- names(Filter(function(.x) scalar_logical(.x$identifier), contract$slots))
    if (length(identifiers) != 1L) {
        abort_okf_import("An importable Graft class must declare exactly one identifier slot.", path = path, record_id = record_id, identifier_slots = identifiers)
    }
    observed_id <- scalar_character(record[[identifiers[[1L]]]], NA_character_)
    if (!identical(observed_id, record_id)) {
        abort_okf_import("The editable record identifier does not match its Graft record ID.", path = path, record_id = record_id, observed_id = observed_id)
    }
    invisible(record)
}

okf_validate_staged_bundle.body:
{
    index <- okf_parse_frontmatter(file.path(stage, "index.md"))
    if (!identical(as.character(index$okf_version), graft_okf_version)) {
        abort_backend_error("The staged OKF bundle has an invalid version marker.", operation = "export_okf_validate", path = stage)
    }
    files <- list.files(stage, pattern = "\\.md$", recursive = TRUE, full.names = TRUE, all.files = TRUE, no.. = TRUE)
    files <- files[!basename(files) %in% c("index.md", "log.md")]
    if (length(files) != expected_count) {
        abort_backend_error("The staged OKF bundle has an unexpected concept count.", operation = "export_okf_validate", expected_count = expected_count, observed_count = length(files))
    }
    for (path in files) {
        frontmatter <- okf_parse_frontmatter(path)
        if (is.null(okf_scalar_text(frontmatter$type))) {
            abort_backend_error("A staged OKF concept does not declare a non-empty type.", operation = "export_okf_validate", path = path)
        }
    }
    invisible(stage)
}

okf_write_documents.body:
{
    for (relative in names(documents)) {
        destination <- file.path(stage, relative)
        if (!dir.exists(dirname(destination)) && !dir.create(dirname(destination), recursive = TRUE)) {
            abort_backend_error("Could not create an OKF concept directory.", operation = "export_okf", path = dirname(destination))
        }
        okf_write_text(destination, documents[[relative]])
    }
}

okf_write_text.body:
{
    connection <- file(path, open = "wb")
    on.exit(close(connection), add = TRUE)
    writeChar(enc2utf8(text), connection, eos = NULL, useBytes = TRUE)
}

open_store_backend.body:
{
    if (!is_compiled_schema(schema)) {
        abort_schema_error("Internal store setup requires a compiled schema.")
    }
    validate_read_only(read_only)
    okf <- rlang::arg_match(okf)
    owns_connection <- is.null(connection)
    if (owns_connection) {
        validate_store_path(path)
        path <- duckdb_path(path)
        connection <- duckdb_connect(path, read_only)
    }
    else {
        validate_duckdb_connection(connection)
        if (!missing(path)) {
            validate_store_path(path)
            requested_path <- duckdb_path(path)
            connection_path <- duckdb_connection_path(connection)
            if (!identical(requested_path, connection_path)) {
                abort_backend_error(paste0("`path` does not identify the supplied DuckDB connection: `", requested_path, "` != `", connection_path, "`."), operation = "connect", argument = "path", store_path = requested_path, connection_path = connection_path)
            }
        }
        path <- duckdb_connection_path(connection)
    }
    okf_path <- resolve_managed_okf_path(path, okf, okf_path)
    capabilities <- duckdb_capabilities(read_only = read_only, owns_connection = owns_connection)
    store <- new_store_backend(schema = schema, connection = connection, owns_connection = owns_connection, read_only = read_only, path = path, capabilities = capabilities, okf_mode = okf, okf_path = okf_path)
    if (owns_connection) {
        reg.finalizer(store, function(store) {
            disconnect_owned_backend(store, finalizer = TRUE)
        }, onexit = TRUE)
    }
    store
}

parse_revision_payload.body:
{
    tryCatch(jsonlite::fromJSON(payload_json, simplifyVector = FALSE), error = function(error) {
        abort_backend_error(paste0("Could not parse a record revision payload: ", conditionMessage(error)), operation = "read_record_revision", parent = error)
    })
}

plan_candidate_changes.body:
{
    capacity <- as.integer(sum(vapply(staged, function(.x) nrow(.x$data), integer(1))))
    row_class <- character(capacity)
    row_input <- integer(capacity)
    row_record_id <- character(capacity)
    row_action <- character(capacity)
    row_payload_json <- character(capacity)
    row_content_digest <- character(capacity)
    row_changed_fields_json <- character(capacity)
    row_expected_revision_id <- rep(NA_character_, capacity)
    row_expected_revision_number <- rep(NA_real_, capacity)
    row_expected_content_digest <- rep(NA_character_, capacity)
    row_identity_reason <- character(capacity)
    row_identity_evidence <- character(capacity)
    change_fields <- character(capacity)
    cursor <- 0L
    current_index <- paste(current$class, current$record_id, sep = "\037")
    empty_evidence <- canonical_json(list())
    for (record_class in names(staged)) {
        class_staged <- staged[[record_class]]
        created_at <- if ("created_at" %in% names(class_staged$data)) {
            class_staged$data$created_at
        }
        else {
            NULL
        }
        updated_at <- if ("updated_at" %in% names(class_staged$data)) {
            class_staged$data$updated_at
        }
        else {
            NULL
        }
        for (index in seq_len(nrow(class_staged$data))) {
            record_id <- class_staged$data$id[[index]]
            if (is.na(record_id) || !nzchar(record_id)) {
                next
            }
            key <- paste(record_class, record_id, sep = "\037")
            current_row <- match(key, current_index)
            has_current <- !is.na(current_row) && !is.na(current$record_id[[current_row]])
            prior <- if (!has_current) {
                NULL
            }
            else {
                parse_revision_payload(current$payload_json[[current_row]])
            }
            payload <- candidate_record_payload(class_staged, index)
            digest <- logical_record_content_digest(payload)
            deleted <- has_current && identical(current$operation[[current_row]], "delete")
            action <- if (!has_current) {
                "insert"
            }
            else if (deleted) {
                "update"
            }
            else if (identical(digest, current$content_digest[[current_row]])) {
                "match"
            }
            else {
                "update"
            }
            if (!is.null(created_at)) {
                created_at[[index]] <- if (is.null(prior)) {
                  planned_at
                }
                else {
                  projection_coerce_timestamps(scalar_character(prior$created_at))[[1L]]
                }
                payload["created_at"] <- list(plan_canonical_slot_value(created_at[[index]], class_staged$contract$slots$created_at))
            }
            if (!is.null(updated_at)) {
                updated_at[[index]] <- if (identical(action, "match")) {
                  projection_coerce_timestamps(scalar_character(prior$updated_at))[[1L]]
                }
                else {
                  planned_at
                }
                payload["updated_at"] <- list(plan_canonical_slot_value(updated_at[[index]], class_staged$contract$slots$updated_at))
            }
            changed <- if (identical(action, "match")) {
                character()
            }
            else {
                logical_record_changed_fields(payload, prior)
            }
            cursor <- cursor + 1L
            row_class[[cursor]] <- record_class
            row_input[[cursor]] <- as.integer(index)
            row_record_id[[cursor]] <- record_id
            row_action[[cursor]] <- action
            row_payload_json[[cursor]] <- canonical_json(payload)
            row_content_digest[[cursor]] <- digest
            row_changed_fields_json[[cursor]] <- changed_fields_json(changed)
            row_identity_reason[[cursor]] <- scalar_character(class_staged$identities[[index]]$identity_reason, "unresolved")
            row_identity_evidence[[cursor]] <- scalar_character(class_staged$identities[[index]]$identity_evidence, empty_evidence)
            change_fields[[cursor]] <- paste(changed, collapse = ", ")
            if (has_current) {
                row_expected_revision_id[[cursor]] <- current$revision_id[[current_row]]
                row_expected_revision_number[[cursor]] <- as.numeric(current$revision_number[[current_row]])
                row_expected_content_digest[[cursor]] <- current$content_digest[[current_row]]
            }
        }
        if (!is.null(created_at)) {
            class_staged$data$created_at <- created_at
        }
        if (!is.null(updated_at)) {
            class_staged$data$updated_at <- updated_at
        }
        staged[[record_class]] <- class_staged
    }
    if (cursor == 0L) {
        return(list(staged = staged, rows = empty_candidate_rows(), changes = empty_plan_changes()))
    }
    used <- seq_len(cursor)
    rows <- data.frame(class = row_class[used], input_row = row_input[used], record_id = row_record_id[used], action = row_action[used], payload_json = row_payload_json[used], content_digest = row_content_digest[used], changed_fields_json = row_changed_fields_json[used], expected_revision_id = row_expected_revision_id[used], expected_revision_number = row_expected_revision_number[used], expected_content_digest = row_expected_content_digest[used], identity_reason = row_identity_reason[used], identity_evidence = row_identity_evidence[used], 
        stringsAsFactors = FALSE)
    changes <- data.frame(class = row_class[used], input_row = row_input[used], record_id = row_record_id[used], action = row_action[used], changed_fields = change_fields[used], expected_revision_id = row_expected_revision_id[used], expected_revision_number = row_expected_revision_number[used], expected_content_digest = row_expected_content_digest[used], proposed_content_digest = row_content_digest[used], identity_reason = row_identity_reason[used], identity_evidence = row_identity_evidence[used], 
        stringsAsFactors = FALSE)
    list(staged = staged, rows = rows, changes = changes)
}

plan_canonical_slot_scalar.body:
{
