}

plan_canonical_slot_value.body:
{
    if (!scalar_logical(slot$multivalued)) {
        return(plan_canonical_slot_scalar(value, slot))
    }
    if (is.null(value) || length(value) == 0L) {
        return(list())
    }
    values <- lapply(value, plan_canonical_slot_scalar, slot = slot)
    if (!scalar_logical(slot$ordered)) {
        keys <- vapply(values, canonical_json, character(1))
        values <- values[order(keys, method = "radix")]
    }
    unname(values)
}

plan_okf_import.body:
{
    validate_retrieval_store(store)
    status <- okf_status(store, path = path)
    if (!status$status %in% c("current", "modified")) {
        abort_okf_import(paste0("Cannot plan an OKF import from a `", status$status, "` bundle. ", status$reason), okf_status = status)
    }
    if (!identical(status$expected_batch_id, status$observed_batch_id)) {
        abort_okf_import("The edited OKF bundle is based on stale accepted knowledge.", okf_status = status)
    }
    snapshot <- okf_snapshot_bundle(status$path)
    on.exit(unlink(snapshot$path, recursive = TRUE, force = TRUE), add = TRUE)
    if (identical(status$status, "current") && !identical(snapshot$bundle_digest, status$bundle_digest)) {
        abort_okf_import(paste("The managed OKF bundle changed while creating a planning snapshot.", "Retry after filesystem writes have finished."), expected_bundle_digest = status$bundle_digest, observed_bundle_digest = snapshot$bundle_digest)
    }
    index <- okf_parse_frontmatter(file.path(snapshot$path, "index.md"))
    if (!identical(scalar_character(index$graft$scope), "complete")) {
        abort_okf_import("Only a complete managed OKF bundle can be imported.", observed_scope = index$graft$scope)
    }
    current <- okf_import_current_records(store)
    proposals <- okf_import_proposals(store, snapshot$path)
    removed <- setdiff(names(current), names(proposals))
    if (length(removed) > 0L) {
        abort_okf_import(paste0("Removing OKF concept files is not supported; restore ", length(removed), " accepted concept(s) before planning."), removed_record_ids = sort(removed, method = "radix"))
    }
    changed_records <- list()
    for (record_id in sort(names(proposals), method = "radix")) {
        proposal <- proposals[[record_id]]
        base <- current[[record_id]]
        proposed_digest <- okf_public_record_digest(proposal$record)
        if (!is.null(base)) {
            declared_base <- proposal$base_digest
            if (is.na(declared_base) || !identical(declared_base, base$digest)) {
                abort_okf_import(paste0("Concept `", record_id, "` is not based on its current accepted revision."), record_id = record_id, expected_digest = base$digest, observed_digest = declared_base)
            }
            if (identical(proposed_digest, base$digest)) {
                next
            }
        }
        class_records <- changed_records[[proposal$class]]
        class_records[[length(class_records) + 1L]] <- proposal$record
        changed_records[[proposal$class]] <- class_records
    }
    base_batch_id <- if (is.na(status$expected_batch_id)) {
        ""
    }
    else {
        status$expected_batch_id
    }
    list(base_batch_id = base_batch_id, path = status$path, proposed_bundle_digest = snapshot$bundle_digest, records = okf_import_data_frames(store, changed_records))
}

