projection_coerce_exact_numbers.body:
{
    vapply(values, function(value) {
        if (is.null(value) || length(value) == 0L || is.na(value[[1L]])) {
            return(NA_character_)
        }
        item <- value[[1L]]
        if (is.character(item)) {
            return(item)
        }
        if (is.integer(item)) {
            return(as.character(item))
        }
        if (is.numeric(item) && length(item) == 1L && is.finite(item) && item == trunc(item) && abs(item) < 2^53) {
            return(sprintf("%.0f", item))
        }
        abort_backend_error(paste0("Cannot rebuild an exact ", type, " projection from a JSON number that may already have lost ", "precision. Encode ", type, " payload values as JSON strings."), operation = "rebuild_projections", duckdb_type = type, value = item)
    }, character(1))
}

projection_coerce_timestamps.body:
{
    present <- !is.na(text)
    canonical <- grepl(paste0("^[0-9]{4}-[0-9]{2}-[0-9]{2}T", "[0-9]{2}:[0-9]{2}:[0-9]{2}", "(\\.[0-9]{1,6})?Z$"), text)
    if (any(present & !canonical)) {
        abort_backend_error(paste0("Projection timestamps must use canonical UTC ISO-8601 syntax ", "with at most six fractional digits."), operation = "rebuild_projections", invalid_timestamps = unique(text[present & !canonical]))
    }
    result <- as.POSIXct(text, format = "%Y-%m-%dT%H:%M:%OSZ", tz = "UTC")
    if (any(present & is.na(result))) {
        abort_backend_error("Projection timestamps contain an invalid UTC date or time.", operation = "rebuild_projections", invalid_timestamps = unique(text[present & is.na(result)]))
    }
    result
}

projection_coerce_values.body:
{
    type <- safe_duckdb_type(type)
    if (identical(type, "BIGINT")) {
        return(projection_coerce_exact_numbers(values, type))
    }
    if (identical(type, "DECIMAL")) {
        return(projection_coerce_exact_numbers(values, type))
    }
    text <- projection_text_values(values)
    switch(type, BOOLEAN = as.logical(text), DOUBLE = as.numeric(text), DATE = as.Date(text), TIMESTAMP = projection_coerce_timestamps(text), text)
}

projection_data_digest.body:
{
    columns <- names(data)
    rows <- character(nrow(data))
    if (nrow(data) > 0L) {
        for (index in seq_len(nrow(data))) {
            values <- vapply(columns, function(column) {
                projection_encode_digest_value(data[[column]][[index]])
            }, character(1))
            rows[[index]] <- paste(values, collapse = "")
        }
    }
    rows <- sort(rows, method = "radix")
    payload <- paste0(projection_encode_digest_value(label), projection_encode_digest_value(paste(columns, collapse = "\n")), paste(rows, collapse = ""))
    paste0("sha256:", digest::digest(payload, algo = "sha256", serialize = FALSE))
}

projection_encode_digest_value.body:
{
    if (length(value) == 0L || is.na(value[[1L]])) {
        return("-1:")
    }
    value <- enc2utf8(as.character(value[[1L]]))
    paste0(nchar(value, type = "bytes"), ":", value)
}

projection_multivalue_rows.body:
{
    record_class <- scalar_character(relation$owner_class)
    slot_name <- scalar_character(relation$slot)
    slot <- schema$manifest$classes[[record_class]]$slots[[slot_name]]
    kind <- scalar_character(relation$kind)
    owner <- character()
    values <- list()
    positions <- numeric()
    recorded_at <- as.POSIXct(character(), origin = "1970-01-01", tz = "UTC")
    for (index in seq_along(payloads)) {
        items <- payloads[[index]][[slot_name]]
        if (is.null(items) || length(items) == 0L) {
            next
        }
        owner <- c(owner, rep(current$record_id[[index]], length(items)))
        values <- c(values, items)
        positions <- c(positions, seq_along(items))
        recorded_at <- c(recorded_at, rep(current$recorded_at[[index]], length(items)))
    }
    position <- if (scalar_logical(relation$ordered)) {
        positions
    }
    else {
        rep(NA_real_, length(owner))
    }
    coerced <- projection_coerce_values(values, scalar_character(slot$duckdb_type))
    if (identical(kind, "object")) {
        if (length(owner) == 0L) {
            return(data.frame(id = character(), subject = character(), object = character(), position = numeric(), created_at = as.POSIXct(numeric(), origin = "1970-01-01", tz = "UTC"), stringsAsFactors = FALSE))
        }
        return(data.frame(id = paste0(owner, "#", slot_name, ":", positions), subject = owner, object = coerced, position = position, created_at = recorded_at, stringsAsFactors = FALSE))
    }
    data.frame(owner_id = owner, position = position, value = coerced, stringsAsFactors = FALSE)
}

