register_schema_version.body:
{
    manifest <- schema$manifest
    fingerprints <- manifest$fingerprints
    build_digest <- scalar_character(fingerprints$build_digest)
    existing <- DBI::dbGetQuery(connection, paste0("SELECT manifest_json FROM ", quote_identifier(connection, "_graft_schema_versions"), " WHERE build_digest = ?"), params = list(build_digest))
    manifest_json <- canonical_manifest_json(manifest)
    if (nrow(existing) == 1L) {
        if (!identical(existing$manifest_json[[1L]], manifest_json)) {
            abort_backend_error("A schema build digest is registered with different manifest content.", operation = "register_schema_version", build_digest = build_digest)
        }
        return(invisible(schema))
    }
    if (nrow(existing) > 1L) {
        abort_backend_error("A schema build digest has multiple registry entries.", operation = "register_schema_version", build_digest = build_digest)
    }
    row <- data.frame(build_digest = build_digest, structural_digest = scalar_character(fingerprints$structural_digest), source_digest = scalar_character(fingerprints$source_digest), manifest_json = manifest_json, compiler_json = canonical_json(manifest$compiler), registered_at = as.POSIXct(now, tz = "UTC"), stringsAsFactors = FALSE)
    DBI::dbAppendTable(connection, "_graft_schema_versions", row)
    invisible(schema)
}

