resolve_candidate_identities.body:
{
    flattened <- flatten_candidate_identities(staged)
    candidates <- flattened$candidates
    identifiers <- flattened$identifiers
    issues <- flattened$issues
    if (nrow(candidates) == 0L) {
        return(list(staged = staged, identifiers = empty_candidate_identifiers(), origins = empty_candidate_origins(), issues = issues))
    }
    identifier_matches <- candidate_identifier_matches(identifiers, snapshot$identifiers)
    length(identifier_matches) <- nrow(candidates)
    origin_matches <- candidate_origin_matches(candidates, snapshot$origins, batch$producer)
    for (row in seq_len(nrow(candidates))) {
        external_ids <- unique(identifier_matches[[row]])
        origin_ids <- unique(origin_matches[[row]])
        supplied_id <- if (candidates$supplied_valid[[row]]) {
            candidates$supplied_id[[row]]
        }
        else {
            character()
        }
        if (length(external_ids) > 1L) {
            issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = candidate_identity_fields(identifiers, row), rule = "consistent_exact_identity", message = "Supplied external identifiers resolve to different records.")
        }
        if (length(supplied_id) == 1L && length(external_ids) > 0L && any(external_ids != supplied_id)) {
            issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = "id", rule = "internal_external_identity_agreement", message = "The supplied internal ID conflicts with an external identifier.")
        }
        if (length(origin_ids) > 1L) {
            issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = ".graft_origin_key", rule = "unique_origin", message = "The producer origin key resolves to multiple records.")
        }
        resolved_ids <- unique(c(supplied_id, external_ids))
        if (length(resolved_ids) == 1L && length(origin_ids) > 0L && any(origin_ids != resolved_ids)) {
            issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = ".graft_origin_key", rule = "origin_identity_agreement", message = "The producer origin conflicts with the resolved record ID.")
        }
    }
    parent <- seq_len(nrow(candidates))
    identity_groups <- split(identifiers$candidate_id, paste("identifier", identifiers$class, identifiers$namespace, identifiers$normalized_value, sep = "\037"))
    origin_present <- !is.na(candidates$origin_key)
    origin_groups <- split(candidates$candidate_id[origin_present], paste("origin", candidates$class[origin_present], batch$producer, candidates$origin_key[origin_present], sep = "\037"))
    for (group in c(identity_groups, origin_groups)) {
        if (length(group) < 2L) {
            next
        }
        for (candidate_id in group[-1L]) {
            parent <- union_candidate_components(parent, group[[1L]], candidate_id)
        }
    }
    component <- vapply(seq_len(nrow(candidates)), function(.x) candidate_component_root(parent, .x), integer(1))
    assigned <- rep(NA_character_, nrow(candidates))
    matched_by <- rep("new", nrow(candidates))
    identity_reason <- rep("unresolved", nrow(candidates))
    identity_evidence <- rep(canonical_json(list()), nrow(candidates))
    current_classes <- split(as.character(snapshot$current$class), as.character(snapshot$current$record_id))
    component_rows <- split(seq_len(nrow(candidates)), component)
    for (rows in component_rows) {
        known <- unique(c(candidates$supplied_id[rows][candidates$supplied_valid[rows]], unlist(identifier_matches[rows], use.names = FALSE), unlist(origin_matches[rows], use.names = FALSE)))
        known <- known[!is.na(known) & nzchar(known)]
        if (length(known) > 1L) {
            for (row in rows) {
                issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = candidate_identity_fields(identifiers, row), rule = "consistent_exact_identity", message = "Candidate identity evidence resolves to multiple records.")
            }
            next
        }
        if (length(known) == 1L) {
            assigned[rows] <- known[[1L]]
            evidence <- component_resolution_evidence(candidates, identifiers, snapshot$identifiers, snapshot$origins, rows, known[[1L]], batch$producer)
            reason <- resolution_evidence_reason(evidence)
            matched_by[rows] <- reason
            identity_reason[rows] <- reason
            identity_evidence[rows] <- canonical_json(evidence)
            next
        }
        record_class <- candidates$class[[rows[[1L]]]]
        contract <- manifest$classes[[record_class]]
        policy <- scalar_character(contract$id_policy)
        if (identical(policy, "require")) {
            for (row in rows) {
                issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = "id", rule = "required_internal_id", message = "This class requires a supplied internal ID.")
            }
            next
        }
        if (identical(policy, "deterministic") && any(vapply(rows, function(.x) candidate_deterministic_key_missing(staged, candidates, .x), logical(1)))) {
            for (row in rows) {
                issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = paste(empty_character(contract$origin_key_slots), collapse = ","), rule = "deterministic_key_complete", message = "Deterministic identity requires every configured key field.")
            }
            next
        }
        identifier_keys <- sort(unique(candidate_component_identifier_keys(identifiers, rows)), method = "radix")
        if (identical(policy, "deterministic")) {
            key_values <- candidate_deterministic_key_values(staged, candidates, rows[[1L]])
            seed <- list(deterministic_keys = key_values)
            reason <- "deterministic_key"
            evidence <- list(list(kind = reason, slots = names(key_values), value_digest = graft_sha256(canonical_json(key_values))))
        }
        else if (length(identifier_keys) > 0L) {
            seed <- list(exact_identifiers = identifier_keys)
            reason <- "exact_identifier_mint"
            evidence <- lapply(identifier_keys, function(.x) {
                list(kind = reason, key = .x)
            })
        }
        else {
            seed <- candidate_identity_seed(staged, candidates, rows[[1L]], batch$producer)
            reason <- "mint"
            evidence <- list(list(kind = reason, seed_digest = graft_sha256(canonical_json(seed))))
        }
        assigned[rows] <- deterministic_graft_id(record_class, seed)
        matched_by[rows] <- reason
        identity_reason[rows] <- reason
        identity_evidence[rows] <- canonical_json(evidence)
    }
    candidates$record_id <- assigned
    candidates$matched_by <- matched_by
    candidates$identity_reason <- identity_reason
    candidates$identity_evidence <- identity_evidence
    for (row in seq_len(nrow(candidates))) {
        record_id <- candidates$record_id[[row]]
        if (is.na(record_id)) {
            next
        }
        actual <- unique(current_classes[[record_id]])
        incompatible <- setdiff(actual, candidates$class[[row]])
        if (length(incompatible) > 0L) {
            issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = "id", rule = "class_compatible_id", message = paste0("Internal ID `", record_id, "` already belongs to another class."))
        }
    }
    duplicate_ids <- unique(assigned[!is.na(assigned) & duplicated(assigned)])
    for (record_id in duplicate_ids) {
        for (row in which(assigned == record_id)) {
            issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, row, field = "id", rule = "unique_batch_id", message = paste0("Internal ID `", record_id, "` occurs more than once."))
        }
    }
    mapped_identifiers <- map_candidate_identifiers(identifiers, assigned, snapshot$identifiers)
    identifier_keys <- paste(mapped_identifiers$class, mapped_identifiers$namespace, mapped_identifiers$normalized_value, sep = "\037")
    for (key in unique(identifier_keys)) {
        indexes <- which(identifier_keys == key)
        mapped <- unique(mapped_identifiers$record_id[indexes])
        mapped <- mapped[!is.na(mapped)]
        if (length(mapped) < 2L) {
            next
        }
        for (candidate_id in unique(mapped_identifiers$candidate_id[indexes])) {
            issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, candidate_id, field = paste(unique(mapped_identifiers$slot[indexes]), collapse = ","), rule = "unique_exact_identity", message = "An exact identifier maps to multiple candidate records.")
        }
    }
    origins <- map_candidate_origins(candidates, batch$producer)
    origin_keys <- paste(origins$class, origins$producer, origins$origin_key, sep = "\037")
    present_origins <- !is.na(origins$origin_key)
    for (key in unique(origin_keys[present_origins])) {
        indexes <- which(origin_keys == key)
        if (length(indexes) < 2L) {
            next
        }
        for (candidate_id in origins$candidate_id[indexes]) {
            issues[[length(issues) + 1L]] <- candidate_identity_issue(candidates, candidate_id, field = ".graft_origin_key", rule = "unique_batch_origin", message = "A producer origin key occurs more than once for a class.")
        }
    }
    for (row in seq_len(nrow(candidates))) {
        record_class <- candidates$class[[row]]
        input_row <- candidates$input_row[[row]]
        staged[[record_class]]$data$id[[input_row]] <- assigned[[row]]
        staged[[record_class]]$identities[[input_row]]$record_id <- assigned[[row]]
        staged[[record_class]]$identities[[input_row]]$matched_by <- matched_by[[row]]
        staged[[record_class]]$identities[[input_row]]$identity_reason <- identity_reason[[row]]
        staged[[record_class]]$identities[[input_row]]$identity_evidence <- identity_evidence[[row]]
        staged[[record_class]]$identities[[input_row]]$origin_key <- origins$origin_key[[row]]
    }
    list(staged = staged, identifiers = mapped_identifiers[c("record_id", "class", "input_row", "slot", "namespace", "value", "normalized_value", "status", "assigned_by")], origins = origins[c("record_id", "class", "input_row", "producer", "origin_key")], issues = issues)
}

