resolve_effective_history_boundary.body:
{
    if (!is_graft_snapshot_backend(store)) {
        return(resolve_history_boundary(store, as_of))
    }
    snapshot <- snapshot_backend_data(store)
    pinned <- list(commit_order = snapshot$commit_order, batch_id = snapshot$batch_id, committed_at = snapshot$committed_at)
    if (is.null(as_of)) {
        return(pinned)
    }
    if (inherits(as_of, "POSIXt") && snapshot$commit_order > 0) {
        requested_time <- validate_history_time(as_of, "as_of")
        pinned_time <- as.POSIXct(snapshot$committed_at, format = "%Y-%m-%dT%H:%M:%OSZ", tz = "UTC")
        if (requested_time > pinned_time) {
            abort_snapshot_error(c("graft_snapshot_boundary_error", "graft_history_boundary_error"), "The requested history boundary is later than the GraftView snapshot.", requested_as_of = as_of, snapshot_commit_order = snapshot$commit_order, snapshot_batch_id = snapshot$batch_id)
        }
    }
    boundary <- resolve_history_boundary(store, as_of)
    if (boundary$commit_order > snapshot$commit_order) {
        abort_snapshot_error(c("graft_snapshot_boundary_error", "graft_history_boundary_error"), "The requested history boundary is later than the GraftView snapshot.", requested_as_of = as_of, requested_commit_order = boundary$commit_order, snapshot_commit_order = snapshot$commit_order, snapshot_batch_id = snapshot$batch_id)
    }
    boundary
}

resolve_history_boundary.body:
{
    if (is.null(as_of)) {
        return(list(commit_order = NULL, batch_id = NULL, committed_at = NULL))
    }
    if (inherits(as_of, "POSIXt")) {
        time <- validate_history_time(as_of, "as_of")
        row <- with_duckdb_error("resolve_history_boundary", DBI::dbGetQuery(store$connection, paste0("SELECT batch_id, commit_order, committed_at FROM ", quote_identifier(store$connection, "_graft_batches"), " WHERE status = 'committed' AND committed_at <= ? ", "ORDER BY commit_order DESC, batch_id ASC LIMIT 1"), params = list(time)))
        if (nrow(row) == 0L) {
            return(list(commit_order = 0, batch_id = NA_character_, committed_at = time))
        }
        return(list(commit_order = as.numeric(row$commit_order[[1L]]), batch_id = row$batch_id[[1L]], committed_at = row$committed_at[[1L]]))
    }
    batch_id <- validate_scalar_text(as_of, "as_of")
    row <- with_duckdb_error("resolve_history_boundary", DBI::dbGetQuery(store$connection, paste0("SELECT batch_id, commit_order, committed_at, status FROM ", quote_identifier(store$connection, "_graft_batches"), " WHERE batch_id = ?"), params = list(batch_id)))
    if (nrow(row) != 1L || !identical(row$status[[1L]], "committed")) {
        graft_abort("graft_history_boundary_error", paste0("History boundary batch `", batch_id, "` does not identify exactly one committed batch."), batch_id = batch_id, observed_status = if (nrow(row) == 1L) 
            row$status[[1L]]
        else NA_character_)
    }
    list(commit_order = as.numeric(row$commit_order[[1L]]), batch_id = row$batch_id[[1L]], committed_at = row$committed_at[[1L]])
}

