schema_compatibility.body:
{
    if (!is_compiled_schema(old_schema) || !is_compiled_schema(new_schema)) {
        abort_schema_integrity("Schema compatibility requires two compiled schemas.")
    }
    old_manifest <- old_schema$manifest
    new_manifest <- new_schema$manifest
    old_digest <- scalar_character(old_manifest$fingerprints$structural_digest)
    new_digest <- scalar_character(new_manifest$fingerprints$structural_digest)
    digests_valid <- identical(old_digest, manifest_structural_digest(old_manifest)) && identical(new_digest, manifest_structural_digest(new_manifest))
    content_matches <- identical(manifest_structural_json(old_manifest), manifest_structural_json(new_manifest))
    compatible <- digests_valid && content_matches
    list(compatible = compatible, classification = if (compatible) {
        "compatible"
    } else if (!digests_valid) {
        "invalid structural digest"
    } else {
        "structural change"
    }, old_structural_digest = old_digest, new_structural_digest = new_digest)
}

schema_manifest_source_snapshot.body:
{
    connection <- tryCatch(file(path, open = "rb"), error = function(error) {
        abort_schema_error(paste0("Could not read schema manifest `", path, "`."), manifest_path = path, parent = error)
    })
    connection_open <- TRUE
    on.exit(if (connection_open) close(connection), add = TRUE)
    chunks <- list()
    repeat {
        chunk <- tryCatch(readBin(connection, what = "raw", n = 65536L), error = function(error) {
            abort_schema_error(paste0("Could not read schema manifest `", path, "`."), manifest_path = path, parent = error)
        })
        if (length(chunk) == 0L) {
            break
        }
        chunks[[length(chunks) + 1L]] <- chunk
    }
    close(connection)
    connection_open <- FALSE
    bytes <- if (length(chunks) == 0L) 
        raw()
    else do.call(c, chunks)
    text <- tryCatch(rawToChar(bytes), error = function(error) {
        abort_schema_error(paste0("Schema manifest `", path, "` is not valid text."), manifest_path = path, parent = error)
    })
    list(bytes = bytes, text = text)
}

