snapshot_graph_candidate_rows.body:
{
    connection <- store$connection
    specs <- snapshot_graph_edge_specs(store$schema, projection)
    parts <- vapply(specs, function(spec) snapshot_graph_edge_spec_sql(connection, spec), character(1))
    if (length(parts) == 0L) {
        parts <- snapshot_graph_empty_edge_candidates_sql()
    }
    placeholders <- paste(rep("?", length(frontier)), collapse = ", ")
    if (identical(direction, "out")) {
        incidence <- paste0("subject IN (", placeholders, ")")
        params <- as.list(frontier)
    }
    else if (identical(direction, "in")) {
        incidence <- paste0("object IN (", placeholders, ")")
        params <- as.list(frontier)
    }
    else {
        incidence <- paste0("(subject IN (", placeholders, ") OR object IN (", placeholders, "))")
        params <- c(as.list(frontier), as.list(frontier))
    }
    predicate_sql <- ""
    if (!is.null(predicate)) {
        predicate_sql <- " AND predicate = ?"
        params <- c(params, list(predicate))
    }
    retrieval_query(connection, paste0("WITH snapshot_current AS (", graft_read_source_sql(store), "), snapshot_edges AS (", paste(parts, collapse = " UNION ALL "), ") SELECT * FROM snapshot_edges WHERE ", incidence, predicate_sql, graph_edge_order_sql(), " LIMIT ", limit + 1L), params = params)
}

snapshot_graph_current_rows.body:
{
    if (missing(ids) || is.null(ids)) {
        abort_backend_error("Snapshot graph node retrieval requires a bounded ID scope.", operation = "snapshot_graph_retrieval")
    }
    classes <- unique(as.character(classes))
    ids <- unique(as.character(ids))
    if (length(classes) == 0L || length(ids) == 0L) {
        return(retrieval_query(store$connection, paste0("SELECT * FROM (", graft_read_source_sql(store), ") current WHERE FALSE")))
    }
    class_placeholders <- paste(rep("?", length(classes)), collapse = ", ")
    id_placeholders <- paste(rep("?", length(ids)), collapse = ", ")
    where <- paste0("current.class IN (", class_placeholders, ") AND current.record_id IN (", id_placeholders, ")")
    retrieval_query(store$connection, paste0("SELECT * FROM (", graft_read_source_sql(store), ") current WHERE ", where, " ORDER BY class, record_id, revision_id"), params = c(as.list(classes), as.list(ids)))
}

