{
    source <- paste0("current.record_id, current.class, current.revision_id, ", "current.revision_number, current.schema_build_digest, ", "current.payload_json, current.content_digest, current.recorded_at, ", "current.commit_order")
    class_sql <- graph_sql_string(connection, spec$record_class)
    if (identical(spec$kind, "about")) {
        array_pattern <- paste0("(?:\\{|,)", canonical_json(spec$object_slot), ":\\[(\"[^\"\\\\]*\"(?:,\"[^\"\\\\]*\")*)?\\]")
        value_pattern <- "\"([^\"\\\\]*)\""
        object <- "snapshot_about.object"
        edge_id <- paste0("CONCAT(current.record_id, '#about:', ", "CAST(snapshot_about.item_position AS VARCHAR), '#about')")
        subject <- "current.record_id"
        from <- paste0("snapshot_current current CROSS JOIN LATERAL (SELECT ", "UNNEST(snapshot_values.items) AS object, ", "generate_subscripts(snapshot_values.items, 1) AS item_position ", "FROM (SELECT regexp_extract_all(regexp_extract(", "current.payload_json, ", graph_sql_string(connection, array_pattern), ", 1), ", graph_sql_string(connection, value_pattern), ", 1) AS items) snapshot_values) snapshot_about")
    }
    else {
        object <- snapshot_graph_payload_scalar_sql(connection, spec$object_slot)
        owner <- snapshot_graph_payload_scalar_sql(connection, spec$edge_id_slot)
        edge_id <- if (is.null(spec$edge_kind)) {
            owner
        }
        else {
            paste0("CONCAT(", owner, ", ", graph_sql_string(connection, paste0("#", spec$edge_kind)), ")")
        }
        subject <- snapshot_graph_payload_scalar_sql(connection, spec$subject_slot)
        from <- "snapshot_current current"
    }
    predicate <- if (is.null(spec$predicate_slot)) {
