        predicate, " IS NOT NULL AND ", object, " IS NOT NULL")
}

snapshot_graph_edge_specs.body:
{
    manifest <- schema$manifest
    specs <- list()
    add_spec <- function(spec) {
        if (!is.null(spec)) {
            specs[[length(specs) + 1L]] <<- spec
        }
        invisible(NULL)
    }
    add_scalar <- function(record_class, subject_slot, object_slot, predicate, edge_class = "provenance", edge_owner_slot = subject_slot, edge_kind, source_table = NULL) {
        contract <- manifest$classes[[record_class]]
        required <- c(subject_slot, object_slot, edge_owner_slot)
        if (is.null(contract) || !all(required %in% names(contract$slots))) {
            return(invisible(NULL))
        }
        add_spec(list(kind = "scalar", record_class = record_class, edge_class = edge_class, source_table = if (is.null(source_table)) {
            scalar_character(contract$view)
        } else {
            source_table
        }, edge_id_slot = edge_owner_slot, edge_kind = edge_kind, subject_slot = subject_slot, predicate_slot = NULL, predicate_value = predicate, object_slot = object_slot))
    }
    if (projection %in% c("semantic", "combined")) {
        semantic <- manifest$graph_projections$semantic_edges
        direct <- empty_character(semantic$direct_edge_classes)
        if (length(direct) == 0L) {
            direct <- names(Filter(function(contract) identical(scalar_character(contract$role), "edge"), manifest$classes))
        }
        statements <- empty_character(semantic$semantic_statement_classes)
        if (length(statements) == 0L) {
            statements <- names(Filter(function(contract) {
                identical(scalar_character(contract$statement_shape), "semantic")
            }, manifest$classes))
        }
        for (record_class in sort(unique(direct), method = "radix")) {
            contract <- graph_projection_contract(schema, record_class, "semantic edges")
            fixed <- scalar_character(contract$fixed_predicate)
            add_spec(list(kind = "scalar", record_class = record_class, edge_class = record_class, source_table = scalar_character(contract$view), edge_id_slot = "id", edge_kind = NULL, subject_slot = "subject", predicate_slot = if (is.na(fixed)) "predicate" else NULL, predicate_value = if (is.na(fixed)) NULL else fixed, object_slot = "object"))
        }
        for (record_class in sort(unique(statements), method = "radix")) {
            contract <- graph_projection_contract(schema, record_class, "semantic edges")
            add_spec(list(kind = "scalar", record_class = record_class, edge_class = record_class, source_table = scalar_character(contract$view), edge_id_slot = "id", edge_kind = NULL, subject_slot = "subject", predicate_slot = "predicate", predicate_value = NULL, object_slot = "object_entity"))
        }
    }
    if (projection %in% c("provenance", "combined")) {
        provenance <- manifest$graph_projections$provenance_edges
        narrative <- empty_character(provenance$narrative_statement_classes)
        if (length(narrative) == 0L) {
            narrative <- names(Filter(function(contract) {
                identical(scalar_character(contract$statement_shape), "narrative")
            }, manifest$classes))
        }
        narrative_slots <- empty_character(provenance$narrative_slots)
        if (length(narrative_slots) == 0L) {
            narrative_slots <- c("about", "primary_subject")
        }
        if ("about" %in% narrative_slots) {
            relations <- Filter(function(relation) {
                scalar_character(relation$owner_class) %in% narrative && identical(scalar_character(relation$slot), "about") && identical(scalar_character(relation$kind), "object")
            }, manifest$relations)
            for (relation in relations) {
                add_spec(list(kind = "about", record_class = scalar_character(relation$owner_class), edge_class = "provenance", source_table = scalar_character(relation$view), edge_id_slot = NULL, edge_kind = "about", subject_slot = "id", predicate_slot = NULL, predicate_value = scalar_character(relation$predicate), object_slot = "about"))
            }
        }
        if ("primary_subject" %in% narrative_slots) {
            for (record_class in narrative) {
                contract <- manifest$classes[[record_class]]
                add_scalar(record_class, "id", "primary_subject", graph_slot_predicate(contract, "primary_subject"), edge_kind = "primary_subject")
            }
        }
        evidence <- graph_role_class_names(schema, "evidence")
        if (scalar_logical(provenance$statement_to_evidence, TRUE)) {
            for (record_class in evidence) {
                add_scalar(record_class, "statement_id", "id", graft_predicate_uri("evidence"), edge_owner_slot = "id", edge_kind = "statement_evidence")
            }
        }
        if (scalar_logical(provenance$evidence_to_source, TRUE)) {
            for (record_class in evidence) {
                contract <- manifest$classes[[record_class]]
                add_scalar(record_class, "id", "source_id", graph_slot_predicate(contract, "source_id"), edge_kind = "evidence_source")
            }
        }
        if (scalar_logical(provenance$supersession, TRUE)) {
            for (record_class in graph_role_class_names(schema, "statement")) {
                contract <- manifest$classes[[record_class]]
                add_scalar(record_class, "id", "superseded_by", graph_slot_predicate(contract, "superseded_by"), edge_kind = "superseded_by")
            }
        }
        if (scalar_logical(provenance$mention_resolution, TRUE)) {
            for (record_class in graph_role_class_names(schema, "mention")) {
                contract <- manifest$classes[[record_class]]
                add_scalar(record_class, "id", "entity_id", graph_slot_predicate(contract, "entity_id"), edge_kind = "mention_entity")
            }
        }
        if (scalar_logical(provenance$semantic_derivation, TRUE)) {
            semantic_classes <- names(Filter(function(contract) {
                identical(scalar_character(contract$statement_shape), "semantic")
            }, manifest$classes))
            for (record_class in semantic_classes) {
                contract <- manifest$classes[[record_class]]
                add_scalar(record_class, "id", "derived_from_statement", graph_slot_predicate(contract, "derived_from_statement"), edge_kind = "semantic_derivation")
            }
        }
    }
    specs
}

