    if (length(narrative) == 0L) {
        narrative <- names(Filter(function(contract) {
            identical(scalar_character(contract$statement_shape), "narrative")
        }, manifest$classes))
    }
    narrative_slots <- empty_character(projection$narrative_slots)
    if (length(narrative_slots) == 0L) {
        narrative_slots <- c("about", "primary_subject")
    }
    edges <- list()
    add_scalar <- function(index, subject_slot, object_slot, predicate, kind, owner_slot = subject_slot) {
        record <- current$record[[index]]
        contract <- manifest$classes[[current$class[[index]]]]
        required <- c(subject_slot, object_slot, owner_slot)
        if (!all(required %in% names(contract$slots))) {
            return(invisible(NULL))
        }
        subject <- snapshot_graph_scalar(record, subject_slot)
        object <- snapshot_graph_scalar(record, object_slot)
        owner <- snapshot_graph_scalar(record, owner_slot)
        if (is.na(subject) || is.na(object) || is.na(owner)) {
            return(invisible(NULL))
        }
        edges[[length(edges) + 1L]] <<- snapshot_graph_edge_row(edge_id = paste0(owner, "#", kind), subject = subject, predicate = predicate, object = object, edge_class = "provenance", source_table = scalar_character(contract$view), created_at = as.POSIXct(NA, tz = "UTC"))
        invisible(NULL)
    }
    if ("about" %in% narrative_slots) {
        relations <- Filter(function(relation) {
            scalar_character(relation$owner_class) %in% narrative && identical(scalar_character(relation$slot), "about") && identical(scalar_character(relation$kind), "object")
        }, manifest$relations)
        for (relation in relations) {
            record_class <- scalar_character(relation$owner_class)
            indexes <- which(current$class == record_class)
            for (index in indexes) {
                owner <- current$record_id[[index]]
                values <- snapshot_graph_values(current$record[[index]], "about")
                for (position in seq_along(values)) {
                  edges[[length(edges) + 1L]] <- snapshot_graph_edge_row(edge_id = paste0(owner, "#about:", position, "#about"), subject = owner, predicate = scalar_character(relation$predicate), object = values[[position]], edge_class = "provenance", source_table = scalar_character(relation$view), created_at = as.POSIXct(NA, tz = "UTC"))
                }
            }
        }
    }
    if ("primary_subject" %in% narrative_slots) {
        for (index in which(current$class %in% narrative)) {
            contract <- manifest$classes[[current$class[[index]]]]
            add_scalar(index, "id", "primary_subject", graph_slot_predicate(contract, "primary_subject"), "primary_subject")
        }
    }
    if (scalar_logical(projection$statement_to_evidence, TRUE)) {
        for (index in which(current$class %in% graph_role_class_names(schema, "evidence"))) {
            add_scalar(index, "statement_id", "id", graft_predicate_uri("evidence"), "statement_evidence", owner_slot = "id")
        }
    }
    if (scalar_logical(projection$evidence_to_source, TRUE)) {
        for (index in which(current$class %in% graph_role_class_names(schema, "evidence"))) {
            contract <- manifest$classes[[current$class[[index]]]]
            add_scalar(index, "id", "source_id", graph_slot_predicate(contract, "source_id"), "evidence_source")
        }
    }
    if (scalar_logical(projection$supersession, TRUE)) {
        for (index in which(current$class %in% graph_role_class_names(schema, "statement"))) {
            contract <- manifest$classes[[current$class[[index]]]]
            add_scalar(index, "id", "superseded_by", graph_slot_predicate(contract, "superseded_by"), "superseded_by")
        }
    }
    if (scalar_logical(projection$mention_resolution, TRUE)) {
        for (index in which(current$class %in% graph_role_class_names(schema, "mention"))) {
            contract <- manifest$classes[[current$class[[index]]]]
            add_scalar(index, "id", "entity_id", graph_slot_predicate(contract, "entity_id"), "mention_entity")
        }
    }
    if (scalar_logical(projection$semantic_derivation, TRUE)) {
        semantic <- names(Filter(function(contract) {
            identical(scalar_character(contract$statement_shape), "semantic")
        }, manifest$classes))
        for (index in which(current$class %in% semantic)) {
            contract <- manifest$classes[[current$class[[index]]]]
            add_scalar(index, "id", "derived_from_statement", graph_slot_predicate(contract, "derived_from_statement"), "semantic_derivation")
        }
    }
    snapshot_graph_bind_edges(edges)
}

