snapshot_identifier_registry.body:
{
    snapshot <- snapshot_backend_data(store)
    rows <- retrieval_query(store$connection, paste0("SELECT o.record_id, o.class, o.batch_id, o.revision_id, ", "o.observed_at, b.commit_order, ", "b.schema_build_digest AS observation_schema_build_digest, ", "r.schema_build_digest AS revision_schema_build_digest, ", "r.payload_json, r.content_digest FROM ", quote_identifier(store$connection, "_graft_record_observations"), " o INNER JOIN ", quote_identifier(store$connection, "_graft_batches"), " b ON o.batch_id = b.batch_id INNER JOIN ", quote_identifier(store$connection, 
        "_graft_record_revisions"), " r ON o.revision_id = r.revision_id AND o.record_id = r.record_id ", "AND o.class = r.class WHERE b.status = 'committed' ", "AND b.commit_order <= ? ORDER BY b.commit_order, o.class, ", "o.record_id, o.batch_id, o.revision_id"), params = list(snapshot$commit_order))
    if (nrow(rows) == 0L) {
        return(empty_snapshot_identifier_registry())
    }
    digests <- unique(c(rows$observation_schema_build_digest, rows$revision_schema_build_digest))
    schemas <- historical_schemas(store, digests)
    events <- list()
    for (index in seq_len(nrow(rows))) {
        record_class <- rows$class[[index]]
        revision_schema <- schemas[[rows$revision_schema_build_digest[[index]]]]
        revision_contract <- revision_schema$manifest$classes[[record_class]]
        observation_schema <- schemas[[rows$observation_schema_build_digest[[index]]]]
        observation_contract <- observation_schema$manifest$classes[[record_class]]
        if (is.null(revision_contract) || is.null(observation_contract)) {
            abort_snapshot_error("graft_snapshot_schema_error", "An observed identifier class is absent from its historical contract.", record_id = rows$record_id[[index]], record_class = record_class, revision_id = rows$revision_id[[index]])
        }
        validated_public_revision_record(rows$payload_json[[index]], rows$content_digest[[index]], revision_contract, record_id = rows$record_id[[index]], revision_id = rows$revision_id[[index]])
        payload <- parse_revision_payload(rows$payload_json[[index]])
        identifiers <- external_identifiers_for_row(observation_contract, payload)$identifiers
        if (length(identifiers) == 0L) {
            next
        }
        for (identifier in identifiers) {
            if (is.na(identifier$normalized_value) || !nzchar(identifier$normalized_value)) {
                next
            }
            events[[length(events) + 1L]] <- data.frame(record_id = rows$record_id[[index]], class = record_class, namespace = identifier$namespace, value = identifier$value, normalized_value = identifier$normalized_value, slot = identifier$slot, commit_order = as.numeric(rows$commit_order[[index]]), batch_id = rows$batch_id[[index]], created_at = as.POSIXct(rows$observed_at[[index]], tz = "UTC"), stringsAsFactors = FALSE)
        }
    }
    if (length(events) == 0L) {
        return(empty_snapshot_identifier_registry())
    }
    events <- dplyr::bind_rows(events)
    events <- events[order(events$commit_order, events$class, events$record_id, events$namespace, events$normalized_value, events$slot, events$batch_id, method = "radix"), , drop = FALSE]
    identifier_key <- paste(events$class, events$namespace, events$normalized_value, sep = "\037")
    owners <- split(events$record_id, identifier_key)
    conflicts <- names(Filter(function(ids) length(unique(ids)) > 1L, owners))
    if (length(conflicts) > 0L) {
        conflict <- conflicts[[1L]]
        parts <- strsplit(conflict, "\037", fixed = TRUE)[[1L]]
        abort_identity_error("A snapshot identifier maps to multiple records.", record_class = parts[[1L]], namespace = parts[[2L]], normalized_value = parts[[3L]], matched_record_ids = unique(owners[[conflict]]), rule = "unique_active_identifier")
    }
    record_key <- paste(events$class, events$record_id, sep = "\037")
    primary_index <- !duplicated(record_key)
    primary <- stats::setNames(identifier_key[primary_index], record_key[primary_index])
    events$status <- ifelse(identifier_key == unname(primary[record_key]), "primary", "equivalent")
    latest <- !duplicated(identifier_key, fromLast = TRUE)
    events <- events[latest, , drop = FALSE]
    result <- data.frame(record_id = events$record_id, class = events$class, namespace = events$namespace, value = events$value, normalized_value = events$normalized_value, status = events$status, assigned_by = rep("authoritative", nrow(events)), confidence = rep(1, nrow(events)), created_at = events$created_at, stringsAsFactors = FALSE)
    rownames(result) <- NULL
    result
}

