validate_candidate_class.body:
{
    issues <- list()
    for (slot_name in names(staged$contract$slots)) {
        slot <- staged$contract$slots[[slot_name]]
        for (index in seq_len(nrow(staged$data))) {
            if (candidate_field_key(index, slot_name) %in% staged$invalid_fields) {
                next
            }
            value <- staged$data[[slot_name]][[index]]
            missing <- is_missing_value(value, multivalued = scalar_logical(slot$multivalued))
            if (scalar_logical(slot$required) && missing && !identical(slot_name, "id")) {
                issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = staged$data$id[[index]], field = slot_name, rule = "required", message = paste0("Required field `", staged$class, ".", slot_name, "` is missing."))
                next
            }
            if (missing) {
                next
            }
            if (anyNA(value)) {
                issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = staged$data$id[[index]], field = slot_name, rule = "non_missing_collection_values", message = paste0("Field `", staged$class, ".", slot_name, "` contains a missing collection value."))
                next
            }
            issues <- c(issues, validate_candidate_constraints(manifest, staged, slot, value, index))
        }
    }
    issues <- c(issues, validate_candidate_invariants(staged))
    if (identical(staged$class, graft_definition_class_name)) {
        issues <- c(issues, validate_definition_candidates(manifest, staged, snapshot$current, connection))
    }
    list(staged = staged, issues = issues)
}

validate_candidate_constraints.body:
{
    issues <- list()
    slot_name <- scalar_character(slot$name)
    fixed_predicate <- scalar_character(staged$contract$fixed_predicate)
    if (identical(slot_name, "predicate") && !is.na(fixed_predicate) && any(as.character(value) != fixed_predicate)) {
        issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = staged$data$id[[index]], field = slot_name, rule = "fixed_predicate", message = paste0("Field `", staged$class, ".predicate` must equal its fixed predicate `", fixed_predicate, "`."))
    }
    enum_name <- scalar_character(slot$enum)
    if (!is.na(enum_name)) {
        allowed <- vapply(manifest$enums[[enum_name]]$permissible_values, function(.x) scalar_character(.x$value), character(1))
        if (length(setdiff(as.character(value), allowed)) > 0L) {
            issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = staged$data$id[[index]], field = slot_name, rule = "enum_membership", message = paste0("Field `", staged$class, ".", slot_name, "` has an unknown value."))
        }
    }
    pattern <- scalar_character(slot$pattern)
    if (!is.na(pattern) && !all(grepl(pattern, as.character(value)))) {
        issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = staged$data$id[[index]], field = slot_name, rule = "pattern", message = paste0("Field `", staged$class, ".", slot_name, "` does not match its pattern."))
    }
    numeric_value <- suppressWarnings(as.numeric(value))
    if (!is.null(slot$minimum_value) && any(numeric_value < as.numeric(slot$minimum_value), na.rm = TRUE)) {
        issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = staged$data$id[[index]], field = slot_name, rule = "minimum_value", message = paste0("Field `", staged$class, ".", slot_name, "` is below its bound."))
    }
    if (!is.null(slot$maximum_value) && any(numeric_value > as.numeric(slot$maximum_value), na.rm = TRUE)) {
        issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = staged$data$id[[index]], field = slot_name, rule = "maximum_value", message = paste0("Field `", staged$class, ".", slot_name, "` is above its bound."))
    }
    issues
}

validate_candidate_invariants.body:
{
    issues <- list()
    data <- staged$data
    is_statement <- identical(scalar_character(staged$contract$role), "statement")
    for (index in seq_len(nrow(data))) {
        if (is_statement && all(c("valid_from", "valid_to") %in% names(data))) {
            from <- data$valid_from[[index]]
            to <- data$valid_to[[index]]
            if (!is.na(from) && !is.na(to) && from > to) {
                issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = data$id[[index]], field = "valid_from,valid_to", rule = "valid_time_order", message = "`valid_from` must be before or equal to `valid_to`.")
            }
        }
        if (identical(scalar_character(staged$contract$statement_shape), "semantic")) {
            entity <- data$object_entity[[index]]
            value <- data$object_value[[index]]
            if (sum(c(!is_missing_value(entity), !is_missing_value(value))) != 1L) {
                issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = data$id[[index]], field = "object_entity,object_value", rule = "exactly_one_semantic_object", message = "A semantic statement must have exactly one object field.")
            }
            if (!is_missing_value(value) && is_missing_value(data$object_datatype[[index]])) {
                issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = data$id[[index]], field = "object_datatype", rule = "semantic_literal_datatype", message = "A semantic literal object requires `object_datatype`.")
            }
        }
        if (is_statement && "superseded_by" %in% names(data)) {
            target <- data$superseded_by[[index]]
            if (!is.na(target) && identical(target, data$id[[index]])) {
                issues[[length(issues) + 1L]] <- new_plan_issue(record_class = staged$class, input_row = index, record_id = data$id[[index]], field = "superseded_by", rule = "no_self_supersession", message = "A statement may not supersede itself.")
            }
        }
    }
    issues
}

validate_candidate_references.body:
{
    issues <- list()
    rows <- list()
    staged_classes <- list()
    for (record_class in names(staged)) {
        ids <- staged[[record_class]]$data$id
        for (record_id in unique(ids[!is.na(ids)])) {
            staged_classes[[record_id]] <- unique(c(staged_classes[[record_id]], record_class))
        }
    }
    available <- snapshot$current$operation != "delete"
    current_classes <- split(as.character(snapshot$current$class[available]), as.character(snapshot$current$record_id[available]))
    for (record_class in names(staged)) {
        class_staged <- staged[[record_class]]
        reference_slots <- Filter(function(.x) scalar_logical(.x$object_reference), class_staged$contract$slots)
        for (slot_name in names(reference_slots)) {
            slot <- reference_slots[[slot_name]]
            expected <- scalar_character(slot$range)
            for (index in seq_len(nrow(class_staged$data))) {
                targets <- class_staged$data[[slot_name]][[index]]
                if (is_missing_value(targets, multivalued = TRUE)) {
                  next
                }
                targets <- as.character(targets)
                if (!scalar_logical(slot$ordered) && anyDuplicated(targets)) {
                  issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, input_row = index, record_id = class_staged$data$id[[index]], field = slot_name, rule = "unique_relation_target", message = paste0("Unordered relation `", record_class, ".", slot_name, "` has a duplicate target."))
                }
                for (position in seq_along(targets)) {
                  target <- targets[[position]]
                  actual <- unique(c(staged_classes[[target]], current_classes[[target]]))
                  format <- reference_id_format(manifest, expected)
                  if (!valid_reference_id(target, format)) {
                    issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, input_row = index, record_id = class_staged$data$id[[index]], field = slot_name, rule = "internal_reference_id", message = paste0("Reference `", target, "` has an invalid identifier format."), condition_class = "graft_reference_error")
                  }
                  else if (length(actual) == 0L) {
                    issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, input_row = index, record_id = class_staged$data$id[[index]], field = slot_name, rule = "reference_exists", message = paste0("Reference target `", target, "` does not exist."), condition_class = "graft_reference_error")
                  }
                  else if (!any(vapply(actual, function(.x) reference_class_compatible(manifest, expected, .x), logical(1)))) {
                    issues[[length(issues) + 1L]] <- new_plan_issue(record_class = record_class, input_row = index, record_id = class_staged$data$id[[index]], field = slot_name, rule = "reference_class", message = paste0("Reference target `", target, "` is not compatible with `", expected, "`."), condition_class = "graft_reference_error")
                  }
                  rows[[length(rows) + 1L]] <- data.frame(class = record_class, input_row = as.integer(index), record_id = scalar_character(class_staged$data$id[[index]], ""), field = slot_name, target_id = target, expected_class = expected, position = as.integer(position), stringsAsFactors = FALSE)
                }
            }
        }
    }
    references <- if (length(rows) == 0L) {
        empty_candidate_references()
    }
    else {
        do.call(rbind, rows)
    }
    list(references = references, issues = issues)
}

validate_candidate_stages.body:
{
    issues <- list()
