validate_commit_plan_heads.body:
{
    if (nrow(heads) == 0L) {
        return(invisible(heads))
    }
    placeholders <- paste(rep("?", nrow(heads)), collapse = ", ")
    current_heads <- DBI::dbGetQuery(store$connection, paste0("SELECT h.record_id, h.class, h.revision_id, h.revision_number, ", "r.record_id AS ledger_record_id, r.class AS ledger_class, ", "r.revision_id AS ledger_revision_id, ", "r.revision_number AS ledger_revision_number, r.content_digest FROM ", quote_identifier(store$connection, "_graft_record_heads"), " AS h LEFT JOIN ", quote_identifier(store$connection, "_graft_record_revisions"), " AS r ON r.record_id = h.record_id AND r.class = h.class ", 
        "AND r.revision_id = h.revision_id ", "AND r.revision_number = h.revision_number ", "WHERE h.record_id IN (", placeholders, ")"), params = as.list(heads$record_id))
    current_index <- match(heads$record_id, current_heads$record_id)
    for (index in seq_len(nrow(heads))) {
        current_row <- current_index[[index]]
        current_revision <- if (is.na(current_row)) {
            NA_character_
        }
        else {
            current_heads$revision_id[[current_row]]
        }
        current_digest <- if (is.na(current_row)) {
            NA_character_
        }
        else {
            current_heads$content_digest[[current_row]]
        }
        current_class <- if (is.na(current_row)) {
            NA_character_
        }
        else {
            current_heads$class[[current_row]]
        }
        current_number <- if (is.na(current_row)) {
            NA_real_
        }
        else {
            as.numeric(current_heads$revision_number[[current_row]])
        }
        dangling <- !is.na(current_row) && (is.na(current_heads$ledger_revision_id[[current_row]]) || !identical(current_heads$ledger_record_id[[current_row]], current_heads$record_id[[current_row]]) || !identical(current_heads$ledger_class[[current_row]], current_heads$class[[current_row]]) || !identical(current_heads$ledger_revision_id[[current_row]], current_heads$revision_id[[current_row]]) || !identical(as.numeric(current_heads$ledger_revision_number[[current_row]]), current_number))
        expected_revision <- heads$expected_revision_id[[index]]
        expected_number <- as.numeric(heads$expected_revision_number[[index]])
        expected_exists <- !is.na(expected_revision)
        observed_exists <- !is.na(current_row)
        changed <- expected_exists != observed_exists || expected_exists && observed_exists && (!identical(current_class, heads$class[[index]]) || !identical(current_revision, expected_revision) || !identical(current_number, expected_number) || !identical(current_digest, heads$expected_content_digest[[index]]) || dangling)
        if (changed) {
            abort_commit_plan("graft_commit_plan_stale", paste0("Record `", heads$record_id[[index]], "` changed after planning."), record_id = heads$record_id[[index]], record_class = heads$class[[index]], expected_revision_id = expected_revision, observed_revision_id = current_revision, expected_revision_number = expected_number, observed_revision_number = current_number, dangling_head = dangling)
        }
    }
    invisible(heads)
}

validate_commit_plan_registries.body:
{
