validate_compiler_slot_type.body:
{
    range <- scalar_character(slot$range)
    object_reference <- scalar_logical(slot$object_reference)
    datetime_format <- scalar_character(slot$datetime_format)
    valid_datetime_format <- if (identical(range, "datetime")) {
        is.na(datetime_format) || datetime_format %in% c("offset", "local_utc")
    }
    else {
        is.na(datetime_format)
    }
    if (!valid_datetime_format) {
        abort_schema_integrity("Datetime input metadata does not match the slot range.", record_class = record_class, slot = slot_name, range = range, datetime_format = datetime_format, rule = "datetime_format_contract", subclass = subclass)
    }
    primitive_types <- manifest_primitive_duckdb_types()
    enum <- scalar_character(slot$enum)
    expected <- if (object_reference || (!is.na(enum) && identical(enum, range))) {
        "VARCHAR"
    }
    else if (!is.na(range) && range %in% names(primitive_types)) {
        unname(primitive_types[[range]])
    }
    else {
        abort_schema_integrity("A slot range must resolve to a supported primitive, enum, or class.", record_class = record_class, slot = slot_name, range = range, rule = "slot_range_contract", subclass = subclass)
    }
    observed <- scalar_character(slot$duckdb_type)
    if (!identical(observed, expected)) {
        qualified <- if (is.null(record_class)) {
            slot_name
        }
        else {
            paste(record_class, slot_name, sep = ".")
        }
        abort_schema_integrity(paste0(if (object_reference) 
            "Object-reference slot `"
        else "Slot `", qualified, "` must use DuckDB type `", expected, "`."), record_class = record_class, slot = slot_name, range = range, observed_type = observed, expected_type = expected, rule = if (object_reference) {
            "object_reference_varchar"
        }
        else {
            "slot_duckdb_type_contract"
        }, subclass = subclass)
    }
    invisible(slot)
}

validate_data_dict_graft_yaml.body:
{
    source <- tryCatch(yaml::yaml.load(text, eval.expr = FALSE), error = function(error) NULL)
    if (!is.list(source) || !is.list(source$tables)) {
        return(invisible(source))
    }
    for (table_index in seq_along(source$tables)) {
        table <- source$tables[[table_index]]
        if (!is.list(table) || !is.list(table$columns)) {
            next
        }
        for (column_index in seq_along(table$columns)) {
            column <- table$columns[[column_index]]
            if (is.list(column) && data_dict_is_scalar_text(column$type)) {
                next
            }
            field <- paste0("tables[", table_index, "].columns[", column_index, "].type")
            abort_schema_error(paste0("The graft-table-v1 profile requires every declared data-dict ", "column to have a type; `export-spec` omits untyped columns."), schema_path = path, field = field, rule = "typed_columns")
        }
    }
    invisible(source)
}

validate_data_dict_json_numbers.body:
{
    data_dict_reject_unsafe_json_numbers(document)
    tokens <- data_dict_json_number_tokens(text)
    unsafe <- which(vapply(tokens, function(token) data_dict_json_number_exceeds_safe_magnitude(token$value), logical(1)))
    if (length(unsafe) > 0L) {
        token <- tokens[[unsafe[[1L]]]]
        data_dict_abort(paste(paste0("The ", subject, " contains a JSON numeric token that cannot"), "cross the R boundary safely; use a quoted string contract instead."), field = "$", rule = "unsafe_json_number", schema_path = path, character_offset = token$offset)
    }
    invisible(document)
}

validate_data_dict_projection_contract.body:
{
    dictionary <- manifest$dictionary
    document <- dictionary$document
    schema <- manifest$schema
    if (!is.list(schema) || is.object(schema)) {
        abort_schema_error("The data-dict source identity must be an object.", manifest_path = path, field = "schema", rule = "dictionary_projection_contract")
    }
    source_files <- schema$source_files
    source_file <- if (is.list(source_files) && length(source_files) == 1L && is.list(source_files[[1L]]) && !is.object(source_files[[1L]])) {
        source_files[[1L]]
    }
    else {
        NULL
    }
    if (is.null(source_file)) {
        abort_schema_error("A data-dict manifest must contain one source-file object.", manifest_path = path, field = "schema.source_files", rule = "dictionary_projection_contract")
    }
    source <- tryCatch(data_dict_manifest_source(document, source_file$content_digest), graft_schema_error = function(error) {
        abort_schema_error(paste0("The data-dict source identity is invalid: ", conditionMessage(error)), manifest_path = path, field = "schema", rule = "dictionary_projection_contract", parent = error)
    })
    expected_schema <- list(id = source$id, name = source$name, version = source$version, source_files = list(list(schema_id = source$id, name = source$name, version = source$version, content_digest = source$content_digest, root = TRUE)))
    if (!identical(schema, expected_schema)) {
        abort_schema_error("The data-dict source identity does not match its public document.", manifest_path = path, field = "schema", rule = "dictionary_projection_contract")
    }
    expected_source_digest <- data_dict_manifest_source_digest(document, source)
    if (!identical(manifest$fingerprints$source_digest, expected_source_digest)) {
        abort_schema_error("The data-dict source digest does not match its public contract.", manifest_path = path, field = "fingerprints.source_digest", rule = "source_digest_content_mismatch")
    }
    compiled <- tryCatch(data_dict_compile_tables(document, source), graft_schema_error = function(error) {
        abort_schema_error(paste0("The public data-dict document cannot reproduce its contract: ", conditionMessage(error)), manifest_path = path, field = "dictionary.document", rule = "dictionary_projection_contract", parent = error)
    })
    expected_dictionary <- data_dict_dictionary_contract(document, manifest$compiler$provider, compiled)
    expected_projection <- list(classes = compiled$classes, slots = compiled$slots, enums = compiled$enums, relations = compiled$relations, graph_projections = data_dict_graph_projections(compiled$classes, compiled$relations), validation_invariants = list(), identifier_normalization_versions = stats::setNames(list(), character()))
    observed_projection <- manifest[names(expected_projection)]
    observed_projection$classes[[graft_definition_class_name]] <- NULL
    if (!identical(dictionary, expected_dictionary) || !identical(observed_projection, expected_projection)) {
        abort_schema_error(paste("The data-dict extension does not reproduce the manifest's compiled", "projection."), manifest_path = path, field = "dictionary", rule = "dictionary_projection_contract")
    }
    invisible(manifest)
}

validate_data_dict_provider_header.body:
{
    allowed <- c("name", "export_format_version", "source_spec_version", "cli_version", "cli_digest", "revision", "source_format")
    if (!is.list(provider) || is.object(provider) || !all(c("name", "export_format_version") %in% names(provider)) || length(setdiff(names(provider), allowed)) > 0L || !identical(provider$name, "data-dict") || !is_nonempty_string(provider$export_format_version) || (!is.null(provider$source_spec_version) && !is_optional_string(provider$source_spec_version)) || (!is.null(provider$cli_version) && !is_optional_string(provider$cli_version)) || (!is.null(provider$revision) && !is_optional_string(provider$revision)) || 
        (!is.null(provider$cli_digest) && !is_graft_digest(provider$cli_digest)) || (!is.null(provider$source_format) && !provider$source_format %in% c("yaml", "resolved_json"))) {
        abort_schema_error("The data-dict provider metadata is invalid.", manifest_path = path, field = "compiler.provider", rule = "dictionary_provider_contract")
    }
    yaml_provider <- identical(provider$source_format, "yaml") && is_nonempty_string(provider$source_spec_version) && is_nonempty_string(provider$cli_version) && is_graft_digest(provider$cli_digest)
    resolved_provider <- identical(provider$source_format, "resolved_json") && is.null(provider$source_spec_version) && is.null(provider$cli_version) && is.null(provider$cli_digest)
    if (!yaml_provider && !resolved_provider) {
        abort_schema_error("The data-dict provider metadata is inconsistent with its source format.", manifest_path = path, field = "compiler.provider", rule = "dictionary_provider_source_format")
    }
    if (!identical(provider$export_format_version, data_dict_export_format_version)) {
        abort_schema_error(paste0("The data-dict export-format version `", provider$export_format_version, "` is not supported."), manifest_path = path, field = "compiler.provider.export_format_version", rule = "supported_data_dict_export_format_version", observed_value = provider$export_format_version, supported_value = data_dict_export_format_version)
    }
    invisible(provider)
}

validate_definition_candidates.body:
{
    issues <- list()
    data <- staged$data
    accepted <- definition_current_records(current)
    accepted <- accepted[!accepted$id %in% data$id, , drop = FALSE]
    candidates <- data.frame(id = as.character(data$id), name = as.character(data$name), target = as.character(data$target), expr = as.character(data$expr), input_row = seq_len(nrow(data)), candidate = TRUE, stringsAsFactors = FALSE)
    definitions <- dplyr::bind_rows(accepted, candidates)
    add_issue <- function(index, field, rule, message) {
        issues[[length(issues) + 1L]] <<- new_plan_issue(record_class = staged$class, input_row = index, record_id = scalar_character(data$id[[index]]), field = field, rule = rule, message = message)
    }
    for (index in seq_len(nrow(data))) {
        target <- scalar_character(data$target[[index]])
        contract <- definition_target_contract_or_null(manifest, target)
        if (is.na(target) || is.null(contract)) {
            if (!is.na(target)) {
                add_issue(index, "target", "definition_target", paste0("`", target, "` is not a public definition target."))
            }
            next
        }
        columns <- definition_public_scalar_columns(contract)
        name <- scalar_character(data$name[[index]])
        if (!is.na(name) && name %in% columns) {
            add_issue(index, "name", "definition_column_shadow", paste0("Definition `", name, "` shadows a column of `", target, "`."))
        }
        local_names <- as.character(definitions$name[definitions$target == target])
        expr <- scalar_character(data$expr[[index]])
        if (!is.na(expr)) {
            checked <- definition_expr_analyze(expr, columns, local_names)
            for (row in seq_len(nrow(checked$issues))) {
                add_issue(index, "expr", checked$issues$rule[[row]], checked$issues$message[[row]])
            }
        }
    }
    keys <- paste(definitions$target, definitions$name, sep = "\r")
    duplicate_keys <- unique(keys[duplicated(keys)])
    for (index in seq_len(nrow(data))) {
        if (paste(data$target[[index]], data$name[[index]], sep = "\r") %in% duplicate_keys) {
            add_issue(index, "name", "definition_name_unique", "Definition names must be unique within a public table.")
        }
    }
    for (target in unique(as.character(definitions$target))) {
        contract <- definition_target_contract_or_null(manifest, target)
        if (is.null(contract)) {
            next
        }
        target_rows <- definitions[definitions$target == target & !keys %in% duplicate_keys, , drop = FALSE]
        definition_names <- as.character(target_rows$name)
        graph <- stats::setNames(vector("list", nrow(target_rows)), definition_names)
        columns <- definition_public_scalar_columns(contract)
        for (position in seq_len(nrow(target_rows))) {
            analysis <- definition_expr_analyze(scalar_character(target_rows$expr[[position]]), columns, definition_names)
            graph[[position]] <- analysis$dependencies
        }
        cycle_names <- definition_cycle_members(graph)
        for (name in cycle_names) {
            indices <- which(data$target == target & data$name == name)
            for (index in indices) {
                add_issue(index, "expr", "definition_cycle", paste0("Definition `", name, "` participates in a dependency cycle."))
            }
        }
        direct_selections <- stats::setNames(vapply(seq_len(nrow(target_rows)), function(position) {
            analysis <- definition_expr_analyze(scalar_character(target_rows$expr[[position]]), columns, definition_names)
            as.integer(analysis$has_selection)
        }, integer(1)), definition_names)
        selection_counts <- stats::setNames(rep(NA_integer_, length(definition_names)), definition_names)
        selection_count <- function(name, active = character()) {
            if (name %in% active) {
                return(NA_integer_)
            }
            if (!is.na(selection_counts[[name]])) {
                return(selection_counts[[name]])
            }
            dependencies <- vapply(graph[[name]], function(dependency) selection_count(dependency, c(active, name)), integer(1))
            if (anyNA(dependencies)) {
                return(NA_integer_)
            }
            selection_counts[[name]] <<- direct_selections[[name]] + sum(dependencies)
            selection_counts[[name]]
        }
        for (name in definition_names) {
            selection_count(name)
        }
        invalid_selection_names <- names(selection_counts)[!is.na(selection_counts) & selection_counts > 1L]
        for (name in invalid_selection_names) {
            indices <- which(data$target == target & data$name == name)
            for (index in indices) {
                add_issue(index, "expr", "definition_expr_selection", paste0("Definition `", name, "` recursively uses more than one `COLUMNS()` selection."))
            }
        }
        invalid_names <- c(cycle_names, invalid_selection_names)
        candidate_rows <- which(target_rows$candidate & !target_rows$name %in% invalid_names)
        if (length(candidate_rows) == 0L) {
            next
        }
        catalog <- target_rows
        compiler <- new.env(parent = emptyenv())
        compiler$catalog <- catalog
        compiler$columns <- columns
        compiler$target <- target
        compiler$compiled <- list()
        compiler$active <- character()
        source_sql <- definition_empty_source_sql(connection, contract)
        validation_rows <- which(!target_rows$name %in% invalid_names)
        for (position in validation_rows) {
            candidate_index <- if (target_rows$candidate[[position]]) {
                target_rows$input_row[[position]]
            }
            else {
                target_rows$input_row[[candidate_rows[[1L]]]]
            }
            basic <- definition_expr_analyze(target_rows$expr[[position]], columns, definition_names)
            if (nrow(basic$issues) > 0L) {
                next
            }
            error <- tryCatch({
                compiled <- definition_compile_row(target_rows[position, , drop = FALSE], compiler)
                type <- definition_describe_sql(connection, compiled$sql, source_sql)
                if (selection_counts[[target_rows$name[[position]]]] > 0L && !grepl("^BOOLEAN", toupper(type))) {
                  rlang::abort("A `COLUMNS()` selection must produce a filter.")
                }
                NULL
            }, error = identity)
            if (!is.null(error)) {
                add_issue(candidate_index, "expr", "definition_expr_type", paste0("Definition `", target_rows$name[[position]], "` does not type-check for `", target, "`."))
            }
        }
    }
    issues
}

validate_duckdb_connection.body:
{
    if (!inherits(connection, "DBIConnection") || !inherits(connection, "duckdb_connection")) {
        abort_backend_error("`connection` must be a DuckDB DBI connection.", operation = "connect", argument = "connection")
    }
    if (!isTRUE(tryCatch(DBI::dbIsValid(connection), error = function(.x) FALSE))) {
        abort_backend_error("`connection` is closed or invalid.", operation = "connect", argument = "connection")
    }
    invisible(connection)
}

validate_global_slot_types.body:
{
    for (slot_name in names(manifest$slots)) {
        validate_compiler_slot_type(manifest$slots[[slot_name]], slot_name = slot_name, subclass = subclass)
    }
    invisible(manifest)
}

validate_graft_commit_plan.body:
{
    if (!S7::S7_inherits(plan, GraftCommitPlan)) {
        abort_commit_plan("graft_commit_plan_invalid", "`plan` must be a GraftCommitPlan object.", argument = "plan")
    }
    data <- commit_plan_data(plan)
    if (!is.list(data) || !identical(names(data), commit_plan_field_names())) {
        abort_commit_plan("graft_commit_plan_tampered", "The commit plan structure is invalid; create and review a new plan.")
    }
    as_graft_provenance(data$provenance, "plan@provenance")
    execution_digest <- tryCatch(graft_sha256(canonical_json(commit_plan_execution(plan))), error = function(error) NA_character_)
    expected_digest <- tryCatch(graft_sha256(canonical_json(commit_plan_digest_data(data))), error = function(error) NA_character_)
    expected_id <- if (is_graft_digest(expected_digest)) {
        deterministic_graft_id("GraftCommitPlan", list(plan_digest = expected_digest))
    }
    else {
        NA_character_
    }
    if (!identical(execution_digest, data$execution_digest) || !identical(expected_digest, data$plan_digest) || !identical(expected_id, data$plan_id)) {
        abort_commit_plan("graft_commit_plan_tampered", "The commit plan digest is invalid; create and review a new plan.", expected_digest = expected_digest, observed_digest = data$plan_digest)
    }
    plan
}

validate_graft_evidence_support_type.body:
{
    slot <- contract$slots$support_type
    enum <- scalar_character(slot$enum)
    if (is.na(enum)) {
        return(invisible(support_type))
    }
    allowed <- vapply(store$schema$manifest$enums[[enum]]$permissible_values, function(.x) scalar_character(.x$value), character(1))
    if (!support_type %in% allowed) {
        abort_validation_error(paste0("Unknown evidence support type `", support_type, "`."), record_class = scalar_character(contract$name), field = "support_type", rule = "enum", observed_value = support_type, allowed_values = allowed)
    }
    invisible(support_type)
}

validate_graft_get_include.body:
{
    allowed <- c("identifiers", "claims", "evidence")
    if (!is.character(include) || anyNA(include) || !all(nzchar(include)) || anyDuplicated(include)) {
        abort_validation_error("`include` must contain unique related-data names.", field = "include", rule = "unique_supported_values", observed_value = include)
    }
    unknown <- setdiff(include, allowed)
    if (length(unknown) > 0L) {
        abort_validation_error(paste0("Unsupported `include` value(s): ", paste(unknown, collapse = ", "), "."), field = "include", rule = "supported_values", observed_value = unknown)
    }
    include
}

validate_graft_get_limits.body:
{
    defaults <- list(identifiers = 100L, claims = 50L, evidence = 100L)
    if (!is.list(limits) || (length(limits) > 0L && is.null(names(limits)))) {
        abort_limit_error("`limits` must be a named list.", argument = "limits", requested_limit = limits)
    }
    unknown <- setdiff(names(limits), names(defaults))
    if (length(unknown) > 0L || !all(nzchar(names(limits)))) {
        abort_limit_error(paste0("Unknown related-data limit(s): ", paste(unknown, collapse = ", "), "."), argument = "limits", requested_limit = limits)
    }
    defaults[names(limits)] <- limits
    defaults$identifiers <- validate_result_limit(defaults$identifiers, "limits$identifiers", graft_retrieval_limits$identifiers)
    defaults$claims <- validate_result_limit(defaults$claims, "limits$claims", graft_retrieval_limits$get_claims)
    defaults$evidence <- validate_result_limit(defaults$evidence, "limits$evidence", graft_retrieval_limits$get_evidence)
    defaults
}

validate_graft_include_superseded.body:
{
    if (!is.logical(include_superseded) || length(include_superseded) != 1L || is.na(include_superseded)) {
        abort_validation_error("`include_superseded` must be `TRUE` or `FALSE`.", field = "include_superseded", rule = "scalar_logical", observed_value = include_superseded)
    }
    include_superseded
}

validate_graft_integrity_store.body:
{
    validate_store_backend(store)
    if (!duckdb_table_exists(store$connection, "_graft_store")) {
        abort_backend_error("The GraftStore must be initialized by `graft_open()` before retrieval.", operation = "graft_retrieval_integrity", store_path = store$path)
    }
    invisible(store)
}

validate_graft_query_request.body:
{
    if (!is.list(request) || (length(request) > 0L && is.null(names(request)))) {
        abort_validation_error("`request` must be a named list.", field = "request", rule = "named_request", observed_value = request)
    }
    if (length(request) > 0L && (anyNA(names(request)) || !all(nzchar(names(request))) || anyDuplicated(names(request)))) {
        abort_validation_error("`request` names must be unique and non-empty.", field = "request", rule = "unique_request_names", observed_value = names(request))
    }
    request
}

validate_graft_retrieval.body:
{
    validate_retrieval_store(store)
    if (is_graft_snapshot_backend(store)) {
        return(invisible(store))
    }
    issues <- graft_retrieval_integrity(store, limit = 1L, projections = FALSE, deep = FALSE)
    if (nrow(issues) > 0L) {
        abort_backend_error("The authoritative revision ledger is not safe to retrieve.", operation = "graft_retrieval_integrity", issues = issues)
    }
    invisible(store)
}

validate_graft_schema_s7.body:
{
    state <- attr(self, ".state", exact = TRUE)
    if (!is.environment(state)) {
        return("internal schema state must be a private environment")
    }
    if (!identical(sort(ls(state)), sort(c("manifest_json", "path", "classes")))) {
        return("internal schema state fields are invalid")
    }
    if (!is_nonempty_string(state$manifest_json)) {
        return("internal manifest must be canonical JSON")
    }
    if (!is_optional_string(state$path)) {
        return("@path must be one string or missing")
    }
    if (identical(state$.validated_manifest_json, state$manifest_json) && identical(state$.validated_path, state$path) && identical(state$.validated_classes, state$classes)) {
        return(NULL)
    }
    manifest <- tryCatch(jsonlite::fromJSON(state$manifest_json, simplifyVector = FALSE), error = identity)
    if (inherits(manifest, "error")) {
        return("internal manifest must be valid JSON")
    }
    if (!identical(canonical_manifest_json(manifest), state$manifest_json)) {
        return("internal manifest JSON must be canonical")
    }
    compiled_schema <- new_compiled_schema(manifest, if (is.na(state$path)) 
        NULL
    else state$path)
    integrity_error <- tryCatch({
        validate_manifest_integrity(compiled_schema)
        NULL
    }, error = conditionMessage)
    if (!is.null(integrity_error)) {
        return("internal manifest failed integrity validation")
    }
    expected <- tryCatch(graft_class_contracts(manifest), error = identity)
    if (inherits(expected, "error") || !identical(state$classes, expected)) {
        return("@classes does not match the compiled manifest")
    }
    state$.validated_manifest_json <- state$manifest_json
    state$.validated_path <- state$path
    state$.validated_classes <- state$classes
    NULL
}

validate_graft_store_s7.body:
{
    state <- attr(self, ".state", exact = TRUE)
    if (!is.environment(state)) {
        return("internal store state must be a private environment")
    }
    if (!identical(sort(ls(state)), sort(c("backend", "schema", "id", "id_digest")))) {
        return("internal store state fields are invalid")
    }
    if (!is_nonempty_string(state$id)) {
        return("@id must be one non-empty string")
    }
    if (!is_graft_digest(state$id_digest) || !identical(state$id_digest, graft_sha256(canonical_json(state$id)))) {
        return("@id does not match its immutable identity digest")
    }
    if (!S7::S7_inherits(state$schema, GraftSchema)) {
        return("@schema must be a GraftSchema object")
    }
    schema_error <- tryCatch({
        S7::validate(state$schema)
        NULL
    }, error = conditionMessage)
    if (!is.null(schema_error)) {
        return("@schema is invalid")
    }
    backend <- state$backend
    if (!is_store_backend(backend)) {
        return("internal store state must contain a connection backend")
    }
    store_error <- tryCatch({
        validate_store_backend(backend, require_open = FALSE)
        NULL
    }, error = conditionMessage)
    if (!is.null(store_error)) {
        return("internal store backend is invalid")
    }
    if (!is_scalar_flag(backend$read_only) || !is_scalar_flag(backend$owns_connection) || !is_scalar_flag(backend$closed) || !is_nonempty_string(backend$path)) {
        return("internal store lifecycle fields are invalid")
    }
    expected_capabilities <- duckdb_capabilities(backend$read_only, backend$owns_connection)
    if (!identical(backend$capabilities, expected_capabilities)) {
        return("@capabilities does not match the connection lifecycle")
    }
    compiled_schema <- tryCatch({
        validate_manifest_integrity(backend$schema)
        backend$schema
    }, error = identity)
    if (inherits(compiled_schema, "error")) {
        return("internal store schema is invalid")
    }
    if (!identical(canonical_manifest_json(compiled_schema$manifest), graft_schema_state(state$schema)$manifest_json)) {
        return("@schema does not match the store schema")
    }
    if (!isTRUE(backend$closed)) {
        metadata <- tryCatch(read_store_metadata(backend$connection), error = identity)
        if (inherits(metadata, "error") || !identical(state$id, scalar_character(metadata$store_id))) {
            return("@id does not match the initialized store")
        }
    }
    NULL
}

validate_graft_view_s7.body:
{
    state <- graft_view_state(self)
    if (!is.list(state) || is.object(state) || !identical(names(state), c("store", "snapshot", "schema"))) {
        return("internal view state is invalid")
    }
    if (!S7::S7_inherits(state$store, GraftStore)) {
        return("internal view store must be a GraftStore object")
    }
    store_error <- tryCatch({
        S7::validate(state$store)
        NULL
    }, error = conditionMessage)
    if (!is.null(store_error)) {
        return("internal view store is invalid")
    }
    if (!S7::S7_inherits(state$snapshot, GraftSnapshot)) {
        return("internal view snapshot must be a GraftSnapshot object")
    }
    snapshot_problem <- snapshot_validation_problem(snapshot_data(state$snapshot))
    if (!is.null(snapshot_problem)) {
        return("internal view snapshot is invalid")
    }
    store_id <- tryCatch(state$store@id, error = function(.x) NA_character_)
    if (!is_nonempty_string(store_id)) {
        return("internal view store identity is invalid")
    }
    if (!identical(state$snapshot@store_id, store_id)) {
        return("internal view snapshot does not match the store")
    }
    if (!is_compiled_schema(state$schema)) {
        return("internal view schema must be a compiled schema")
    }
    build_digest <- scalar_character(state$schema$manifest$fingerprints$build_digest)
    if (!identical(build_digest, state$snapshot@schema_build_digest)) {
        return("internal view schema does not match the snapshot")
    }
    NULL
}

