validate_manifest_dictionary_header.body:
{
    dictionary <- manifest$dictionary
    compiler <- manifest$compiler
    provider <- if (is.list(compiler) && !is.object(compiler)) {
        compiler$provider
    }
    else {
        NULL
    }
    if (is.null(dictionary)) {
        if (!is.null(provider) || (is.list(compiler) && identical(compiler$name, "graft-data-dict-adapter"))) {
            abort_schema_error(paste("A data-dict compiler or provider requires a matching dictionary", "extension."), manifest_path = path, field = "dictionary", rule = "dictionary_provider_contract")
        }
        return(invisible(manifest))
    }
    required <- c("provider", "document", "profile", "defaults", "adapter_version", "requirements", "mapped", "preserved", "not_enforced")
    if (!is.list(dictionary) || is.object(dictionary)) {
        abort_schema_error("The dictionary extension must be an object.", manifest_path = path, field = "dictionary", rule = "dictionary_extension_contract")
    }
    missing <- setdiff(required, names(dictionary))
    unexpected <- setdiff(names(dictionary), required)
    if (length(missing) > 0L || length(unexpected) > 0L) {
        abort_schema_error("The dictionary extension has invalid fields.", manifest_path = path, field = "dictionary", rule = "dictionary_extension_contract", missing_fields = missing, unexpected_fields = unexpected)
    }
    if (!is.list(compiler) || is.object(compiler) || !setequal(names(compiler), c("name", "version", "script_digest", "provider")) || !is_graft_digest(compiler$script_digest) || !identical(compiler$script_digest, data_dict_adapter_script_digest())) {
        abort_schema_error("The compiler metadata is invalid for a data-dict manifest.", manifest_path = path, field = "compiler", rule = "dictionary_compiler_contract")
    }
    validate_data_dict_provider_header(provider, path)
    if (!identical(dictionary$provider, provider)) {
        abort_schema_error("Dictionary and compiler provider metadata must be identical.", manifest_path = path, field = "dictionary.provider", rule = "dictionary_provider_contract")
    }
    if (!identical(compiler$name, "graft-data-dict-adapter") || !identical(compiler$version, dictionary$adapter_version)) {
        abort_schema_error("The compiler metadata does not match the data-dict adapter.", manifest_path = path, field = "compiler", rule = "dictionary_compiler_contract", expected_name = "graft-data-dict-adapter", expected_version = dictionary$adapter_version, observed_name = compiler$name, observed_version = compiler$version)
    }
    if (!is.list(dictionary$document) || is.object(dictionary$document) || !identical(dictionary$profile, "graft-table-v1") || !is_nonempty_string(dictionary$adapter_version) || !is.list(dictionary$requirements) || length(dictionary$requirements) == 0L || !all(vapply(dictionary$requirements, is_nonempty_string, logical(1))) || !is.list(dictionary$preserved) || !all(vapply(dictionary$preserved, is_nonempty_string, logical(1))) || !data_dict_mapped_contract_is_valid(dictionary$mapped) || !is.list(dictionary$not_enforced) || 
        length(dictionary$not_enforced) == 0L) {
        abort_schema_error("The dictionary extension has invalid contract metadata.", manifest_path = path, field = "dictionary", rule = "dictionary_extension_contract")
    }
    document_version <- dictionary$document[["$version"]]
    if (!identical(document_version, provider$export_format_version)) {
        abort_schema_error(paste("The public data-dict document version must match the provider", "export-format version."), manifest_path = path, field = "dictionary.document.$version", rule = "dictionary_export_format_version", observed_value = document_version, expected_value = provider$export_format_version)
    }
    tryCatch(data_dict_validate_root(dictionary$document), graft_schema_error = function(error) {
        abort_schema_error(paste0("The public data-dict document is invalid: ", conditionMessage(error)), manifest_path = path, field = "dictionary.document", rule = "dictionary_public_document_contract", parent = error)
    })
    sanitized_document <- tryCatch(data_dict_public_document(dictionary$document), error = function(error) NULL)
    if (is.null(sanitized_document) || !identical(sanitized_document, dictionary$document)) {
        abort_schema_error("The public data-dict document contains redacted provider fields.", manifest_path = path, field = "dictionary.document", rule = "dictionary_public_document_contract")
    }
    if (!identical(dictionary$adapter_version, data_dict_adapter_version)) {
        abort_schema_error(paste0("The data-dict adapter version `", dictionary$adapter_version, "` is not supported."), manifest_path = path, field = "dictionary.adapter_version", rule = "supported_data_dict_adapter_version", observed_value = dictionary$adapter_version, supported_value = data_dict_adapter_version)
    }
    validate_data_dict_projection_contract(manifest, path)
    defaults <- dictionary$defaults
    if (!is.list(defaults) || !setequal(names(defaults), c("role", "id_policy", "id_format")) || !identical(defaults$role, "node") || !identical(defaults$id_policy, "require") || !identical(defaults$id_format, "linkml") || !all(vapply(dictionary$not_enforced, data_dict_loss_is_valid, logical(1)))) {
        abort_schema_error("The dictionary extension has invalid defaults or loss metadata.", manifest_path = path, field = "dictionary", rule = "dictionary_extension_contract")
    }
    invisible(manifest)
}

validate_manifest_header.body:
{
    duplicate <- duplicate_json_object_key(manifest)
    if (!is.null(duplicate)) {
        abort_schema_error(paste0("Schema manifest `", path, "` contains duplicate JSON object key `", duplicate$key, "`."), manifest_path = path, field = duplicate$path, rule = "duplicate_json_key")
    }
