    }
    unexpected <- setdiff(names(manifest), c(required, "dictionary"))
    if (length(unexpected) > 0L) {
        abort_schema_error(paste0("Schema manifest `", path, "` has unexpected field(s): ", paste(unexpected, collapse = ", "), "."), manifest_path = path, unexpected_fields = unexpected, rule = "manifest_fields")
    }
