    if (!identical(manifest$manifest_version, graft_manifest_version)) {
        abort_schema_error(paste0("Schema manifest `", path, "` uses unsupported manifest version `", manifest$manifest_version, "`."), manifest_path = path, field = "manifest_version", rule = "supported_manifest_version", observed_value = manifest$manifest_version, supported_value = graft_manifest_version)
    }
    if (!identical(manifest$projection_mapping_version, graft_projection_mapping_version)) {
        abort_schema_error(paste0("Schema manifest `", path, "` uses unsupported projection mapping version `", manifest$projection_mapping_version, "`."), manifest_path = path, field = "projection_mapping_version", rule = "supported_projection_mapping_version", observed_value = manifest$projection_mapping_version, supported_value = graft_projection_mapping_version)
    }
    validate_manifest_dictionary_header(manifest, path)
    digests <- manifest$fingerprints
    required_digests <- c("structural_digest", "source_digest", "build_digest")
    missing_digests <- setdiff(required_digests, names(digests))
    if (length(missing_digests) > 0L) {
        abort_schema_error(paste0("Schema manifest `", path, "` is missing fingerprint(s): ", paste(missing_digests, collapse = ", "), "."), manifest_path = path, missing_fingerprints = missing_digests)
    }
    unexpected_digests <- setdiff(names(digests), required_digests)
    if (length(unexpected_digests) > 0L) {
        abort_schema_error(paste0("Schema manifest `", path, "` has unexpected fingerprint(s): ", paste(unexpected_digests, collapse = ", "), "."), manifest_path = path, unexpected_fingerprints = unexpected_digests, rule = "manifest_fingerprints")
    }
    invisible(manifest)
}

validate_manifest_integrity.body:
{
    if (!is_compiled_schema(schema)) {
        abort_schema_integrity("Schema integrity validation requires a compiled schema.", subclass = subclass)
    }
    manifest <- schema$manifest
    manifest_hash <- rlang::hash(manifest)
    if (isTRUE(validated_manifest_hashes[[manifest_hash]])) {
        return(invisible(schema))
    }
    duplicate <- duplicate_json_object_key(manifest)
    if (!is.null(duplicate)) {
        abort_schema_integrity(paste0("The schema manifest contains duplicate JSON object key `", duplicate$key, "`."), field = duplicate$path, rule = "duplicate_json_key", subclass = subclass)
    }
    validate_manifest_shape(manifest, path = schema$path, integrity = TRUE, subclass = subclass)
    fingerprints <- manifest$fingerprints
    fingerprint_names <- c("structural_digest", "source_digest", "build_digest")
    invalid_fingerprints <- fingerprint_names[!vapply(fingerprints[fingerprint_names], function(.x) {
        value <- scalar_character(.x)
        !is.na(value) && grepl("^sha256:[0-9a-f]{64}$", value)
    }, logical(1))]
    if (length(invalid_fingerprints) > 0L) {
        abort_schema_integrity(paste0("Schema fingerprint(s) are not canonical SHA-256 digests: ", paste(invalid_fingerprints, collapse = ", "), "."), invalid_fingerprints = invalid_fingerprints, rule = "canonical_schema_fingerprints", subclass = subclass)
    }
    declared_digest <- scalar_character(fingerprints$structural_digest)
    computed_digest <- manifest_structural_digest(manifest)
    if (!identical(declared_digest, computed_digest)) {
        abort_schema_integrity(paste0("The declared structural digest does not match the manifest ", "content."), declared_structural_digest = declared_digest, computed_structural_digest = computed_digest, rule = "structural_digest_content_mismatch", subclass = subclass)
    }
    validate_global_slot_types(manifest, subclass)
    validate_manifest_projection_contracts(manifest, subclass)
    declared_build_digest <- scalar_character(fingerprints$build_digest)
    computed_build_digest <- manifest_build_digest(manifest)
    if (!identical(declared_build_digest, computed_build_digest)) {
        abort_schema_integrity("The declared build digest does not match the manifest content.", declared_build_digest = declared_build_digest, computed_build_digest = computed_build_digest, rule = "build_digest_content_mismatch", subclass = subclass)
    }
    validated_manifest_hashes[[manifest_hash]] <- TRUE
    invisible(schema)
}

validate_manifest_projection_contracts.body:
{
    class_names <- names(manifest$classes)
    expected_relations <- character()
    projection_names <- character()
    for (record_class in class_names) {
        contract <- manifest$classes[[record_class]]
        view <- scalar_character(contract$view)
        if (!identical(scalar_character(contract$name), record_class) || is.na(view) || !nzchar(trimws(view))) {
            abort_schema_integrity(paste0("Class `", record_class, "` has invalid projection metadata."), record_class = record_class, rule = "class_projection_metadata", subclass = subclass)
        }
        projection_names <- c(projection_names, view)
        slots <- contract$slots
        for (slot_name in names(slots)) {
            slot <- slots[[slot_name]]
            if (!identical(scalar_character(slot$name), slot_name)) {
                abort_schema_integrity(paste0("Slot `", record_class, ".", slot_name, "` name must match its manifest key."), record_class = record_class, slot = slot_name, declared_name = scalar_character(slot$name), rule = "slot_name_contract", subclass = subclass)
            }
            validate_compiler_slot_type(slot, slot_name, record_class, subclass)
        }
        scalar_slots <- Filter(function(.x) !scalar_logical(.x$multivalued), slots)
        view_columns <- vapply(scalar_slots, function(.x) scalar_character(.x$view_column), character(1))
        if (anyNA(view_columns) || !all(nzchar(trimws(view_columns))) || anyDuplicated(tolower(view_columns))) {
            abort_schema_integrity(paste0("Scalar slots for class `", record_class, "` must use unique projection columns."), record_class = record_class, rule = "unique_projection_columns", subclass = subclass)
        }
        multivalue_slots <- Filter(function(.x) scalar_logical(.x$multivalued), slots)
        relation_names <- character()
        for (slot_name in names(multivalue_slots)) {
            relation <- validate_manifest_relation_contract(manifest, record_class, slot_name, subclass)
            relation_names <- c(relation_names, scalar_character(relation$name))
            projection_names <- c(projection_names, scalar_character(relation$view))
        }
        declared_relations <- empty_character(contract$relations)
        if (anyDuplicated(declared_relations) || !setequal(declared_relations, relation_names)) {
            abort_schema_integrity(paste0("Class `", record_class, "` relation metadata does not match its multivalued slots."), record_class = record_class, rule = "class_relation_correspondence", subclass = subclass)
        }
        expected_relations <- c(expected_relations, relation_names)
    }
    observed_relations <- vapply(manifest$relations, function(.x) scalar_character(.x$name), character(1))
    if (anyNA(observed_relations) || anyDuplicated(observed_relations) || !setequal(observed_relations, expected_relations)) {
        abort_schema_integrity("Generated relations must correspond exactly to multivalued slots.", expected_relations = sort(expected_relations), observed_relations = sort(observed_relations), rule = "generated_relation_correspondence", subclass = subclass)
    }
    invalid_projection_names <- is.na(projection_names) | !nzchar(trimws(projection_names)) | startsWith(tolower(projection_names), "_graft_")
    if (any(invalid_projection_names) || anyDuplicated(tolower(projection_names))) {
        abort_schema_integrity("Class and relation projection names must be valid and unique.", projection_names = projection_names, rule = "unique_projection_names", subclass = subclass)
    }
    invisible(manifest)
}

validate_manifest_relation_contract.body:
{
    contract <- manifest$classes[[record_class]]
    slot <- contract$slots[[slot_name]]
    matches <- Filter(function(.x) {
        identical(scalar_character(.x$owner_class), record_class) && identical(scalar_character(.x$slot), slot_name)
    }, manifest$relations)
    if (length(matches) != 1L) {
        abort_schema_integrity("A multivalued slot must have exactly one generated relation.", record_class = record_class, slot = slot_name, relation_count = length(matches), rule = "generated_relation_count", subclass = subclass)
    }
    relation <- matches[[1L]]
    object_reference <- scalar_logical(slot$object_reference)
    kind <- if (object_reference) 
        "object"
    else "value"
    predicate <- scalar_character(relation$predicate)
    valid <- identical(scalar_character(slot$name), slot_name) && is.null(slot$view_column) && scalar_logical(slot$multivalued) && !scalar_logical(slot$identifier) && setequal(names(relation), c("name", "view", "owner_class", "owner_view", "slot", "kind", "ordered", "predicate")) && identical(scalar_character(relation$name), paste(record_class, slot_name, sep = ".")) && identical(scalar_character(relation$owner_view), scalar_character(contract$view)) && identical(scalar_character(relation$view), 
        paste0(contract$view, "__", projection_snake_case(slot_name))) && identical(scalar_character(relation$kind), kind) && identical(scalar_logical(relation$ordered), scalar_logical(slot$ordered)) && !is.na(predicate) && nzchar(trimws(predicate))
    if (!valid) {
        abort_schema_integrity(paste0("Generated relation `", record_class, ".", slot_name, "` does not match the compiler contract."), record_class = record_class, slot = slot_name, relation = scalar_character(relation$name), rule = "generated_relation_contract", subclass = subclass)
    }
    invisible(relation)
}

validate_manifest_shape.body:
