validate_projection_head_integrity.body:
{
    head <- quote_identifier(connection, "_graft_record_heads")
    revision <- quote_identifier(connection, "_graft_record_revisions")
    invalid <- DBI::dbGetQuery(connection, paste0("SELECT h.record_id, h.class, h.revision_id, ", "CAST(h.revision_number AS VARCHAR) AS revision_number, ", "COUNT(r.revision_id) AS matching_revision_count FROM ", head, " AS h LEFT JOIN ", revision, " AS r ON h.record_id = r.record_id AND h.class = r.class ", "AND h.revision_id = r.revision_id ", "AND h.revision_number = r.revision_number ", "GROUP BY h.record_id, h.class, h.revision_id, h.revision_number ", "HAVING COUNT(r.revision_id) <> 1 ORDER BY h.class, h.record_id"))
