validate_resolved_data_dict.body:
{
    invalid <- character()
    if (!is.list(document) || is.data.frame(document)) {
        invalid <- "document"
    }
    else {
        if (!"$version" %in% names(document)) {
            invalid <- c(invalid, "$version (missing)")
        }
        else if (!data_dict_is_scalar_text(document[["$version"]])) {
