validate_snapshot_store_mapping.body:
{
    observed_store_id <- scalar_character(row$store_id)
    observed_format <- scalar_character(row$store_format_version)
    observed_history <- if (length(row$history_complete) == 0L) {
        NA
    }
    else {
        row$history_complete[[1L]]
    }
    if (!identical(observed_store_id, data$store_id)) {
        abort_snapshot_error("graft_snapshot_store_mismatch", "The snapshot belongs to a different Graft store.", expected_store_id = data$store_id, observed_store_id = observed_store_id)
    }
    if (!identical(observed_format, data$store_format_version) || !identical(observed_history, data$history_complete)) {
        abort_snapshot_error("graft_snapshot_store_mismatch", "The store format or history coverage does not match the snapshot.", expected_store_format_version = data$store_format_version, observed_store_format_version = observed_format, expected_history_complete = data$history_complete, observed_history_complete = observed_history)
    }
    latest <- if (length(row$latest_commit_order) == 0L || is.na(row$latest_commit_order[[1L]])) {
        0
    }
    else {
        as.numeric(row$latest_commit_order[[1L]])
    }
    if (data$commit_order > latest) {
        abort_snapshot_error("graft_snapshot_boundary_error", "The snapshot boundary is newer than the current store.", snapshot_commit_order = data$commit_order, latest_commit_order = latest)
    }
    if (identical(data$commit_order, 0)) {
        return(invisible(data))
    }
    observed_batch <- scalar_character(row$boundary_batch_id)
    observed_time <- snapshot_timestamp(row$boundary_committed_at)
    if (!identical(observed_batch, data$batch_id) || !identical(observed_time, data$committed_at)) {
        abort_snapshot_error("graft_snapshot_boundary_error", "The snapshot boundary does not match its committed batch.", snapshot_commit_order = data$commit_order, expected_batch_id = data$batch_id, observed_batch_id = observed_batch, expected_committed_at = data$committed_at, observed_committed_at = observed_time)
    }
    invisible(data)
}

validate_store_backend.body:
{
    if (!is_store_backend(store)) {
        abort_backend_error(paste0("`", arg, "` has invalid internal store state."), operation = "validate_store", argument = arg)
    }
    if (!isTRUE(store$closed) && !isTRUE(tryCatch(DBI::dbIsValid(store$connection), error = function(.x) FALSE))) {
        store$closed <- TRUE
    }
    if (isTRUE(require_open) && isTRUE(store$closed)) {
        abort_backend_error("The GraftStore is closed.", operation = "validate_store", store_path = store$path)
    }
    invisible(store)
}

validate_store_path.body:
{
    if (!is.character(path) || length(path) != 1L || is.na(path) || !nzchar(path)) {
        abort_backend_error("`path` must be one non-empty DuckDB path.", operation = "connect", argument = "path")
    }
    invisible(path)
}

validate_store_writable.body:
{
    validate_store_backend(store)
    if (isTRUE(store$read_only)) {
        abort_backend_error(paste0("A read-only store cannot perform `", operation, "`."), operation = operation, store_path = store$path)
    }
    invisible(store)
}

validated_public_revision_record.body:
{
    payload <- tryCatch(parse_revision_payload(payload_json), error = identity)
    if (inherits(payload, "error")) {
        abort_backend_error("A selected revision payload is not valid canonical JSON.", operation = "graft_retrieval", record_id = record_id, revision_id = revision_id, parent = payload)
    }
    canonical <- tryCatch(canonical_manifest_payload(payload, contract), error = identity)
    if (inherits(canonical, "error") || !identical(logical_record_content_digest(canonical), content_digest)) {
        abort_backend_error("A selected revision payload does not match its content digest.", operation = "graft_retrieval", record_id = record_id, revision_id = revision_id, parent = if (inherits(canonical, "error")) 
            canonical
        else NULL)
    }
    public_revision_record(payload_json, contract)
}

validation_slot_type.body:
{
    type <- toupper(scalar_character(slot$duckdb_type, "VARCHAR"))
    if (scalar_logical(slot$object_reference) && !identical(type, "VARCHAR")) {
        abort_schema_error("Object-reference fields must use DuckDB type `VARCHAR`.", field = scalar_character(slot$name), rule = "object_reference_varchar", duckdb_type = type)
    }
    type
}

verify_graph_views.body:
{
    missing <- graft_graph_view_names[!vapply(graft_graph_view_names, function(.x) duckdb_table_exists(connection, .x), logical(1))]
    if (length(missing) > 0L) {
        abort_backend_error(paste0("The initialized read-only store is missing generated graph view(s): ", paste(missing, collapse = ", "), ". Reopen it as a writable GraftStore."), operation = "verify_graph_views", missing_views = missing)
    }
    invisible(connection)
}

verify_initialized_store.body:
{
    metadata <- read_store_metadata(store$connection)
    verify_store_format(metadata)
    verify_metadata_structure(store$connection)
    old_schema <- compiled_schema_from_json(metadata$manifest_json)
    validate_manifest_integrity(old_schema)
    validate_manifest_integrity(store$schema)
    compatibility <- schema_compatibility(old_schema, store$schema)
    if (!isTRUE(compatibility$compatible)) {
        abort_schema_mismatch(compatibility)
    }
    active_build_digest <- scalar_character(metadata$active_build_digest)
    registry <- read_schema_version(store$connection, active_build_digest)
    if (nrow(registry) != 1L || !identical(registry$manifest_json[[1L]], metadata$manifest_json)) {
        abort_backend_error("The active schema metadata does not match its schema registry entry.", operation = "verify_store", build_digest = active_build_digest)
    }
    build_digest <- scalar_character(store$schema$manifest$fingerprints$build_digest)
    if (!identical(active_build_digest, build_digest) && isTRUE(activate) && !isTRUE(store$read_only)) {
        activate_schema(store$connection, store$schema)
    }
    invisible(store)
}

verify_metadata_structure.body:
{
    definitions <- metadata_table_definitions()
    available <- duckdb_table_names(connection)
    missing <- setdiff(names(definitions), available)
    if (length(missing) > 0L) {
        abort_backend_error(paste0("The initialized store is missing required metadata table(s): ", paste(missing, collapse = ", "), "."), operation = "verify_store", missing_tables = missing)
    }
    for (table in names(definitions)) {
        expected <- vapply(definitions[[table]]$columns, function(.x) scalar_character(.x$name), character(1))
        observed <- DBI::dbListFields(connection, table)
        missing_columns <- setdiff(expected, observed)
        if (length(missing_columns) > 0L) {
            abort_backend_error(paste0("Metadata table `", table, "` is missing required column(s): ", paste(missing_columns, collapse = ", "), "."), operation = "verify_store", table = table, missing_columns = missing_columns)
        }
    }
    invisible(connection)
}

verify_projection_state.body:
{
    expected_columns <- c("state_id", "schema_build_digest", "head_source_digest", "cache_digest", "object_digest", "rebuilt_at")
    missing_columns <- setdiff(expected_columns, DBI::dbListFields(connection, graft_projection_metadata_table_names))
    if (length(missing_columns) > 0L) {
        abort_backend_error(paste0("The derived projection state is missing column(s): ", paste(missing_columns, collapse = ", "), ". Reopen the store writable with `graft_open()`."), operation = "verify_projection_state", missing_columns = missing_columns)
    }
    state <- DBI::dbReadTable(connection, graft_projection_metadata_table_names)
    if (nrow(state) != 1L || !identical(state$state_id[[1L]], graft_projection_state_id)) {
        abort_backend_error(paste0("The derived projection state must contain exactly one active row; ", "found ", nrow(state), ". Reopen the store writable with `graft_open()`."), operation = "verify_projection_state", row_count = nrow(state))
    }
    expected <- projection_state_values(connection, schema)
    fields <- names(expected)
    stale <- fields[vapply(fields, function(field) !identical(state[[field]][[1L]], expected[[field]]), logical(1))]
    if (length(stale) > 0L) {
        abort_backend_error(paste0("The generated projections are stale or altered in: ", paste(stale, collapse = ", "), ". Reopen the store writable with `graft_open()`."), operation = "verify_projection_state", stale_fields = stale)
    }
    invisible(connection)
}

verify_projection_views.body:
{
    validate_projection_head_integrity(connection)
    expected <- c(stats::setNames(rep("VIEW", length(generated_projection_view_names(schema))), generated_projection_view_names(schema)), stats::setNames(rep("BASE TABLE", length(generated_projection_table_names(schema))), generated_projection_table_names(schema)), stats::setNames(rep("BASE TABLE", length(graft_projection_metadata_table_names)), graft_projection_metadata_table_names))
    catalog <- projection_object_catalog(connection)
    observed <- stats::setNames(catalog$table_type, catalog$table_name)
    invalid <- names(expected)[is.na(observed[names(expected)]) | observed[names(expected)] != expected]
    if (length(invalid) > 0L) {
        details <- vapply(invalid, function(name) {
            type <- observed[[name]]
            if (is.null(type) || is.na(type)) {
                type <- "missing"
            }
            paste0(name, " (expected ", expected[[name]], ", found ", type, ")")
        }, character(1))
        abort_backend_error(paste0("The initialized read-only store has invalid generated projection ", "object(s): ", paste(details, collapse = ", "), ". Reopen it writable with `graft_open()`."), operation = "verify_projection_views", invalid_projections = invalid)
    }
    verify_projection_state(connection, schema)
    invisible(connection)
}

verify_store_format.body:
{
    observed <- scalar_character(metadata$store_format_version)
    if (!identical(observed, graft_store_format_version)) {
        graft_abort("graft_store_format_error", paste0("Unsupported graft store format `", observed, "`; this version requires `", graft_store_format_version, "`."), observed_version = observed, supported_version = graft_store_format_version)
    }
    invisible(metadata)
}

with_duckdb_error.body:
{
    tryCatch(code, error = function(error) {
        if (inherits(error, "graft_error")) {
            stop(error)
        }
        abort_backend_error(paste0("DuckDB operation `", operation, "` failed: ", conditionMessage(error)), operation = operation, parent = error)
    })
}

write_data_dict_source_snapshot.body:
{
    directory <- tempfile("graft-data-dict-source-")
    if (!dir.create(directory)) {
        abort_schema_error("Could not create a temporary data-dict source snapshot.", schema_path = source_path)
    }
    complete <- FALSE
    on.exit(if (!complete) unlink(directory, recursive = TRUE), add = TRUE)
    path <- file.path(directory, basename(source_path))
    connection <- tryCatch(file(path, open = "wb"), error = function(error) {
        abort_schema_error("Could not create a temporary data-dict source snapshot.", schema_path = source_path, parent = error)
    })
    connection_open <- TRUE
    on.exit(if (connection_open) close(connection), add = TRUE)
    tryCatch(writeBin(bytes, connection), error = function(error) {
        abort_schema_error("Could not write a temporary data-dict source snapshot.", schema_path = source_path, parent = error)
    })
    close(connection)
    connection_open <- FALSE
    complete <- TRUE
    list(path = path, directory = directory)
}
